/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20101104-4","meetingId":"h22-c-settlement","date":"2010年11月4日","dateIso":"2010-11-04","committee":"決算特別委員会","time":"午前１０時０２分～午後５時４６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を152件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"そういった中で、品川区といたしましては、自立を目的に取り組む母親のためのパソコン教室事業といったものを行っていただいて、そういった形でいろいろと手助けをしていただいているといった取り組みをしていただいておりますけれども、それでまずお伺いしたいのが、平成２１年度、１６９名のパソコン教室に参加をされている方が、この決算書に出ておりますけれども、この方々のその後。","respondent":"安井子育て支援課長","answer":"パソコン教室ですけれども、こちらは比較的初級のウィンドウズから、それこそワード、エクセルといった初級のものを中心に行っているものと、それから中級コースということで、ホームページですとか、そういったものを勉強していただくというようなコースに分かれておりまして。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"基本的なところを教えていただいているというところなんですが、やはりこのパソコン事業を自分のいわゆる仕事の一つとして取り入れたいという希望のもと、そうやって受けられている方がいらっしゃるわけですよね。平成２１年度１６９名。そういったところで、やっぱり就職の受け皿というか、そういうところを確保するといった意味で、もう一度その辺をどうお考えになっているのかお聞かせください。","respondent":"安井子育て支援課長","answer":"ということで、私どもとしては、そういった資格を身につけていただいた上で、さらに自立支援プログラムを作成して行っていくです。自立支援プログラムにつきましては、策定が４８件とこちらにありますけれども、４０件就職のほうが決まっているという形で実施しています。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"そんなようなお話を、これもやはり母子寡婦の方々からお伺いをして、こういう事業が今年度行われているんだというようなことを我々自民党でも認識をしたところなんですけれども、そういった意味で、今後のいわゆる在宅での就労といったところ、これは今年度そうやって国も方針を出しているといった中で、区はどのような形で在宅の就労に関してお考えで。","respondent":"安井子育て支援課長","answer":"品川区でのこういった在宅就労についての検討もさせていただいたんですけれども、なかなかパソコン教室も２０人とかそのくらいのレベルで、これはご希望者については定員２０名となっているんですけれども、希望された方は全員ということで、実際上は初級が２２名。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"国も在宅での就労の考え方といったものをそういった形で示しているといったことで、やはりこれは何としてもダブルワークにならないといったところをもう一度そのあたりを区のほうでも認識をしていただいて、何かあれば取り組みをしていただきたいなということで、この質問は終わります。今後の５年といったもの、勝負どきといったこの表現の内容というか、どういうことなのかお聞かせをいただきたい。","respondent":"吉岡保育課長","answer":"区としては今お話があった認定こども園３園、それからあと幼保一体施設も今年第一日野が開設しまして３園目になったわけですけれども、そういう形で幼稚園の保育・教育、それから保育園での保育・教育をどのように連携し統合していくのかという検討を進めているわけで。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問・要望","question":"今年の４月から義務化がスタートするといったことで、平成２１年度の予算のもと、さまざまな取り組みをしていただき、３,４２６世帯にこの品川区独自の制度を使っていただいて設置をしていただいたということでありますけれども、３,４２６世帯、いわゆる対象の世帯数が何軒あって、その率というか、活用率といったものをお伺いさせていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"この３,４２６件は、ひとり暮らし高齢者と高齢者世帯を中心にということで、民生委員が回っているのが七、八千件ですので、かなり高い率はつけていただいているというような感じがいたします。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"私からは成果報告書の１３０ページ、社会福祉費、社会福祉総務費の民生委員経費、１３４ページ、同じく社会福祉費の障害者福祉費の自立支援サービスと１３５ページにかけまして、生活支援サービス全般にわたって、その中で障害児のタイムケア事業、また発達障害者に関連して、さらにその関連として３６ページの障害者就労支援事業の内容についてお伺いします。","respondent":"冨岡高齢者福祉課長","answer":"研修の関係ですけれども、研修につきましては、新任の時点で１回研修を受けると同時に、東京都民生児童委員連合会でもいろいろ研修等をやってありますので、一定時期が過ぎましてから研修をお受けになっているということと、毎月の協議会において。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"といいますのは、やはり個人情報を例えばほかの人に話しているとか、また本来あってはならないんでしょうけれども、道端で相談事を受け付けているような、そのような場面に出くわした方から、ちょっといかがなものかという話も伺っていますので、この件につきましては、特に信頼関係、信用関係にもなりますので、個人情報保護と守秘義務についてはしっかりと研修をやっていただければと思いますが。","respondent":"冨岡高齢者福祉課長","answer":"民生委員のお立場で、お話をされていると、その方が何か民生委員とかかわりがあるのか、要援護者なのかというのはこの辺は難しい状況というのがありますので、そういうのも配慮しながら個人の秘密は守るように十分にお伝えしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"続きまして、障害児タイムケア事業ですけれども、一昨年が２,２７３回で、前年の３,３９９回、それが今年度２,７９６回ということで、かなり浮沈が激しいかなと思いますけれども、今年度、平成２１年度が減少した主な要因はどこにあるのかということを１点お伺いします。区のほうで何か指示があって動いているとか、情報を得ているものがありましたら、この３点についてお願いいたします。","respondent":"永尾障害者福祉課長","answer":"３点目の療育手帳の交付についてです。こちらについては、東京都の愛の手帳で療育手帳というのをやっております。対象に含めるかについてはかなり意見が分かれているところで、東京都のほうも慎重な対応をしているという段階です。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"都立品川特別支援学校ですけれども、二、三年かけて保護者を母体としてつくっていくということで、お子様方は待ったなしというような状況になるかと思いますけれども、一日も早く何らかの形で安心して通学ですか、品川区内ですので、できる環境、ぜひともウォッチをしていただければと、そのように思います。３点目です。","respondent":"永尾障害者福祉課長","answer":"こちらの人数につきましては、すべて延べ人数でやっております。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと話はそれに関連しますけれども、障害者自立支援法に基づきまして、障害者の施設の新体系の移行というのが今も進んでいるかと思いますけれども、今まで父兄の方々ですとか、ご本人に対しまして説明会をかなり実施されていると伺っております。これについての反響などがございましたら、簡単で結構ですので教えてください。","respondent":"永尾障害者福祉課長","answer":"今後につきましても、それぞれの施設の特色、特長を十分に丁寧に説明して、一人ひとり丁寧な対応をしていきたいというふうに考えております。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"この区民健診が過去には２０％程度だったということですけれども、区民の健康という観点からいうと、特定健診とあと区のほうでのさまざまながん検診とか健康課のほうですか、あるかと思いますけれども、総合的に、縦割ではなくして、横から見て、区民の健康を本当に考えていく、基本的なところを考えていくのは課としてはどちらに役目があるのかということについてお伺いします。","respondent":"本城国保医療年金課長","answer":"そういったところも踏まえて、これからの対応といたしましては、受診へのＰＲと受診しやすい環境づくりがとても大切だと考えているところです。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"１９０ページにあります国保事業、それから２１４ページの後期高齢者医療についてお聞きをしてまいりたいというふうに思います。国保のほうですけれども、平成２１年度で１９万１,０００世帯余りの方が加入をしているということなんですけれども、ここでの滞納世帯、それから資格証、短期証の発行なんかもあれば、その辺を教えていただきたいというふうに思います。","respondent":"本城国保医療年金課長","answer":"資格証の世帯ですが、現時点で１４１世帯が資格証を受給しています。それから、後期高齢者医療のほうの滞納されている方の状況ですが、平成２０年度、平成２１年度を含めまして、現在で直近では１,１２９世帯の方が滞納されている状況です。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"今年度改正をされましたけれども、減免、減額の相談件数、その辺の数字とそれから均等割が３５％未満の場合は５割、３割の減額ができる。それから３５％から４５％の場合は６割、４割ですか、４５％から５５％の均等割の場合は７割、５割、２割の減額ができる。こういう内容になっていましたけれども、それぞれにちょっとこの辺の件数についてもお聞かせを願いたいというふうに思います。","respondent":"本城国保医療年金課長","answer":"国民健康保険の関係で、滞納者への対応ですが、国民健康保険について、納期が過ぎても滞納されている方につきましては、督促状を発行した後に催告書等、あるいは電話がわかっている場合については電話でご連絡して、個々の状況を把握した上でその方の状況に応じて。","id":"exchange-013"},{"speaker":"菊地委員","kind":"確認","question":"その辺をちょっとお答え願いたいのと、滞納期間は何か基準があるんだというふうに思うんですけれども、そういう滞納期間とか、どういう基準で差し押さえを行っているのかということと、それから預貯金口座を差し押さえるということは、何らかの方法でこれを確認するんだというふうに思うんですけれども、その辺の確認方法についてもお聞かせを願いたいというふうに思います。","respondent":"本城国保医療年金課長","answer":"通常の文書では応答していただけない方も、差し押さえを一つのきっかけとして、差し押さえの段階で改めてご相談いただくケースもかなりありますので、そういった場合については、差し押さえの経過も踏まえてこれからどういった形で納付が具体的に進んでいくか。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"その辺の考え方も教えていただきたいのと、それから減免制度ですか、これの活用、ちょっと私聞き漏らしたのかもしれませんけれども、相談件数がちょっとわからないのでもう一度そこを教えていただきたいんですけれども、制度の活用者、全体の数からいうと非常に少数なのかなというふうに思うんですよね。恒常的な低所得者の方はどういうふうに対応されておられるのかについてもお聞かせを願いたいと思います。","respondent":"本城国保医療年金課長","answer":"それとあわせて、経済情勢の中で失業される方がすごく増えているということがありますので、これも今年度からですが、失業、いわゆる非自発的失業者に対する軽減ということも実施しておりまして、今１,５００人弱ぐらいの人がその軽減で対応しているような状況です。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"私どもが春にいただいたアンケートの中で、税金や社会保険料などの負担についてどう感じるかというふうに聞いたところ、本当に重いと感じるという方が６５％にも上っておられるんですよね。先ほどの話ですと、後期高齢者の方、短期証を１８件発行しているということですけれども、命に直結をするわけですよね。とりわけ高齢者の方はね。やっぱりそこは大きく改善をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"私のほうからは、１３３ページ、ひとり暮らし高齢者ニーズ調査について、それと１４４ページ、生活保護費についてお伺いをします。１４４ページの生活保護費については、まず初めに、平成２１年度民生費の中で増の主なものとしてもこの生活保護費が書かれていますが、生活保護、品川区として改めてどのような位置づけというか、考え方を持っているのかお聞かせください。よろしくお願いします。","respondent":"冨岡高齢者福祉課長、平澤生活福祉課長","answer":"この事業につきましては、平成２１年度の国の事業ということで３年間の事業ですが、まず最初に事業を実施するに当たりまして、これは品川第二地区をモデル地区で実施をしたものですが、その地区の高齢者等の方。区としての考え方というご質問なんですけれども、生活保護自体は憲法第２５条に定める生存権の保障ということで、最後のセーフティネットとして欠かせないものだという位置づけで事業を行っているところです。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"ひとり暮らし高齢者のお答えは、民生委員がやられているということでよろしかったんでしょうか。だれが調査をしたかという部分で、民生委員がされたのか、また民生委員が例えば来なくていいよとかと言われたところが１,２００件あったというんですが、そこに対しては、どなたがお伺いをして人数を聞かれたのか、その点だけお聞かせください。","respondent":"冨岡高齢者福祉課長、平澤生活福祉課長","answer":"民生委員が調査されました。それから、来なくていいという方につきましては、社会福祉協議会が調査をしたところです。初めに、３６ページの自立支援事業にかかわる保護費の削減額ですが、生活保護費につきましては、全体で５,４００万円の効果額があったですが、区の負担、単体で考えますと、その中の１,２００万円が削減されたです。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"ひとり暮らし高齢者ニーズ調査、ぜひとも高齢者の方たちが何を求めているのか、改めて聞いているという事業だと思いますので、ぜひこの挙げられたものに対してさらなる支援をしていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。１３８ページの品川児童学園運営費についてお尋ねします。品川区では、現在発達障害と思われる就学前のお子さん、あるいは小学校・中学校の子たちがどれぐらいいるのか把握していらっしゃるでしょうか。その出現率は品川区として何か特色があるのかということもお尋ねします。平成２１年で言えば２４名の登録者のお子さんが毎日全員来て、支援を受けていたのでしょうか。","respondent":"冠木指導課長、永尾障害者福祉課長","answer":"私どもが把握しているのは、そういった学習障害、あるいは発達障害があるのではないかと疑われる児童、あるいは心配な児童・生徒に対して、学習支援という形で対応していますので。児童学園の通園の仕組みですけれども、隔日通園の方と毎日通園の方と分かれております。隔日通園の方につきましては、現在７名、全日通園の方は現在１３名いらっしゃいます。","id":"exchange-020"},{"speaker":"高橋委員","kind":"質問・要望","question":"数字的なことをお尋ねして、これを指導に生かしていただきたいと思うんですが、児童学園の指定管理運営委託費７,３００万円余ですが、社会福祉法人の福栄会がやっているんですが、初めは品川総合福祉センターだったと思うんですが、ちょっと記憶があいまいですが、変更された経緯と、それからもう一つは、福栄会は発達障害にかかわる事業、あるいはそういったことを児童学園で行う以前に。","respondent":"永尾障害者福祉課長","answer":"子どもの発達相談につきましては、安心センターのほうで福栄会が実施していたという経緯がありまして、そちらの事例を積み重ねて生かすということで、福栄会が児童学園の指定管理を受けることになりました。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうすると、ちょっとこれは一般論というか法律論なんですが、知的障害児通園施設の運営委託に社会福祉法人が指定されるということについて、社会福祉法上の根拠、つまり知的障害児通園施設は社会福祉法人が運営できるという言い方のほうがいいんでしょうか。社会福祉法上の根拠を教えていただきたいんですが。","respondent":"永尾障害者福祉課長","answer":"知的障害児通園施設につきましては、児童福祉法の第４３条のほうで定められて、それに基づいてやっております。","id":"exchange-022"},{"speaker":"高橋委員","kind":"質問","question":"ところで、同じ社会福祉事業なんですが、認可保育園の運営委託、これは社会福祉法人、または社会福祉法人以外でもよろしいのでしょうか。","respondent":"吉岡保育課長","answer":"認可保育園につきましては、ちょっと今、年度は失念しましたけれども、既に株式会社でも運営できるような形になっておりますので、今現在特にそのようなしばりはございません。","id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"そうなんですね。ですから、今お話にあったようにＮＰＯや社会福祉法人や株式会社まで運営ができるということですね。そういう事業を社会福祉法人に運営を委託しまして、その能力のある社会福祉法人になぜ公立保育園の委託を区のほうはさせていかないんでしょうか。ですから、平成２２年の私立の認可保育園に対して区のほうも補助を今回されたわけですよね。ということをどうお考えになるか、お願いします。","respondent":"吉岡保育課長","answer":"そういう中で、既に社会福祉法人が経営している私立保育園もありますし、また区立保育園は現在４０園あって、その中で今までの保育のさまざまな積み重ね、実績、経験、ノウハウもありますので、そういう中で十分な保育をしてきたというふうに自負はしているところですけれども。","id":"exchange-024"},{"speaker":"高橋委員","kind":"質問・要望","question":"ところが、今のお話しによると、社会福祉法人だと受け入れ態勢が云々と、先ほど言った福栄会は非常に専門性が高くて能力を持っている。これは今後検討していっていただきたいと思います。それについて前もお尋ねしましたけれども、ＮＰＯが公立保育園を運営していくということについて拡大していく、そういうことのお考えはないのでしょうか。その行政哲学というんでしょうか、そこもお尋ねします。","respondent":"吉岡保育課長","answer":"ぷりすくーるのお話です。非常に優れた保育・教育を実施しているというお話もございました。私どももそのように考えてあります。","id":"exchange-025"},{"speaker":"高橋委員","kind":"質問・要望","question":"検討していただいて、数字の面からもそうですし、こそという言い方をしてはいけませんが、経費の面からも検討をしていっていただきたいと思います。平成２１年度からの事業だと思うんですが、ここでの相談の内容や事業が児童学園での支援やあるいは教育機関、保育園などの支援に生かされて、特に平成２２年、今年の施策にどのように生かされたか、具体的な事例をお教えください。","respondent":"永尾障害者福祉課長","answer":"そちらの状況も踏まえながら、児童学園の中の通園や母子通園等につなげていくような事例も出てきていることと思います。今後もちょっと気になるお子さんについてのご相談が気軽にできるような発達相談室になるように努めていきたいというふうに思っております。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"よろしくお願いします。私は１３０ページの成年後見制度、１３２ページ、ＤＶ被害者などの給付金、２０３ページの特定健康診査について伺ってまいりたいと思います。やはり先駆的に取り組む品川区ということで言われる、そういったゆえんですとか、この高い評価はどういうところが特に評価をされているのか伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"これにつきましては、平成１０年以降から早く成年後見センターを立ち上げて取り組んでいったということ、今の任意後見につながっていく安心サービスというものがありますけれども、そういうところをきっかけに、この法が始まった段階から早期に取り組んでいったということ。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"ボランティアの限界もあるかと思われますので、ボランティアも必要だし、あるいは専門性も必要だしというところの仕組みについてどのようにお考えか伺いたいと思います。９人が特段どうこうというわけではないんですが、幅広い意味だと思いますが、高齢者の方のＤＶに対する現況がどうであるのか、そしてどのように想定がされていて対応していくのか、この３点の流れを伺えればと思います。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"今後供給が非常に必要とされると、高齢者の方で、認知症の高齢者の方が増えていくという中で、成年後見はどのように対応していくかですが、現在支援員という制度で対応している５２人ぐらいがおられて、それぞれ８０件ぐらい。こちらのＤＶ被害者の生活支援給付金給付事業なんですけれども、ちょうどこの時期に定額給付金とそれから子育て応援特別手当、こちらの受給のタイミングがございました。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"質問","question":"成年後見のところは、今触れました地域の理解と、それと携わる方の必要性というのは、今後の大きな柱になるかと思いますので、よろしくお願いします。大くくりな中で、品川区の中のＤＶというくくりの中の現況、そしてどのように想定されていくのか、そして対応が今いろんな新事業もあるかと思いますので、その点も次に伺いたいと思います。","respondent":"安井子育て支援課長","answer":"そちらで大体２００件ぐらいのご相談が寄せられているわけなんですけれども、私どもの子育て支援課のほうは、特に福祉事務所の立場として婦人保護を取り扱っておりますので、そういった方について、東京都の配偶者暴力の相談所です女性相談センター。","id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問","question":"特定健康診査のところで、医療費抑制のために国が数年前に特定健診と特定保健指導ということで、俗にメタボ検診等の導入がなされまして、その中で国民健康保険においては、保険者である品川区に受診の促進と対象者への指導が義務づけられているとは思いますが、品川区におけるまず直近の受診率はどれくらいあるのか、そして品川区の位置づけはともかくとして、都内というか近隣区、２３区というくくりだとか。","respondent":"本城国保医療年金課長","answer":"それで、今手元にありますのは、都内２３区の中の状況ですが、一番高いところで平成２０年度ですが、４７％程度、低いところで２９％程度、そのような中での分布です。","id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問","question":"これはいろんな課題があるかと考えていますが、この制度が導入されたときに、国では目標の受診率を６５％と定めて、下回った場合にペナルティーを課すと聞き及んでいます。どのようなペナルティーというものが準備というか、されているのか。それは品川区にとってどのような負担になるのか、現状の想定というか、あるいはおよそ金額的なものもあるかと思いますので、ご答弁をよろしくお願いします。","respondent":"本城国保医療年金課長","answer":"ただ、これ自体は今、後期高齢者医療制度の改革の中で、ペナルティーという形では見直しの方向で検討がされているというふうには聞いているところです。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"私は１３０ページの社会福祉総務費の中の、一つはホームレス対策事業、そしてその下の品川介護福祉専門学校の修学資金についてお伺いさせていただきたいと思います。よろしくお願いします。","respondent":"平澤生活福祉課長","answer":"第２点目なんですけれども、品川区の状況ですが、８月と１月に目視調査による調査を実施しておりまして、平成２０年度の８月期は４４名、平成２１年度につきましては、同じ同期で２８名、１月に関しましては３５名ずつということで変わっていないわけなんですけれども。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"ホームレスの対策事業の上に、行旅死亡人等取扱事務６件と書いてあるんですが、これは身元不明の方のことかなということなんですが、実際この中にはホームレスの方というのはいらっしゃるのでしょうか。","respondent":"平澤生活福祉課長","answer":"前者のほうですね、行旅死亡人等にホームレスの方が入っているのかということになりますが、いわゆる私どもが目視で確認している方の中にはいらっしゃらないんですけれども、ただ現実的にお名前などがわからない中で、行き倒れといった言葉が適切かどうかはわかりませんけれども。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"勝島に浜川荘でしたかね、あるかと思うんですが、そちらのほうにホームレスの方がもし、いらっしゃれば教えていただきたいし、また特に男女別、また年代のことがわかれば教えていただきたいんですけれども。","respondent":"平澤生活福祉課長","answer":"男女の区分なんですけれども、圧倒的に、９割以上、ほとんど１００％近い形で男性です。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問","question":"ちょっと時間がないので、次の、下のほうにあります品川介護福祉専門学校の修学資金についてお伺いします。こちらに貸付１０５件とありますけれども、この１０５件の内容を教えていただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"１０５件の内容ですが、これにつきましては、前期、後期で２回に分けて貸付をしておりまして、前期が５８名、後期が４７名です。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"毎年３０人以上の方がこの学校を卒業されて、そしてこの修学資金制度を利用する方の９割以上の方が区内の指定施設で介護業務に従事するというふうに聞いておりますけれども、実際今まで３年以上勤務なさって、約１２０万円ですか、返済が免除されるというふうに聞いておりますけれども、実際何人ぐらいいらっしゃるのか。","respondent":"冨岡高齢者福祉課長","answer":"ですから、かなりの割合で免除の対象になっているです。それから、先ほどの前期、後期ですけれども、これは１年生、２年生の前期分、後期分という合算の数字です。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つ、逆に今度途中でやめられた方で、返済状況はどのようになっているのかも教えていただきたいんですけれども。","respondent":"冨岡高齢者福祉課長","answer":"すみません、貸付が残っている方で、現在３０名が返済中です。そのうち毎月支払をいただいている方が２６名、残りの方はときどき滞っておいでになるので連絡をしているというような状況です。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても、品川区のすばらしい制度ですので、本当に皆さんの力になりたいということで入学したかと思いますが、ぜひやめた方の理由をしっかり調査していただいて、今後活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"藤原委員","kind":"確認","question":"１３２ページの高齢福祉費になると思うんですけど、それと２０３ページの特定健診についてお伺いしますが、委員長、中延のコンシェルジェについてお伺いをしたいんですが、ほとんどが民生費にかかるんですけども、ちょっとだけ産経費が入っちゃうかもしれないんですけど、ほとんどが民生費なのでやらせてください。","respondent":"諸岡商業・観光課長、本城国保医療年金課長","answer":"中延商店街、街のコンシェルジェという福祉的な事業を行っていた店舗につきましての助成額です。平成１８年に１年間だけですが、家賃助成として月額１２万円の助成をしております。特定健康診査の健康課との連携の具体的な方法ですが、以前ご答弁させていただいた将来的には給付データの分析も含めて共有化して、それを今後の健康施策全般に役立てるというような意味でご答弁させていただいた経緯がございましたが。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"データがどれだけ有効かというお話をして、将来的にやりますよという答弁をいただいているにもかかわらず、結局何もしていないわけじゃないですか。だけど、結局何もやっていないわけじゃないですか。具体的にやっていないんですから、もっとちゃんとデータの大事さというのを把握して、区民の本当に健康のためなんですから、ちゃんとやっていただきたいと思うんですけど、改めてお伺いしたいと思います。","respondent":"本城国保医療年金課長、間部高齢者いきがい課長","answer":"それで初めて特定健診の意義が達成されるということは改めて認識しています。社会福祉協議会を通じまして、地域貢献ポイント事業を契約しているところです。予算につきましては、前払いということで、今年度ですけれども、４８万円ほどコーディネート委託ということで支払済みです。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"確認をしていても、それだけの確認ではわからなかった部分というのはあるんですけれども、結局前払いしてもつぶれちゃったわけですよね。そうですよね。ＮＰＯ法人というのはほかにもあるじゃないですか、助成、支援もあるじゃないですか。しようがないでは済まないじゃないですか、税金なんだから。その辺について、これからもあり得ることですから、ちゃんと明確なその辺の答えをいただきたいんですけど。","respondent":"間部高齢者いきがい課長","answer":"経営状態の把握につきましては、今までも努めてまいったわけですが、今後さらに一層確認に努力してまいりたいと、このように考えてあります。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"把握していないから、なったから、これからと言っているんですから、全部時間いいですから、その辺、明確な、税金ですよ。ちょっと、もうちょっと努力しますとか、その辺じゃなくて、いただきたい。","respondent":"福田会計管理者","answer":"もう一つ、私ども事業としておつき合いのある公認会計士に経営分析を委託したり、そういう事業もやっておりますので、今後はそうしたことをこのようなケースがもし生じれば活かしてまいりたいというふうに思っております。","id":"exchange-042"},{"speaker":"阿部委員","kind":"質問","question":"私からは１３０ページの民生委員の経費、それから２番目に１３６ページの高齢者の口腔ケア、それから１４１ページの児童手当について伺います。民生委員、人材の確保がなかなか難しいという話をよく聞きますけれども、品川区の状況はどうなっているでしょうか。未提出者の割合とそれからどのような対応をしているかということを教えてください。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"今までもなかなか民生委員が就任されない部分がありますけれども、それについては地区の民生委員、ほかの民生委員ともお話ししながら。こちらにつきましては、今月催告のほうを出させていただきまして、支給がその方たちについては１０月の支給がとまっておりますので。特に現場のケアに携わる介護士たちのためには、福祉カレッジのほうで口腔ケア研修ということで、両歯科医師会の先生方にお願いして。","id":"exchange-043"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういった面からも、社会福祉協議会の寄附金を民生委員が集めるという仕組みについては、これは社会福祉協議会のお考えという面もあるかもしれませんけれども、区としてもぜひ考えていただきたいと思うんですが、いかがでしょうか。口腔ケアについては、一定のご認識があると思いますが、ぜひ進めていただきたいと思います。それから、児童手当なんですけれども、５００件ほどまだ届いていない。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"その支え合いの重要な拠点といいますか、主体として社会福祉協議会があるんだということで、民生委員が社会福祉協議会と連携しながら地域福祉を進めていただいているというような今までのいきさつの中から。現況届未提出の方についての対応ですけれども、ホームページとかあるいは広報しながわであるとか、そういった媒体も通じまして広く周知に努めてまいりたいと考えています。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"何か相談したいなと思ったときに、そういえば何か前に協力してくれないですかとお金のことで言われたなというところで、一つそこにハードルができてしまうのは、私はもったいないことだと思うんですね。そういった民生委員側の心理、それから地域のお年寄りをはじめとして困ったことを相談したい方の心理と、そういったこともしっかりと踏まえた上で今後どうあるべきか。再度ご答弁をお願いします。","respondent":"冨岡高齢者福祉課長","answer":"本委員会におきまして、委員からそのようなお話をいただいたということは、社会福祉協議会のほうに伝えてまいりたいと考えております。","id":"exchange-045"},{"speaker":"阿部委員","kind":"質問・要望","question":"すみません、ちょっと１分しかないので言えるかどうか。保育園運営費について、午前中公立の保育園の公設民営について少し話が及びました。ですので、子育てあるいは教育といったところに力を入れている品川区の政策を一般的な区と同じような形にしてしまうというのは、私はむしろもったいないことだと考えています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長は選挙で待機児解消を掲げまして、一日も早い実現が求められますけれども、とりわけ来年４月の対策について伺いたいと思います。本会議で、区長が引き続き定員拡大、既存施設の活用などの多様な施策を、財政状況を勘案し効果的に実施してまいりますという答弁をされましたが、また定員拡大でいわゆる詰め込みをするつもりなのかどうかということもあわせてお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"来年度以降の待機児童対策につきましては、先般ご答弁申し上げましたとおり、私立保育園、認可保育園の２園の開設の助成をまず予定しております。それに加えまして、これまで行ってきましたような既存園の定員拡大も含めたさまざまな施策で対応していきたいと考えております。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこで伺いますけども、特に厳しいと言われている大崎・五反田地域にある認可保育園の今年４月の最低点数ですね、特に厳しい状況である０・１・２歳児クラス、それぞれについて伺います。それとあと、４月、１０月は厚生労働省から待機児童数の調査を求められていると思いますが、１０月の待機児童数は何人か教えていただきたいと思います。今年の１０月も含めて、ここ３年間の数字も教えてください。","respondent":"吉岡保育課長","answer":"それから１歳児については、常勤であることプラス、例えばご兄弟が同じ保育園にいるとか、そういうプラスの加点がないと難しい状況が１歳児です。２歳児については、やはり父母が常勤の状態が必要ということです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのほかにこのガイドラインによりますと、ほかに入所可能な保育所があるにもかかわらず、特定の保育所を希望し、保護者の私的な理由により待機している場合には、待機児童数に含めないこととありますけれども、例えばそれは区も答弁していたように、申込書に１園しか希望していない方を指していると思うんですけど、これ以外に何かあるんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"国が定義をしております待機児童ですが、委員今おっしゃられたとおりの項目があります。そのほか、休職中については区の実情に合わせて待機児童という算定をするという項目があったかと認識しております。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"待機児が６６人とおっしゃるならば、そもそも調査日、日時、４月１日時点においての入所申込者数、そもそもいろんなものを引く前の、４月１日時点での入所申込数というのは何人なんでしょうか。少なくとも区がおっしゃるのは、たぶん不承諾通知をもらったのが４８７人なんですけども、この数ではないと。その日に説明していると思うんですけれども、そこはどうでしょうか、あわせてお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"子どもと一緒に歩くということがありますので、そこまで見ております。二つ目のご指摘ですけれども、調査日、４月１日現在に入所の申請がされているというところに従いまして、４月１日時点での入園申請が出されているという方を待機児としてカウントしております。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"その４月１日時点で入所申込書を出している方というのは何人と認識しているんでしょうか、お伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"４月１日時点で入所申請を出されている方の全員の数ということになりますと、３１２名のお申し込みが出されています。その中で引き続き保育園の入園を申請されている方が６６名です。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"４８７人の方が不承諾通知をもらっているんですけども、改めて４月１日時点で申し込んだ方が３１２人だというふうに認識しているということなんですね。これは実態とそぐわないと思うんです。この指摘に対して、区の認識をお伺いしますのと、あと品川、ちょっと私品川方式と呼んじゃったんですが、こうした形でカウントしている区というのはほかに例があるのか、つかんでいらっしゃるのかお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"次のご質問ですけれども、４月１日時点での申請を改めて出されている方を待機児とするということへのご質問ですが、４月１日以降、お入りになるご意思がないということであれば、当然保育園を待機していると見なさないというのが考え方としては正当だと考えております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"国が示しているガイドラインに基づいてやっているとおっしゃるんでしょうけれども、区によって随分まちまちなんです。こういう中で、区がしっかり責任を持つ認可保育園を計画的に増設しないで、一体どうしてこういう事態が解決するのだと。ですから、ぜひ区長も考え方を変えていただいて、ぜひ深刻な待機児の問題に心を寄せていただいて、政策転換、認可保育園の大幅増設を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"武内委員","kind":"質問・要望","question":"私は１３１ページの社会福祉協議会助成金の中のほっとサロン、それから１３３ページの特別養護老人ホーム入所調整会議運営費に関連してお伺いしたいと思います。ほっとサロンにつきましては、ここに決算書のほうに２カ所で約３７６万円計上されておりますが、この内容についてと、あと現在のほっとサロンの開設の状況を教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"ですから、区立が３カ所、それから地域のほっとサロン、これが８カ所という形で現在運営されている、そんなところです。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"そうしますと残りの８カ所については、ここには出ていないんですけれども、社会福祉協議会のほうで助成を行っているということだと思うんですけれども、その内容とあと、そうすると、区立でやっている内容、それぞれがやっている内容の特長というんですか、違いとか、こういったものと、またこれまでやってこられた中での全体を通しての区の評価というんですかね、これについてお伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"こういう場につきましては、社会福祉協議会を通じて助成を出しているわけですけれども、区としましても、さまざまな地域でそれこそほっとするような場所が、拠点というものができていくことが地域の支え合いにとっても、社会福祉協議会が支え合いの組織ですので。","id":"exchange-055"},{"speaker":"武内委員","kind":"質問","question":"そうした中で、今社会福祉協議会のほうでは、いろいろ事業をやるときに一定の助成を行っているというふうに伺っているんですけども、そうした中で、例えば区立で、区の場所を使ってやっていらっしゃるところと、また場合によっては区のいろんな場所を、無料なのか、少し安い料金なのかわかりませんけど、場所の問題ですね、使ってやっている方もいらっしゃると思うんですけど、そうした中で。","respondent":"冨岡高齢者福祉課長","answer":"これにつきましては、現在地域福祉計画の改訂を進めているところですので、地域福祉を支える担い手の拠点をどのように支援をしていくかというような中で検討してまいりたいと考えているところです。","id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"私自身はその評価は１回しか見ていないので私自身は評価できないんですけれども、いろんな関係者の方からすると、非常にすばらしい取り組みをやっているという方たちがいるので、そういった部分も含めて、今後いろんな地域で、自分たちで家賃を払ってやっていこうという方に対しては、もうちょっと助成のあり方を検討していただけないかなというふうに思うんですけど。","respondent":"冨岡高齢者福祉課長","answer":"地域福祉計画、先ほど申し上げましたように改訂を検討していますので、その中で助成のあり方、拠点に対しても含めて、また項目として検討してまいりたいと考えています。","id":"exchange-057"},{"speaker":"武内委員","kind":"質問","question":"続きまして、１３３ページの入所調整会議の件ですけれども、今回特別養護老人ホームのほうが杜松小学校の跡ということで計画案がこの間示されまして、非常に評価をしているんですけど、ただ絶対的な数が足りないということは一つ大きな課題であるというふうに区のほうも受けとめていただていると思うんですが、またその全体数の問題と別に、今度入れる方の関係で、例えば介護度もかなり重くて。","respondent":"冨岡高齢者福祉課長","answer":"これは本年２月の調査の大体の数字ですが、区内の７カ所の特養ホームで、入所者のうち医療行為が必要な方の割合が２５.８％というような数字です。ですから、２０％から３０％の間という大きい数字ですが、とらえていただければと考えています。","id":"exchange-058"},{"speaker":"武内委員","kind":"質問","question":"例えば、新たに入るときに、例えば胃ろうがあったりとか、気管切開というのはまたちょっとレベルが違うかもしれませんけども、そういった場合には、受け入れができるかどうかというのは、その辺はどんな感じなんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"現在の申込者の中の、大体今申し上げたとおり、ほとんどの方が入所後胃ろうになったという方です。","id":"exchange-059"},{"speaker":"武内委員","kind":"質問","question":"何で、一番必要じゃないけども、そういう場合に入れないんだろうかというお声がありまして、例えば今、国のほうでも医療行為が必要な方についての取り組みをされていますけれども、特養の中で、それぞれある中で、例えば区のほうで一定の割合というんですかね、そこに入っている方について、もしくは新たに入れる方について、そういうものというのは話し合いをされたりとか。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、それをどういう基準を出して、どうこうしろというのはすごく難しゅうありますが、国のほうも今その辺のところを課題としてとらえているというふうに聞いておりますので、少し動向を見つめ。","id":"exchange-060"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひその辺も見すえながら、場合によっては例えば一定のものを受け入れてくれるところには、例えば助成を少し厚くするとか、そういうことも検討できないかなと、これは一つ要望します。そうした中で、品川のほうで傾聴ボランティアみたいな方がいるかどうかちょっとわからないんですけど、そうしたことも含めてレスパイトケア、在宅介護の方のあり方というのをどのように考えているか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"今非常に厳しい状況の方のレスパイトということは必要であるというふうに感じておりますけれども、ただやはり、個々のケアマネジメント、ケアマネジャーとの話の中で、少しずつ上がってくるものだなというふうに理解しておりまして。","id":"exchange-061"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、成果報告書の１３４ページ、高齢者住宅対策事業等に関連して少し具体的にお伺いさせていただければと思いますので、よろしくお願いいたします。以上、３点です。","respondent":"間部高齢者いきがい課長","answer":"主に高齢者住宅のあっせんにつきましては、高齢者住宅の入居がなされない方に、あわせて実施しているという事業でございまして、あっせんの件数につきましては、平成１９年度は申請が６５件、助成が１０件、平成２０年度は５６件で８件。","id":"exchange-062"},{"speaker":"原委員","kind":"質問・要望","question":"逆のほうの形からいきますと、私も今日、管内の宅建業者からのほうの資料をちょうだいしてきたんですけれども、そうしますと、これは確認しなくていいと思うんですけども、以前の高齢事業課のほうが高齢者いきがい課と、そこにパスされているという解釈をして進めしますけれども、まずそうしましたらば、区のほうで連帯保証されているところの、区と協定されていらっしゃる。","respondent":"間部高齢者いきがい課長","answer":"このあっせん事業につきましては、宅建の品川支部にお願いをしているところでございまして、現在加盟９０社で対応されているです。","id":"exchange-063"},{"speaker":"原委員","kind":"確認","question":"１点ちょっとご返事がなかったのでもう一回確認しますけども、この保証制度、具体的には初回保証委託料の助成のことについてなんですけど、そこがちょっとお返事がなかったので、もう一回、１社なのか数社なのか、その辺も含めて。","respondent":"間部高齢者いきがい課長","answer":"すみません、レントゴー保証株式会社１社で行っているところです。","id":"exchange-064"},{"speaker":"原委員","kind":"質問・要望","question":"この辺の保証、これは社会福祉協議会のほうとの連動もあるでしょうけれども、とにかく金額面も民間で５万円ということになっていますので、そうすると今度は民間のオーナーとか宅建業者のほうが逆に引いてしまうというようなところがあるものですから、その辺をもう少し充実していただきたいという、これは要望です。","respondent":"間部高齢者いきがい課長","answer":"あっせんにつきましては、区では区民の皆様からご要望があった際に、月に２回ほどリストにまとめまして宅建の品川支部のほうにデータを送信してマッチング作業をしていただいているところです。","id":"exchange-065"},{"speaker":"原委員","kind":"意見","question":"そうですね、やっとリストという話が出てきたので、そこに関連をして話します。先ほど申し上げたように、最近の区内の業者のほうからいただいたんですけれども、そのいただいた中にちょうどこれは６年前のデータも、２０１０年、２００４年の両方のデータをちょうだいしたんですけれども、まず形状が変わっていない。","respondent":"間部高齢者いきがい課長","answer":"ただ、氏名等は当然のことながら書いていないということで、宅建の方から、先ほど委員が申し上げられたように番号、例えば平成２０年度の何番の方についてこういう物件があるよというデータがこちらに戻されてくる。","id":"exchange-066"},{"speaker":"原委員","kind":"意見","question":"現場はすごく一生懸命やっていると。先ほど申し上げたように、６年前のデータとリスト表が全く同じ形で来ておりますので、その辺のところをもう一回基本的なところを、というのは、ハローワークのように、幾ら個人データがどうこうといっても、ハローワークのような形の展開もあろうかと思いますので、その辺をお答えいただければと思います。","respondent":"間部高齢者いきがい課長","answer":"リストの形式が長年変わっていないです。この件につきましては、宅建の品川支部とよく話し合いの場を持ちまして、どのような形がよろしいかと。ひいては、高齢者の方に的確にマッチングするような形になるように改良していきたいと考えております。","id":"exchange-067"},{"speaker":"市川委員","kind":"質問・要望","question":"私のほうからは、１３５ページの生活支援サービス、地域生活の支援に関連して、ふれんどりー事業について伺います。それから、１３８ページの特別養護老人ホーム等整備費から伺います。それから、生活者ネットでは、ぜひとも当事者の声を聞いていただきたいという要望をしておりましたけれども、これについてはなさったのか、またなさっていないとしたら、今後の予定はあるのか、この点をお聞きします。","respondent":"冨岡高齢者福祉課長","answer":"アンケート等につきましては、このとき、これは平成２１年度についてはいたしておりませんけれども、今回、今年度実施する介護者激励のつどいについては、アンケート、どういうご意向かということのアンケートをしていく予定にしています。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問・要望","question":"１９３人の参加者はお聞きしたんですけれども、対象というのは何人になっているのかというのをお聞かせいただきたいと思います。それで、私たち平成２２年度にアンケートを実施されるということなんですけれども、今年度生活者ネットのほうでも家庭介護を経験されている方４１人からの声を聞きました。約８０％の方は、やっぱり家庭で介護することはつらいとお答えになっております。","respondent":"冨岡高齢者福祉課長","answer":"それとあと、介護者の研修ということで、日帰り研修、それから宿泊研修ということで、本年度は宿泊研修のみになりましたけれども、そういう形で現在研修等も介護者のレスパイトということで実施をしていますが、今後どういう形の、今の事業をベースに。","id":"exchange-069"},{"speaker":"市川委員","kind":"質問・要望","question":"対象者４,８７３人の中の１９３人の参加というのは参加率がたった４％で、ほとんどの方がこういった支援を受けられていないという実態もありますのでご検討をお願いしたい。次に、介護保険の特別給付費の通院等外出介助サービス特別給付について伺います。これは事業内容が三つあるようですけれども、この三つのそれぞれの実績について伺います。","respondent":"冨岡高齢者福祉課長","answer":"要支援の方の夜間対応サービス特別給付が、平成２１年度延べ４０人です。それから通院等外出介助サービスの特別給付が、平成２１年度延べ４７５人です。地域密着型ケアハウスの特別給付が延べ３１７人の実績でございました。","id":"exchange-070"},{"speaker":"市川委員","kind":"質問","question":"この事業の決算額が８３万９,２５０円ですか。それで、２００９年度、平成２１年度の予算を見ますと、３,４３４万４,０００円という予算で、大変執行率が低い事業なんだなというふうに感じるんですけれども、この２００９年度予算を立てた根拠はどういうところなのかを伺います。これだけの不用額を生んだ理由は、どういうところにあったのか、その分析をどのようにされているのか伺います。","respondent":"冨岡高齢者福祉課長","answer":"これは最初の年の算出の仕方ですけれども、区内のケアマネジャーにちょっとリサーチをいたしまして、概数ということで最初の年でしたもので出したです。実際ケアマネジメントをしまして、ご希望の方に当てはめてみますと、実績のとおりということで差が出てしまったです。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問","question":"最初のリサーチと随分違っていたということなんですけれども、それにしても不用額が多過ぎるかなというふうに思っているんです。それで、２０１０年度の予算を見ると１,１８８万円ということで、かなりまた引き下げられているんですけれども、これについての算出の根拠というのはどのようなことでされたのか伺います。","respondent":"冨岡高齢者福祉課長","answer":"１年間の実績がまだ出ていないうちの予算の積算ですので、見込みということと、今後これがある程度もう少しよくご説明をして、区民の方におわかりいただいて、利用がもう少し伸びる可能性も含めて、そういう金額で計算をさせていただきました。","id":"exchange-072"},{"speaker":"市川委員","kind":"質問・要望","question":"これは２００９年度に始まった事業で、ちょっと考えると、要支援の方が病院やそれから外出支援サービスを受けるというのは、ないことではなくて、私もニーズは結構あるんじゃないかなというふうに思ったんですけれども、この事業の内容が利用する方のニーズに合っていないのか、それともＰＲの仕方が悪いのか、ちょっとこの辺はきちんと分析をして。","respondent":"冨岡高齢者福祉課長","answer":"この事業は、サービスを提供している事業者にもまだよくご理解いただいていない部分もございまして、その辺もよくお話をするのと、介護保険上のいろいろ制約がありますけれども、その中で使えるか、さらに判断をしながらサービスの提供に努めてまいりたいと考えています。","id":"exchange-073"},{"speaker":"市川委員","kind":"質問","question":"先ほどおっしゃった介護保険上の制限というんですか、ちょっとその辺がどういうところなのか伺いたいんですけれども、お願いします。","respondent":"冨岡高齢者福祉課長","answer":"これは東京都との検査のときにいろいろ微妙な解釈の違いで、これは適用できるのかどうかというようなところがあるようでございまして、その点で提供者のほうがときに消極的になる場合もあるということで、その辺をもう一度よく話を詰めて。","id":"exchange-074"},{"speaker":"市川委員","kind":"質問・要望","question":"これについてはサービスの内容が皆様にも、提供者のほうにも行き渡るような方法をとって広げていただきたいと思います。次ですけれども、生活支援サービス、地域生活の支援に関連して、ふれんどりーサービス事業について伺います。要綱を見たんですけれども、要綱には特にそのような表記が見当たらないんですけれども、なぜこのようになっているのか伺います。","respondent":"永尾障害者福祉課長","answer":"学校から目的地につきましては、一応考え方としてはお子さんが学校からどこかに寄り道をするというのは、一般的にはあまり好ましいものではないということで、現状では認めていませんけれども、例えば作業所から目的地というのであれば、社会人がどこかに寄り道したいという。","id":"exchange-075"},{"speaker":"市川委員","kind":"質問・要望","question":"そういうことを考えると、ぜひ学校から施設という運用も認めていただきたいということを要望しておきます。それから最後ですけれども、特別養護老人ホーム等整備費に関連して、認知症グループホームの整備について伺います。八潮と都南が整備されておりますので、残りがあと６カ所になるかなというふうに思うんですけれども、あと６カ所の整備方針はどのような形でされていくのか伺います。","respondent":"冨岡高齢者福祉課長","answer":"グループホームにつきましては、身近な事業所ですので、生活圏域に１カ所ずつということで、介護保険事業計画第５期までということで見込んでおりまして、それについてさまざまな機会をとらえて、オーナー型というのは非常に難しいなというふうには認識しておりますけども。","id":"exchange-076"},{"speaker":"市川委員","kind":"提案","question":"区は質を担保するという、支援を行うような協働の観点で認知症グループホームの整備を進めていただきたいというふうに思って再度要望するんですけれども、オーナー型は難しいという、この辺はどのようなところが難しいのか具体的にお話しいただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"オーナー型を実際、区でも実施していますが、一般的に申し上げるところは、建物を建てて、賃料というものがあります。","id":"exchange-077"},{"speaker":"山路委員","kind":"質問","question":"午前中にもひとり暮らし高齢者ニーズ調査、高齢者相談等事業のことについていろいろ質問が出まして、お話をお伺いしましたが、地域における高齢者の方を守るために調査をして、そしてボランティアの人を募集して、ボランティアに応援してもらって、町会・自治会、そして地域センター、ふれあいサポート、いろんな関係者の方でひとり暮らし高齢者の方を守っていこうという仕事だろうと思うんですが。","respondent":"冨岡高齢者福祉課長、本城国保医療年金課長","answer":"ひとり暮らしの高齢者の方が地域で安心して暮らせるための支援を行うための事業ですので、これについて昨年度、平成２１年度にニーズ調査をさせていただいて、今年度、実際その結果どういうニーズがあったかということで。区の中の事業では、保健センター等々の関連の事業の中で対応をすることはあり得るかなと思いますが、ただ特定健診の中というのはなかなか困難だと感じているところです。","id":"exchange-078","title":"町会・自治会支援"},{"speaker":"山路委員","kind":"質問","question":"非常に反響を呼びまして、６月から８月までの間に８項目にわたって検査をしてくださったんだそうです。毎日の生活が充実していますかということとか、わけもなく疲れたような感じがしますか。それで、８００人検査を受けた中から２４人が検査に引っかかったといいますか、該当した。こういう情報はお伺いしたことがあるかどうか。品川区では考えられないかどうか、もう一度ご答弁をお願いします。","respondent":"冨岡高齢者福祉課長、本城国保医療年金課長","answer":"これはニーズにどのように対応していくかということ、そこの問題を解決しない限り、なかなかきめ細かな対応というのはできないかと思いますが、今後の社会福祉協議会での研究の課題にしていただきたいと考えています。板橋区で実施されていた手法等については、ちょっと私のほうで今把握しているところではないところですので、それについては調査等をしたいとは思っておりますが、ただ、少なくとも今の時点では、特定健診の中でというのは。","id":"exchange-079"},{"speaker":"山路委員","kind":"質問・要望","question":"課長が言われたとおりで、これからきめ細かく対応していただきたいんですが、高齢者の方が出入りするお買い物場とか、郵便局とか、その辺まで手を伸ばしてネットワークの中に入っていただいて、居場所は地図とかいろいろ見ればわかりますよね。","respondent":"冨岡高齢者福祉課長、本城国保医療年金課長","answer":"場所につきましては、地域センターの中の社会福祉協議会のブランチの部分であると思います。今ご指摘いただい板橋区の方法については近々調査しますが、今のところは、それがどう活かせるかについては、ちょっといろいろ課題があるかなとは感じているところです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"１３０ページ、成年後見制度利用支援事業、介護保険利用者負担金軽減措置事業、次のページに行きます。１３１ページ、安心生活創造基金、次に１３６ページ、社会参加への支援、以上４点聞かせていただきます。順番がちょっと狂いますが、介護保険利用者負担軽減措置事業なんですけれども、３万８,０００円と金額は少ないですけれども、どのような事業で、なぜこういう返還が行われたのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この事業につきましては、障害者のサービスをお使いになった方が６５歳以上になってもお使いいただけるということの軽減事業ですが、計画したよりも都の交付金が多かったということで、その余りました部分については、３万８,０００円を翌年度返還させていただいた。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"おおむねこれは何名の返還をされた方がいらっしゃったのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"何名というよりも、金額的にその金額ということでございまして、何名分ということではございません。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、前年度の成果報告書を検討させていただきましたけれども、出てこなかった。今年こういう形で出てきたわけですけれども、今後こういうことの返還行為というのは、年度によってあるということで認識をしてよろしいのかどうか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この事業につきましては、対象者がおいでになるとその部分で交付金をいただく部分でありまして、ぴったりになれば当然返還はないということでいきますが、今回については事業があり、それで多くいただいたものですから、返還をしたです。年度によって変わってくるという状況です。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"では次です。１３１ページの安心生活創造基金ですけれども、成果報告書の９３ページの国からの補助金でということで安心生活創造事業補助金ということで１０分の１０、１,０００万円ということで出ていますけれども、いただきました基金の状況、これは基金として、区のほうの基金には載っていないんですが、どこにどういうふうにこの基金が載って出てくるんでしょうか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この部分につきましては、社会福祉の寄附金をいただきました。その１,０００万円を区を通しまして社会福祉協議会に渡し、それは社会福祉協議会へということでございましたので、その分を基金として積みまして、生活安定応援事業のために充てるという予定の基金です。","id":"exchange-084"},{"speaker":"大沢委員","kind":"意見","question":"事業補助金ということですけれども、そもそも補助金あるいは助成金、二つ種類がありますけれども、補助金なり助成金、これは基金という名目で振替をしていって、本来的にどのようなものか考えを聞かせてください。","respondent":"冨岡高齢者福祉課長","answer":"これは重複しますけれども、区にいただいた部分を社会福祉協議会にお渡しをして、そちらで生活安定事業のために使ってくださいねという形で基金化したものです。そして、基金ということでお渡しをした、そういう内容です。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"補助事業、本来であれば、補助ですから、何らかの補助をするため、事業を行うに当たって何か不足したりする部分で、それを補うために国からの補助金が入っていると思うんですが、それをそのままの基金という形で、名目で、お金に色はついていませんけれども、そういう形に名目でなっているということにちょっと私は違和感を感じるんですけれども。","respondent":"冨岡高齢者福祉課長","answer":"これは国の補助とは別に社会福祉指定寄附金を１,０００万円いただきまして、社会福祉協議会にというご指定がございましたので、社会福祉協議会にお渡しをして、それを基金として社会福祉協議会で積んでいただいて、その事業は先ほどの生活応援事業に充てていただくと。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、９３ページに名目は同じですけれども、安心生活創造事業補助金というのと、この安心生活創造基金というのは別物なんでしょうか。名目は一緒ですけれども、同じものか、別のものなのか、どっちでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"別物でございまして、その部分はひとり暮らし生活応援事業に当て込んでいるという部分です。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問・要望","question":"別物だけど、まるっきり名目は一緒で、我々成果報告書を見る上において、一つの名目であれば、当然ながら同じように解釈をするのは当たり前だと思うんですけど、なぜあえて表記を変えないで同じような形で書いてしまったんでしょうか。ということで、何が聞きたかったかというと、補助金ですよね。","respondent":"冨岡高齢者福祉課長","answer":"すみません、説明が不足して申しわけございません。寄附金の系列があります。それについては、区を通って社会福祉協議会に基金としてこちらはお出しをしたというのが１点です。それから、国からの補助金があります。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問","question":"１０分の１０で、補助金が来た。確かに先ほど課長がおっしゃったように、ひとり暮らし高齢者云々ということの使い道が違うんだよということも伺いましたけれども、これは表記の方法というのは工夫はしていただけないんでしょうか。そうでないと、私たちも成果報告書の見方を勘違いしてしまうので、無理な話でしょうか、ちょっと教えてください。","respondent":"金子企画財政課長","answer":"委員ご指摘のところは、ごもっともな部分があると考えています。この表記、毎年工夫をしておりますけれども、委員の皆さん、それから区民の皆さんにも誤解のないような表記を今後とも心がけていきたいというふうに考えてあります。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問","question":"わかりました。わかるように、私もこれからまた研究しながら、また再度伺いたいと思います。では次なんですが、１３６ページに行きます。しかしながら、予算書を見ました。お金の出てきたところ、補助金であれば、いろいろな部分で予算のところで載っていない部分もあろうかとは思うんですけれども、本来予算書に載っていないものを、決算をするということはどういうことなのか教えてください。","respondent":"永尾障害者福祉課長","answer":"事務費につきましては、ちょっと予算書が今手元にないので比較ができていないんですけれども、こちらの成果報告書をつくる際、もう少しその辺について照合して整備していきたいというふうに考えております。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"予算書はあります。ご覧になるんでしたら、今お渡しをしても結構です。これは何年にもわたって事務費が出てきません。いきなり決算書の成果報告書になると、事務費が載ってまいります。しかも、今回においては９００万円余ということで、１,０００万円近いお金が事務費ということで記載をしてあります。どこから捻出して決算をされた金額なのか教えていただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"社会福祉協議会のほうが適切に進行できるだろうということで、事務の移管をしたわけでありますけれども、その段階で、当然かなりの事業ボリュームがありますので、社会福祉協議会の人件費相当を見込んで事務費として計上したという経過があります。","id":"exchange-091"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、前年度、過去の流れでも結構です。予算書の中で事務費というものがどこに表記を、これもやはり表記を、これに限っては、社会参加への支援のところだけが事務費が計上されていません。ほかのは事務費があります。ここだけ事務費がぽこっと空白のようにあいています。どこへ事務費が、今決算ですのであれですが、予算書の中のどこに事務費が書いてあるんでしょうか。","respondent":"永尾障害者福祉課長","answer":"申しわけありません。予算書の中では、福祉タクシーと自動車燃料費助成の中にまとめてその部分も組み込んで表記しておりますので、この辺についてはまた調整してまいります。","id":"exchange-092"},{"speaker":"大沢委員","kind":"質問","question":"はい、わかりました。結構です。成年後見制度利用支援事業のことなんですけれども、これは制度そのものということよりも、金額ということで伺います。品川区の成年後見制度は非常に精度が高くて利用率も高いということ、確実なものであるということは十分わかっておりますが、このあい差はなぜ生じたのか、事業を行うにおいて何が原因でこういうふうな形で決算の金額になったのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"これは家庭裁判所に審判を申し立てまして、審判がおりるわけですが、そのおりるまでの過程において、品川成年後見センターの場合は最近鑑定が省略されるというようなことで、実績があるものですから、鑑定料が１０万円ですので。","id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"そこで、３０％相違があるということについて、成年後見制度利用支援事業に関しては４０％でしたけれども、それぐらいの執行額と予算額の差が出ているということについて、社会福祉を行う上においてどのように考えるか、要は予算を立てたわけですから、限りなく予算に近く、先ほどの成年後見のところで裁判所の費用、いろんな部分の、そういうところはありますけれども、本来セーフティネットたる。","respondent":"木下健康福祉事業部長","answer":"そういう意味で、なかなか見込みが難しかったです。今後やはり、家庭裁判所のほうの鑑定に対する方針等をよく見極めながら、予算の組み立てについては引き続き課題にさせていただきたいというふうに思っております。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"それを今後どのように精査をし、どのように整理をしていくのか、展望がありましたら教えていただきたい。個々の事例でいろんな性質で難しいかと思いますが、あえて頭の中に浮かんだ展望があれば教えていただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"福祉の分野ではいわゆる保険的と言ったら適切かどうかあれですけれども、やはり区民の方のニーズといいますか、行政が支援をしなければならないケースというのは、さまざまなケースがあり得るわけでありまして、そういう点では、そのような要望。","id":"exchange-095"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１３３ページの住宅用火災警報器給付事業と、あと１３２ページ、１３３ページの特養ホームの入所の関係と増設を求める質問をいたします。３年間の制度で終わってしまったんですが、消防署のほうでも未設置がまだまだあるよといったところでは、命を守るためにぜひつけてほしいんだ。ぜひ漏れなく設置してほしいという声も届いています。この点が１点です。よろしくお願いします。","respondent":"冨岡高齢者福祉課長","answer":"平成２１年の２回です。平成２１年９月です。５３６人。入所者がその対応する部分で９８人、要介護１が５７人、２が８５人、３が１７１人、４が１１６人、５が１０７人。","id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特養の入所、増設の件なんですが、私は入所者の数字を最も今回の質問で聞きたかったんですが、それが出ないということなので、今後いつごろだったら出るのか、ちょっとその確認をして、ここがわからないと状況が本当につかめないんですね。需要がどうなのかと、この分析をしっかりと目標値を示して住民に説明すべき、私は説明責任が果たされていないと思っていますが、この点はいかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"八潮南中学校、杜松小学校の跡ですが、これは何度もお答え申し上げておりますように、区がこの特養をつくりますということは、それだけ効果があるわけですので、やはり適地が見つかって確実につくれる、こういう段階になりませんと、特養については計画という形であらわせない。","id":"exchange-097"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国有地の所在地とか面積とか、情報が自治体にも入りやすいように働きかけをしているということなんですが、ぜひ品川区も国とか東京都から土地の情報を得て、積極的に貸してもらったり、譲ってもらったりということを働きかけて、早急に特養を土地がないからといった、こんなことでは区民はとても納得いかないので、ぜひそこに足を踏み出していただきたいんですが、いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"今後もさまざまな情報を集める中で、用地確保には努めてまいりますけれども、やはり特養のみでは解決できる問題ではありませんので、在宅の拡充あるいは大井林町の新しいタイプの高齢者住宅、そういう施策を組み合わせる中で。","id":"exchange-098"},{"speaker":"堺委員","kind":"提案","question":"先般も生活保護世帯の急増が大都市圏を中心に国内で深刻化する中、全国１９市による指定都市市長会は、制度の抜本的な見直しを国に求めるため、今年の秋には具体的な提案をまとめる方針だと、こういう中で、特に抜本的な制度改革、それから運営の適正化、保護費の全額国保負担、こういったものについて課題の洗い出しや具体策を検討していると、このような報道もされてあります中で、品川区におきましても。","respondent":"平澤生活福祉課長","answer":"そのところなんですけれども、端的にあらわれているところが、生活保護世帯の中では、四つの分類がございまして、高齢者世帯、それから障害者世帯、母子世帯、その他の世帯、この四つに区分されてくるわけなんですが。","id":"exchange-099"},{"speaker":"堺委員","kind":"質問","question":"それからまた、１０月１１日付の朝日新聞に同じく貧困の連鎖、これについて、この貧困の連鎖に関心が高まったきっかけは、堺市健康福祉局の理事、現関西国際大学の教授が２００７年に公表した調査結果だと、生活保護を受ける世帯主の２５％は、みずから育った家庭も生活保護世帯だったと、この貧困の世代間承継は云々と、こういうことで報道されておりましたが、この貧困の連鎖という考え方に対して。","respondent":"平澤生活福祉課長","answer":"区独自の検証ということはございませんが、ただ国のほうで平成１６年１２月に生活保護制度にかかわるあり方に関する専門委員会の報告ということの中で、貧困の再生産を防止するという観点から、生活保護費本体の部分なんですけれども。","id":"exchange-100"},{"speaker":"堺委員","kind":"質問・要望","question":"この中に、これは法内援護というんですか、扶助費というんでしょうかね、この中にいわゆる国で言っている学習支援費、これが含まれているんだろうなというふうに理解をするんですが、それでいいのかどうか。これがいわゆるさっき申し上げた東京都の塾代ですかね、これに相当するものなのかどうかということをちょっと確認しておきたいんですが、また教えていただきたいんですが。","respondent":"平澤生活福祉課長","answer":"もう一つ、先ほどご指摘がございました被保護者自立促進事業５９名とありますのは、これは法外援護ということで、東京都独自事業で、委員がおっしゃっておりました塾代の援助、こちらの経費につきましても、この中に含まれているところです。","id":"exchange-101"},{"speaker":"堺委員","kind":"質問・要望","question":"時間がなくなってしまったんですが、自立支援事業につきましても、成果報告書の３６ページの中に大変すばらしい成果があったということで報告がされておりますので、これはさらにこの事業を促進拡充していっていただきたい、こういう思いから、最近釧路市でもこれについて積極的に国のモデルとなるような事業が行われておりますので、この辺も取り入れながら。","respondent":"平澤生活福祉課長","answer":"委員のほうから釧路市の先進的な事業ということでご紹介がございましたが、私どもとしましても、それを勉強していきたいと思っています。","id":"exchange-102"},{"speaker":"川西委員","kind":"質問","question":"それから２番目の訪問介護員雇用・訪問介護員２級資格取得助成のことですが、２級のヘルパー資格取得については、資格のない人が介護施設といいますか、特養ホームに勤務をしながら資格を取るということで、施設への助成制度ということで資格取得の制度ができまして、これで人材確保、人材確保の定着事業に大いに役立っていると思いますけれども、この辺について実績等を伺います。","respondent":"冨岡高齢者福祉課長","answer":"平成２１年度につきましては、たしか４９人、２５施設が受けているというふうに聞いております。","id":"exchange-103"},{"speaker":"川西委員","kind":"質問","question":"７００円、発足当時は大変私、提供者の方からも好評いただいて、それから特に利用されている方々から大変好評をいただいていまして、いい関係にあるというふうに思っておりました。両方に関係しながら、１時間当たりの提供賃金のレベルアップについて何とか考えてほしいと思いますが、この辺について前向きにはいかがなものでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"これはまず第一に社会福祉協議会の事項ですので、理事会等のお話になってくるかと思いますけれども、これがいわゆる有償ボランティアの制度であるという、協力会員と利用会員との間の制度上の問題とかといろいろ考えた場合に。","id":"exchange-104"},{"speaker":"川西委員","kind":"質問・要望","question":"とても親切なご答弁、ありがとうあります。しかし、社会福祉協議会と区の関係性からいいますと、人材の派遣、いろんな区の職員の経験者もいらっしゃる。要望として申し上げておきます。しかし、福祉施設において、有資格のヘルパーの人材をもっと求めているんではないかというふうに思いまして、この制度をもう少し国から補助金が出る制度だと思いますので、積極的に進める考えというのをお聞かせください。","respondent":"冨岡高齢者福祉課長","answer":"今はケア協議会と連携をとりまして、ヘルパーの講習の助成はしていますけれども、やはり介護報酬の改定に伴いまして、独自で、やはりそれから介護の人材の雇用給付金等もありますので、独自で経営ということで取り組んでおいでになると思いますので、それにつきましては。","id":"exchange-105"},{"speaker":"川西委員","kind":"質問・要望","question":"ちょっと１年以上前になりますけれども、さくら会に無資格でアルバイト的にといいますか、無資格だと短時間しかアルバイトをさせていただけない。私は、やはり今の、現状にとどまらずに、こういう中高生の居場所というのをもう少し考えていただけないかと思いますが、児童センターの運営費の中で、この部分についての平成２１年度の現況、そしてこれからどういうふうになさろうとしているのか伺います。","respondent":"安井子育て支援課長","answer":"さらにこれからここで活動していた方たちが地域のイベントであるとか、そういったところに出かけていって、社会活動みたいなところでより広く地域とつながっていけるように活動を支援してまいりたいというふうに考えているところです。","id":"exchange-106"},{"speaker":"川西委員","kind":"質問・要望","question":"こういうことで、私は本来的には行政がそういうときに、ほっとしたいときに、１時間ぐらいコミュニケーションをとるところが必要だなというふうに思っていますので、中学生の、高校生はちょっと大きくなってばらばらですからあれですけど、中学生のそういう何か午前中の授業だの、試験だのというときの後に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"私は成果報告書の２０３ページ、特定健康診査に関連をして、先ほど渡辺委員も質問しましたが、その後追いで質問します。それからあと１４０ページ、家庭教育支援事業について質問します。それを今ＰＲでいいんですかということですよ。やっぱり、受診率を具体的に上げていくことを考えていくとか、そういうものを具体的に示すべきじゃないんでしょうか。お願いいたします。","respondent":"本城国保医療年金課長","answer":"そのために、制度が始まったばかりでございましたので、当初ＰＲ等を中心に対応していまして、その中で、一般的なＰＲだけではとても足りませんので、個別の受診勧奨を今年から３回に増やしたり、受診しやすい環境づくりということで。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ある程度安心、そういう話を聞くと安心するんですよ。万が一それが何億円単位になったとするならば、それは今から年度計画をつくって、それに対する受診率を上げていくことのほうがはるかに税の出費は少なくなるわけだから、そのことについてぜひ進めていっていただきたいということをお願いしたい。もう一言、答弁をお願いいたします。","respondent":"本城国保医療年金課長","answer":"今の繰り返しになる部分もあるかもしれませんが、現在私どもとしては、特定健康診査の重要な意義を十分認識して、計画を達成するために可能な限りの手段を尽くして、平成２２年度もより充実させていく方向で頑張っていきたいと考えているところです。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひ年度を区切った対応をしっかりお願いいたします。ですから、すべてこれらに共通しているのは、家庭の問題ですね。だけれども、この支援事業の中で、親育ち教育なり、それから親の指導なり、昔はおじいちゃん、おばあちゃんがいて、できたことが今できていないわけだから、そういうことについて、広い意味で対処できる仕組みを検討してみてはいかがでしょうか。ご答弁をお願いいたします。","respondent":"安井子育て支援課長","answer":"これはちょっと児童虐待のほうもやはり同じような問題があるかなというふうには感じております。そこら辺につきましても、今後何らかのいろいろ研究をさせていただきまして対応方法を考えていきたいというふうに考えております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私も難しいと思いながら質問しているんですよね。だから、そういうことについては、さらに研究とお話をいただいたけれども、乳児、幼児、保育園、小学校まで含めた上で、表現はなかなか難しいのだけれども、教育面だけじゃなくて、今お話をさせていただいたような家庭支援と言ったらいいんですかね、そういう観点からも再度制度を検討してみたらいかがでしょうか。ご答弁をお願いいたします。","respondent":"小林青少年育成課長","answer":"現状では、青少年問題協議会を方針決定の機関として各団体が連携して育成に努めておりますけれども、この動きを核として、今後も地域で一層連携を密にして、子どもの育ち、青年層の自立まで一貫して見守っていき、育てるような体制の充実に向けて努力をしてまいりたいと思います。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"それからもう一点、先ほど来、出ております生活保護に関連して質問いたします。先ほどそうだったですよね。だから、この５,４００万円、これはすばらしいことなんだけれども、これからさらにこの制度を具体化していくため、つまり、自立を促していくための品川区の方向性の再度の確認と、それから先ほどお話があったように、親の面倒を見るために子どもが学校に行けずに生活保護を受けることもあった。","respondent":"平澤生活福祉課長","answer":"こういった方に関しましては、ケースワーカーも含めて支援の体制を強めていきたいと考えております。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"これはどこまで増えるんでしょうか。それを品川区はどこまで補助していくんですか。仕事中です。その運営の仕方、区ですべき役割というのと、今後この児童センターの運営はどういう方向に行くのか、それから指導員はここ数年間何人かとっていただいていますけれども、やはり区の職員はこれから増やしていただきたいというふうに思いますので、その採用についての今後の動向をお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長、安井子育て支援課長","answer":"区といたしましては、今委員からお話がございました認証保育所の開設支援、それと短時間就労型対応保育所の開設。ついては、整備した認証保育所については、運営費の補助をするとともに、利用者の方についても一定の助成をしていくと、そのような考え方です。パパが参加するような講座もこれから予定していますので、そちらのほうで対応するというふうなことで考えております。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"特長を持たせようということが始まっています。認証保育所もですね。親たちの要望も変わってくるし、事業者のほうも変わってくるだろうというふうに思いますので、そのところについては注視して、しかるべきところでの投資、助成とかを考えていただきたいと思います。最後に、児童センターの指導員は区の職員を増やしていくんですか、増やしてくださいという要望に対してのご意見をお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"やはり、すまいるスクールに登録される方が圧倒的に多いということですので、それを事前にどういったところであるかということを体験していただくのは非常に重要だと思いますので、教育委員会とも協力しながら、そこら辺のところを進めていきたいというふうに考えております。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は１４４ページ、生活保護費について、先ほど進学支援にありましたそのお話を聞きたいと思います。そして１３２ページ、高齢福祉費で特養ホームについてお聞きしたいと思います。最初に、生活保護世帯の子に進学支援を拡大している、先ほどもほかの委員からお話がありました。だから、しようがないから福祉のほうで支援をしていくんだと、そういうことなんでしょうか、お聞かせください。","respondent":"平澤生活福祉課長","answer":"先ほどご紹介いたしましたのは、次世代育成支援ということで、東京都の事業です。前年度助成されたのが９家族、生徒数にしまして１０人ということで、母子の世帯がほとんどだということでございました。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとある資料によりますと、教育は学校の役割ではないか。自治体には戸惑いも残っていると。首都圏のあるところの生活保護担当課長は、こう言っています。「本来は公教育がやるべきこと。でも、現実に低学歴が自立の壁になっている。したがって、守備範囲を超えているかもしれませんが、やるしかない」ということをうたっているんですね。止まるよということを言っているんですが、それはどうなんですか。","respondent":"平澤生活福祉課長","answer":"法律の中に入っているのは、参考書代とかクラブ活動助成費に当たる学習支援費が去年の７月から新たに入ってきた、そういったところですので、あくまでも法外援護ということで、行きたい方に関する意欲を援助していく、そういう形でやっております。","id":"exchange-116"},{"speaker":"須貝委員","kind":"意見","question":"今やりたい人がいたらどうぞという話じゃなくて、このままいったら大変でしょうという私は意味のあらわれだと思うんです。今、国のことを、見解を察するならば、なぜこういうふうにできるんですよということを例えば学校で配らないのか。個別に郵送したっていいんだし、私は本当にやはり子ども一人ひとりのこと、それからこれから日本を担う子どもたちのことをやっぱりしっかり考えてほしいなと思います。","respondent":"本城国保医療年金課長","answer":"そんな中で、恒常的な低所得の方への保険料の措置ですが、基本的には、恒常的には保険料の７割軽減する、５割軽減する、それから２割軽減するという措置がございまして、７割軽減についてが約３４％、５割軽減が２％。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"ただし、医師や弁護士などには自前の国保組合という制度はありますと。そこでちょっとお聞きしたいんですが、そもそも国家公務員の皆さん方は、国民の生活を安定させるために奉仕する立場のはずですが、どうしてここで国家公務員の共済組合の保険と一般の今言った国保、国民健康保険がなぜ一体にならないんですか。実際なら一緒にやらなきゃいけないんじゃないかと思うんですが、ちょっと教えてください。","respondent":"本城国保医療年金課長","answer":"そもそも健康保険制度ができた歴史的沿革からいきまして、初めにできたのが主に工場あるいは企業に勤めている人たちを対象にした健康保険が沿革的には先行して実施されたところです。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問・要望","question":"私はここで、じゃあ何が決められるんだという話じゃないんですが、実際それだけ大変ならば、本当は共済組合も一緒になるべきだ。でも、実際今、法的になれないということならば、もっと困っている人たちに厚い支援というのをもっと積極的に予算組みして出すべきじゃないかな。実際これだけ困っている人がますます増えていく現状をどう見ているのか、その辺についてお聞かせください。","respondent":"冨岡高齢者福祉課長","answer":"区といたしましては、制度の中で最善のケアを尽くしてまいりたいと思っているところです。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に我々、委員の皆さんも本当にまちの中を歩いたら、いや実は民間の老人ホームにいたんだけど出されちゃった。病気をしたから出されちゃった。それも長期入院。さらに大病をしちゃって、それで自宅で引き取る。それはやっぱり大変なことだと思うんですね。それは高齢者がますます増えるわけですから、その辺のことを身近な区としては、私はできるだけケアしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"１３９ページの認証保育所利用助成制度についてお聞きいたします。この事業の目的をお聞かせいただきたいと思います。これは平成２１年度の決算ですが、評価についても同じくお聞かせをいただきたいと思います。","respondent":"吉岡保育課長","answer":"評価ですけれども、決算のほうに書いてありますけれども、延べ４４１人の方に助成をしたということで、認可保育園の補完的な機能としての認証保育所をご利用いただく上で一定の成果を上げたものというふうに理解しています。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"平成２２年度になるとまた中身のさまざまな運営方法ですとか事務作業とか、また募集に当たってとか、さまざま変化しておりますので、現在とられている手法、それからその後いわゆる改善点の問題については、やはり４カ月分が約半年後に振り込まれてくるという今の厳しい実態についての検討をするというご答弁が以前一般質問でもございましたけれども。","respondent":"吉岡保育課長","answer":"それで、やはり保育園の保育料につきましても、基本は所得で決まってきますので、その辺の所得の捕捉の仕方等々、システムの活用とか、今省力化できるところはないかということで検討はしていますけど、今年度から始めた事業ですので。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"問題はここからですね。ぜひ平成２３年度から、やはり私、区民の訴えを聞いている立場からすると、一日も早く、またぜひとも平成２３年度の４月１日から新しい体制にしていただきたいというふうに思います。そこで、今なかなかめどがつきませんというところで、できない理由をもう少し詳しくお聞きしたいと思います。そこで、ここについてもう一回ご答弁をいただけますでしょうか。","respondent":"吉岡保育課長","answer":"技術的な問題、難しいところは、大きく言って２点あろうかと思っています。１点は、所得のやはり捕捉、保育園保育料が幾ら支払われるであろうかということを決めるのが所得の捕捉になってきます。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問","question":"そこからいたしますと、今ご答弁いただいて、なかなか難しいというお話がございましたけれども、そうですかというわけにはいかないということで、この質問をさせていただいているわけです。でも、そこができないから、どうしても認証保育所に二の足を踏むという方、２種類大まかにいらっしゃると思います。今のご答弁の上に、もう一歩さらに踏み込んだ区民の声にこたえられるようなご答弁をお願いいたします。","respondent":"吉岡保育課長","answer":"今委員、まさにおっしゃられたとおり、認可保育園に通っているのとほぼ同等のご負担でというのは、新しい平成２２年度からの制度の趣旨ですので、その方向に向けて十分検討してまいりたいと思いますけれども、保育課だけではなく、区役所全体、少数精鋭でやっておりますので。","id":"exchange-124"},{"speaker":"若林委員","kind":"意見","question":"最後の職員の大増員とか、そういうところにちょっと引っかけられましたけれども、認証保育の運営費の助成が都からも、また区の一般財源からも多くの補助が入っております。そういう意味では、認証保育所のご協力とか、外部の方のいわゆるシステム的にご協力というのもあると思いますので、ぜひともさらなる創意工夫をよろしくお願いをして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"最初に、社会福祉総務費のほうは、成果報告書の一番下に、介護保険利用者負担金軽減措置事業３万８,０００円ということがあるんだけども、ここはどういうことなのかというのと、こういう一般会計のところに介護保険というか介護保険利用というのが、こういうところに入ってくるのはどういう意味なのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この介護保険利用者負担金軽減措置事業ですけれども、前年度に介護保険を利用された方で、障害者のサービスを受けた方が６５歳以上になって、引き続きサービスを受けた方、これは減額される対象でございまして、その部分を事業化したんですが。","id":"exchange-126"},{"speaker":"須藤委員","kind":"意見","question":"そうやって去年はそういう返還金というのはなかったんだけど、今年になって増えてきちゃっているんですが、この辺は障害者福祉に対して、それぐらいの仕事が十分にできなかったのか、あるいは予算上立てて、これだけやるぞとやって考えたけど、なかなか無理だったというのか、いろんな考え方があるだろうと思うんだけども、今までにないくらいに返還金というのが。","respondent":"永尾障害者福祉課長","answer":"国の補助金、都の補助金の返還金の件ですが、交付の決定をするのが年度の途中でございまして、見込みを、その後変更決定というのを１月ごろに行います。そうすると、その後に変化が、いろいろな利用者の増減がありますと、翌年に精算をするというような方法をとっております。","id":"exchange-127"},{"speaker":"須藤委員","kind":"意見","question":"逆に、デメリットがすごくなってきちゃうと、またこの後何十年とそこを使わなきゃいけない建物なので、その今の建物、既存を残すということは確かに物を大切にするという考え方だけれども、じゃあその後、２０年、３０年使ったときに、不便さがあるよ、それはもともと学校として建てたものだから、社会福祉施設としてあるものじゃないんだから、そこを緊急的にやるというならばわかるけども。","respondent":"冨岡高齢者福祉課長","answer":"この次の部分につきましても、やはりその施設を見て、これは全体的に今は八潮の施設もそうですが、やはり区民にご利用いただくという開放的な部分もありますので、トータルを考えて。","id":"exchange-128"},{"speaker":"須藤委員","kind":"意見","question":"今度杜松小学校はどのぐらい年限がたっている建物なのかな、校舎として。八潮はまだ二十何年ですよというから、建物としてあと何十年とまだ使えますよ。杜松小学校については、将来的にはどういうふうに考えますか。","respondent":"久保田行財政改革担当課長","answer":"杜松小学校ですけれども、杜松小学校の校舎につきましては、おおむね３５年から４０年ぐらい経過をしているというものですので、改修して使えば２０年から３０年ぐらいは使えるものだというふうに考えておりまして、そうした意味でも校舎を活用して。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、今言った４０何年たっていますよというときに、普通ですとそろそろ交代だよと、５０年でという時期に、またそこを使ってあと何十年間というと、そうすると、やっぱりいいものをつくっておいてもらいたいなというような思いがあるので、そうすると、今の校庭のほうに逆にしっかりした施設をつくって、今の校舎を壊して今度グラウンドにするとかというような、広い土地ですから。","respondent":"久保田行財政改革担当課長","answer":"杜松小学校につきましては、位置的にも非常に狭い道路の中にあるというところが１点ありますので、なかなか大規模な改修工事というものが難しい状況にあるというのは我々としても踏まえているところです。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問・要望","question":"最後に、国保で１９０ページの、先ほどもちょっと出ていましたけども、滞納繰越金があったり、介護保険で滞納したりなんかすると、今度介護保険自体が使えなくなっちゃうのか、あるいは介護保険料を支払っていないで、何年間後に介護が必要ですよといったときに、そういったものは利用はどういうふうになるのかお聞かせください。","respondent":"冨岡高齢者福祉課長","answer":"介護保険の未納の方への対応の仕方ですけれども、サービスをお受けになっている方にはサービスをお受けになっていますけども未納ですよという通知を差し上げている段階でございまして、それでよくご相談をして納めていただくというような段階です。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"その後はまだわかりませんと。どういうふうになるんだか、ちょっとわからないんだけど。たまたまひっくり返って介護が必要ですといったときに、介護保険を払っていないからだめですよというのが普通だろうと思うんだけど、そのあたりはどういうふうになるんですかと聞いているので。もし、今まで払わなくて、二十何年間まとめて払うから介護保険の適用にしてくださいと言ったらどうなるのか。","respondent":"冨岡高齢者福祉課長","answer":"すみません、ちょっと説明不足です。当然未納な方にはお知らせをして、ご利用いただくときには償還払いといいますか、１０割払っていただいて、９割お返ししていくというふうな流れになると思います。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問","question":"１９９ページにいわゆる医療費のところで、項目の２が高額療養費で、次が４の出産育児諸費になって、３の移送費というのが抜けているんだけども、移送費はゼロだからこういうときには書かないのか、ゼロだったら書かないでいい形になっているのか、項目は入れて、ゼロというふうにやるのが普通なのか、予算ではちゃんと入っているけど、それは使わなかったよといったら、２、４と飛んで、項が飛ぶのか。","respondent":"冨岡高齢者福祉課長、金子企画財政課長","answer":"１０割を払っていただきまして、９割については保険料を入れていただければお返しをすると、償還払いです。決算書のほうにはゼロでも載せますけれども、実績調書のほうはゼロでしたので、逆にこちらのほうには載せていない、そういう関係です。","id":"exchange-133"},{"speaker":"須藤委員","kind":"意見","question":"書き方として、その項はあるけど、ゼロのときは項を飛ばしていくという形が決算のやり方でいいわけですね。そういうふうに考えて、見たときに、ぽんとゼロならゼロで、ああこうだなとわかるんだけど、ぽんぽんと飛んじゃうと思ったんですけども、書き方としてはそういうのはなしでというのが当たり前だというふうに理解しておいていいですね。","respondent":"金子企画財政課長","answer":"委員ご指摘のとおりです。","id":"exchange-134"},{"speaker":"土井委員","kind":"質問","question":"ということで質問するのが１点と、それから子どもたちの問題で、保育園、認定こども園、幼保一体施設、公私立の保育事業等々、１３８ページから１４０何ページにいろいろ出てきているわけですけど、以前にも質問した経緯があるんですが、この辺についての考えを後から伺いたい。ここにある例えば今言った二つの事務用経費というのは、中身は何でしょうかというのをまず最初に聞かせてください。","respondent":"金子企画財政課長","answer":"この１３２ページの事務費ですけれども、こちらは障害者の管理システム等々のシステム関係の改修、維持、管理がメインになっておりまして、そういう意味では事務用経費と事務費と区分けして書いてある部分については、細かい差異というのがない部分もありますけれども。","id":"exchange-135"},{"speaker":"土井委員","kind":"質問","question":"と思ったから聞いたんです。要するに、これがどこにも入らない事務費ですと言われたら、みんなが事務なんで、どこかに入らなきゃいけないはずですから、それをお伺いしたということです。それを進めるためには、私立の幼稚園との関係はどうやっていけばいいのか、やっていかなきゃならないのかというところが大きな課題ではなかろうかなと思うんですけれども、その辺についてお伺いしたい。","respondent":"吉岡保育課長","answer":"こども園につきましては、今のところ来年度の通常国会に法案が上程されるというふうに聞いてありますけれども、その辺の動向を踏まえながら今後検討していくことになろうかと思いますが、いずれにしても区としては。","id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"私も昔からいっているんですけど、教育だけ必要な子どもとか、保育だけ必要な子どもなんていないわけで、それをバランスよくしっかりとやっていくというのが本当の究極のところでなきゃいけないと思っているので、それが例えばどう名前をつけようが、どう呼ぼうが、そうなんだという精神を持っていないと。","respondent":"吉岡保育課長","answer":"それで今現在、幼保一体施設でやっている幼稚園、保育園、３園あるわけですけれども、そちらのほうに配置をする保育士については、両方の資格を持っている人を重点的に配置をしていますので、そういう意味では人材の活用も行われているというふうに考えているところです。","id":"exchange-137"},{"speaker":"土井委員","kind":"質問・要望","question":"今言ったように教育と保育がバランスよくいくということによって、子どもたちの心の安定も含めて育ちに影響していくのではないかというふうにも私は思っておるものですから、ぜひその意味でバランスよくやるためにも、資格を一緒に持つように、持てるように援助する、支援をすると、こんなようなことも進めていただければありがたいなと考えています。これは要望だけしておきます。","respondent":"本城国保医療年金課長","answer":"国民健康保険の被保険者についても同様の仕組みがございまして、同じような形で２,０００円の補助をして利用していただくという形になっているものです。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問","question":"国保も同じものがあるとすれば、それをやっぱりどう使ったらいいのか、それの部分とそれからもう一つ、我が品川区が持っている保養施設の部分というのをうまく活用しなきゃいけないわけで、その意味では国保や後期高齢者の方々には、これも含めてこういう制度がありますよ、しっかり健康増進のためにやってくださいよというのは、先ほど６５％受けなきゃいけないというのと似たようなもので。","respondent":"本城国保医療年金課長","answer":"知っていただくことが利用の第一歩にもちろんなってくるわけですので、国民健康保険ですとか、あるいは後期高齢者医療の中ではいろんなＰＲをする中で、ご利用をいただくようにＰＲをさせていただいているところです。私どもの課の関係ではそのような形で周知しています。","id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"１３８ページ、高齢者住宅等整備費について伺いたいと思います。ここに掲載されているのは、用地取得費と基本設計の費用ですけれども、大井林町の高齢者住宅のことなわけですけれども、どのような内容の施設なのか、あるいは建設費、用地費等々で補助金はどこからどのくらい来ているのかということも含めて対象者、家賃設定、どういうふうに考えているのか教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この施設につきましては、高齢者住宅を７０戸、それから住み替え用の住宅を２０戸、あわせて１階に小規模多機能型居宅介護事業所、それと訪問看護ステーション、それと在宅介護支援センターを一緒に併設してまいりまして、高齢者住宅にお住まいになっても。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"昨年の第３回定例会の区長の答弁で、「ある程度介護が必要になっても安心して住み続けられる低所得者向けの住宅整備が必要と考える」、こういうふうに区長が答弁されています。この考え方は、今でも同じなのかどうか。ちょっとその辺を区長にご答弁いただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"今回の住宅ですけれども、従前の高齢者住宅ですね、２１９戸ありますけれども、こちらよりは生活支援機能を強化しておりますので、そういう意味では全体の利用料は今精査中でありますけれども、それよりは高くなるだろうというふうに考えておりますが、しかしながら。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"私が伺ったのは、今ちょっと説明いただきましたけれども、低所得者向けの住宅整備が必要、こういうことで変わりはないかということを確認で聞いたんですけども、その点についても改めて伺いたいと思います。本当にそういうことを大事にして推進していきたいというのであれば、やっぱり本当に安心して輝く笑顔を持ち続けて暮らしていける、そういうことが大事だと思うので、ちょっと伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"低所得者という定義はありませんので、その範囲をどういうふうに考えるかというところはいろいろあろうかと思います。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"そういうコンセプトで長期基本計画をつくられた、そこのところにくっついていた、本当に品川区でよかったと、こういうふう評価される道になっていくと思うので、その辺についてしっかりと検討していただきたいし、見解を伺いたいと思います。それからもう一つ、１４１ページの保育園運営費、ここも伺いたいと思います。そして、あわせて今年度の定員拡大数、ここも伺いたいと思います。","respondent":"木下健康福祉事業部長、伊崎待機児童対策担当課長","answer":"今回予定しておりますのは、先ほど申し上げたような高齢者像を前提に考えております。ご指摘のような方々につきましては、現在高齢者住宅２１９戸がありますので、この基盤で対応していきたいというふうに考えているところです。そのほか、年度途中にオアシスルームを児童センターに移設したなどの関係で、定員の弾力化をあわせて４０名ほど図っております。","id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"平成２２年度のもあわせて伺ったので後で教えていただきたいと思います。ですから、その辺については十分考慮するべきだというふうに思いますので、ぜひ減免制度、そういうものを所得の一定程度のところを考えているんであれば、私は減免制度をつけるべきだし、国民年金の方をやっぱり対象にした施設設計をしていただきたい、このことをもう一回強く申し上げて答弁を求めたいと思います。","respondent":"木下健康福祉事業部長、伊崎待機児童対策担当課長","answer":"これは公営住宅ではありませんから家賃減免もありません。高優賃制度に基づく家賃の補助金があるです。先ほど申し上げました定員拡大ですが、申しわけありません、そちらが平成２２年度です。平成２１年度につきましては、４月の時点で公立保育園を１５名定員拡大しております。","id":"exchange-144"},{"speaker":"三上委員","kind":"質問・要望","question":"それから２点目、高齢者世帯の安否確認ということでありますけれども、これについては防災面からも言えると思いますけども、高齢者のひとり暮らしの方たちの安否を確認する上で、冷蔵庫に救急カプセルと、こういうことが随分推奨されているわけですけれども、こういったことについての取り組みというのはどの程度品川区の高齢者の方はされているのか、現状的な部分がおわかりになれば。","respondent":"間部高齢者いきがい課長、冨岡高齢者福祉課長、永尾障害者福祉課長","answer":"来年度につきましては、現在のところは現行の体系で、横引きで、現状維持で実施するということを予定しておりますけれども。これにつきましては、区では孤立死防止の見守りネットワークの中で、町会・自治会で取り組んでおられるところが１町会３自治会ございまして。そちらで検討して、必要だという判断になったときに導入するようにしております。","id":"exchange-145"},{"speaker":"三上委員","kind":"質問","question":"いろんなところに絡んでいるわけですから、これをどういうふうに全庁的に整理していくのかということになってくるわけであって、一つの課の課長からお答えいただいても、それはそこの課で取り組むことである。今後についてどうするのかということですから、全体を取りまとめていくところがそれを答弁しなければならないわけでしょう。そこのところをまずお答えいただけますか。","respondent":"久保田行財政改革担当課長","answer":"私どもこういったものにつきましては、ここに書かれているものにかかわらず、今回事務事業評価をやった中で、いろいろと輻輳している事業があるなという認識を持っているところです。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問・要望","question":"安否確認の件について、要するに今取り組んでいるところがありますよという答弁ですよ。要するに全体的に品川区として、そういうふうな高齢者の意識としてどうなのかなということでちょっとお伺いしたつもりでいたんだけれども、それを、では補助するならするで、全町会にすべてそういうことでやりますということでこれは公表してあるんですか。","respondent":"冨岡高齢者福祉課長","answer":"救急キット自体はそもそも、いわゆる全町会的にどうこうということは区としては今のところ考えておりません。町会として、これは見守りをする上において必要だろうという判断をされたところはその方法を選んでいただければ助成をするというような考えです。","id":"exchange-147"},{"speaker":"三上委員","kind":"質問・要望","question":"もうちょっと幅広く。ところが、あけたはいいけども、全然何も入っていないということの繰り返しだったら、やっぱり困るんであって、ぜひともしっかりと品川区のほうからこういう取り組みについてもやっていかれたらどうでしょうかと区民の皆さんに啓発をしていただきたいと思うわけです。それから、音声コードについては、しっかりと来年度に向けて取り組みをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"松澤委員","kind":"質問","question":"私からは１３８ページ児童福祉費に関連いたしまして、待機児解消策と保育ママ制度についてお伺いをしたいと思います。たくさん質問と答弁がありましたけれども、改めてお聞きしたいと思います。それともう一つは、０歳児、１歳児、２歳児、３歳児、これの認可保育園での１人当たり、今どれぐらい経費がかかっているのか、その辺をお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"来年度４月には私立保育園、認可保育園の２園の開設を予定しております。認証保育所４０名定員の保育園の１園の開設を予定しております。このほかにも今必要に応じて検討をしています。１歳児につきましては２４３万円程度、それから２歳児については２４０万円程度というふうに考えてあります。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問","question":"保育ママ制度に入ります。保育ママ制度は、昭和４４年から平成１４年まであったんですね。その当時の保育園は定員割れをしている状態でした。それと同時に、だんだん０歳児の受け入れを増やしていく。そんな中で保育ママ制度がなくなっていったのかなというふうに思っているんですね。委託料はどれぐらいなのか、利用料は幾らぐらいなのか、その辺についてお伺いしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"こちらにつきましては、今後の利用者の状況等を見ながらも変化はしていくものであるとは思いますが、現行ではそのような形で進めていきたいと考えております。","id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"委託料が８万円でしょう。今、０歳児は認可保育園では５８０万円、平均すると４０万円以上だよね。１歳児、２歳児は、２４３万円、２４０万円で、１人２０万円、１歳児、２歳児はかかっている。やっぱり、保育ニーズの多様化の中では、品川の保育はすばらしいと、その考えがあり過ぎるんではないですか。その辺の考え方について、間違っているかどうかお聞かせください。","respondent":"伊崎待機児童対策担当課長","answer":"委託料ですが、８万円のほか、年間７２万円をお渡ししていますので、保育ママの収入といたしましては、保育料も含めて４００万円ほどになると考えております。今の制度上の位置づけですけれども、先ほど申し上げましたのは、児童福祉法上の位置づけです。","id":"exchange-151"},{"speaker":"松澤委員","kind":"質問","question":"保育ママ制度、私が議員になったころに盛んに質問したんですけども、また復活してきたので、この問題についてもいろいろ取り上げたいと思うんですけれども、やはりニーズの多様化の中でいろんな人がいるんだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/696113?Template=document&Id=1328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":116505,"voices":358}},{"id":"h22-20101105-4","meetingId":"h22-c-settlement","date":"2010年11月5日","dateIso":"2010-11-05","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を152件抜き出しています。","topics":[{"id":"topic-01","title":"◯鈴木委員長 ただいまより決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"◯鈴木委員長 ただいまより決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"結果として多くの方々に受診されていないということも聞きましたので、やっぱりそういうことについては品川区も考えなければいけないだろうし、ほかに子宮がん、乳がん等もありましたけれども、特にこの胃がん検診だけはそのような現状があるということを聞きましたので、まずこの受診率に対する品川区の見解と、具体的なそれを向上させるための対応をお伺いいたします。","respondent":"山岡健康課長","answer":"検診の内容についても、今後もう少し簡単な検査方法があるかないか、こういうことも含めて検診については考えてまいりたいというふうに考えております。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"提案","question":"だから、当然、費用対効果も考えなければいけないけれども、確かなことは、胃がん検診の受診率を上げなければいけないということ、大きな目で見れば、保険料を下げなければいけないわけでありますから、そういう具体的な提案が、医師会から具体的に出されていると思いますが、そのことに対して現時点での品川区の対応、それから目黒区の具体的な成功例があります。","respondent":"山岡健康課長","answer":"国でも研究に取り組んでいるですので、私どもとしましては、この研究の状況を見守りながら検討してまいりたいと、これは既に私どもも検討しているところですが、直ちに取り上げるのはどうかという段階です。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"これは９０１６事業が平成２０年度から始まりました。いろいろお話をお伺いしていきますと、この９０１６の受賞者は非常にお元気で、背筋もピンとされておりまして、歯の健康が全身の健康につながっているということがよく理解できるということを目の当たりにするわけでありますが、この９０１６達成のためには、歯周疾患改善指導が現行は７０歳までで今は終わっているわけですね。お願いいたします。","respondent":"山岡健康課長","answer":"ただ、これから先、高齢の方が増えてくる中で、さらに足伸ばしをする必要があるかどうか今後の検討課題とします。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ十二分に検討してください。それから、これは要望だけですが、成人歯科健診の委託料等は、１２年間据え置きされているとも聞きましたので、これはぜひ具体的な対応をお願いしておきます。それから、まだ正式に確認はしておりませんけれども、この問題に対して２３区で新しい組織をつくって動き出すようなこと、それがまた課長会で承認されたような話もちらちら聞こえてくるんです。お願いいたします。","respondent":"太田品川区清掃事務所長","answer":"今回、今後の取り扱いを含めるということで、清掃一部事務組合、清掃工場副工場長、それから関係の課長会、私どもの課長会も入りまして、不適正搬入防止検討委員会というものを今般、来週早々にも立ち上げてまいります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もうあんまり時間がないのであれですけれども、要は、３億円の税金が支出されたということに対して原因がわからなかったわけですよね。だから、私たちとして非常に思うのは、再発防止策と、２３区の組織、今改めて聞きましたけれども、それがさらに着実な成果を上げてもらうように品川区からも言っていただきたいと思いますが、最後に一言だけ、決意だけお聞かせください。お願いします。","respondent":"太田品川区清掃事務所長","answer":"ご指摘のとおり、それは区の負担、分担金が入ってあります。それはひもとけば税金になってくるですので、清掃一部事務組合に対しては、課長会、部長会を通じまして厳しく意見をしていきたいというふうに考えてあります。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"１つには、この特定健診というのは今までの区民健診の基本的な健診が多く含まれているということもありまして、それにさらにがん検診という考え方でやられてきたと私は思うんですけれども、今後の取り組みについて、この件についてはまずお伺いしたいと思います。これは皆様もご存じのことかと思いますけれども、サラリーマンの方が会社で年１回の規定される健診を受ける。","respondent":"山岡健康課長","answer":"それで、このそれぞれの医療保険者が実施した特定健康診査、これについて、これは区の場合は国保課のほうでやっているわけですけれども、それを区民全体のこれからの健康づくりにどう生かせるかどうか、まだ特定健診制度が始まって２年、今年で３年目ということですので。","id":"exchange-006"},{"speaker":"浅野委員","kind":"提案","question":"２年前になりますけれども、平成２０年の第２回定例会で特定健診の質問をさせていただいたときに、区内の病院をいろいろな病気で訪れた方に対しまして、この方が国民健康保険に加入している人であれば、特定健診をその場で受診を勧めたらどうかというような提案もさせていただきました。これは実際に行われているのかどうか。","respondent":"山岡健康課長","answer":"医療機関で可能な限り同時受診をしていただくように、例えばがん検診の受診医療機関で特定健診が可能ならば同時受診をしていただくという方向で、今、国保とも連携して取り組んでいるところです。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"どうもありがとうございました。次の課題ですけれども、低公害車の導入促進事業ですが、２５台で２１８万円の予算に対しまして３分の１にとどまっているわけですけれども、助成の台数を含めた当初予算との差異、こちらについてお伺いします。平成２１年度はシミュレーターを利用した鮫洲の運転試験場での実技指導、こちらのほうをやられているようですけれども、参加者数はどうだったのか教えてください。","respondent":"工藤環境課長","answer":"今回、平成２１年度は、講習会、教習会ということで、実技的な教習会と、もう１つは講習会という部分を予定されていたんですけれども、当初、講習会の中でドライビングシミュレーター装置というものを３台活用する予定でございました。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"今年度は、次世代自動車、電気自動車とプラグインハイブリッドの助成があるわけですけれども、４台という枠ですけれども、この現状について、また枠が埋まらなかったらそのまま続けるということですけれども、こちらのほうについてお伺いします。こちらのほうを講演会とか講習会で利用するという手もありますので、そのようなことについて今後の取り組みについてお伺いしたいと思います。","respondent":"工藤環境課長","answer":"現在の状況ですけれども、２台の方の申請が出てきている状況です。続きまして、エコドライブの今後の取り組み等ですけれども、私ども、今年度に関してはエコドライブ講習会、１０月２４日の日曜日にもう既に実施したところです。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"お聞きしたい１つが、地域経済に与える影響なんですけれども、前回の質問でも申し上げましたけれども、地域的にはまだまだおふろがないようなアパートもあるような地域なんですけれども、地元の不動産屋にお聞きしたところ、銭湯がなくなると入居者が激減していく、あるいは家賃も低く設定せざるを得ない、こういうことでした。","respondent":"山岡健康課長、福島ものづくり・経営支援課長","answer":"地域経済に与える影響という観点からですと、私の守備範囲をちょっと逸脱してしまうんですが、その次の出会いの湯のほうからお答えしますと。そういう意味では、さまざまな産業が発展するように全方位的に支援していくのが区の役割だと思っていますので、私どもとしましては。ただ、若干いらっしゃるということで、やはりそういう方の衛生上のことを考えますと、一定程度。","id":"exchange-010"},{"speaker":"菊地委員","kind":"提案","question":"昨年お聞きしたときには、出会いの湯に来られる方も含めて、１つの銭湯で１日約１５０名ぐらいというお話がありましたけれども、今お話をした東大井の銭湯ですけれども、ここを利用されていた方が経営者のご家族と話をされた際に、私、前回、区立浴場の提案をしましたけれども、区が営業を支援してくれるのであれば再開したいと、マンションにはしたくない。","respondent":"福島ものづくり・経営支援課長","answer":"銭湯に対する支援ですけれども、私どものほうでは、経営支援相談等を行ってありますので、その銭湯を継続して行うためにはどうしたらいいか、そういったことにつきましては十分相談に乗ることはできますし、また融資あっせんということも使えますので。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"先ほど、適正な配置が必要だというお話がありました。公衆浴場ですから、区としても先ほどのお話ではないですけれども、区民の健康を守っていく上で必要なものだというお話がありましたから、区のほうから積極的にこうしたところに声をかけていくことが必要なんだというふうに思うんですね。改めてその辺をお答え願えますか。","respondent":"山岡健康課長","answer":"もし検討するとしても、慎重に考えていかなければならないというふうに思っております。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、先ほど申し上げたように、実際になくなったんですよね。先ほど、出会いの湯の目的をお聞きしたんですけれども、健康づくりを目的にしているということでしたけれども、公衆浴場が実際にその地域からなくなっていけば、その機会というのは、言ってみれば永遠に失われるということになるんじゃないでしょうか。","respondent":"山岡健康課長、福島ものづくり・経営支援課長","answer":"そういう意味でも、出会いの湯の取り組みで公衆浴場の場合によっては支援になっているのかなと、出会いの湯は毎週１回ですけれども、それを機に毎日公衆浴場を使うという方も当然出てきていらっしゃいますので。そういった中ではどれだけ需要があるのか、そういったものを分析した上で支援をするということが可能ではないかというふうに考えてあります。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"どれほどの需要がというのは、先ほども話しましたけれども、１日に１つの銭湯に約１５０名ほどの皆さんが利用するという状況があるんです。５年ほど前に公衆浴場の確保のための特別措置に関する法律というのが改正されたようですけれども、目的として次のように記載されているんです。この点をもう一度お聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"経営の困難から防止するですけれども、私どもとしては、先ほどから出ています経営相談、そういった相談員を直接派遣する、そういった事業も行ってありますので、経営が困難であるということで廃業する前にこちらのほうに相談していただければ。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"前回も申し上げていますけれども、区が直接やっぱり公衆浴場の経営に乗り出して、区内全域で適正配置をしていく、コミュニティーを守っていく、それから地域経済を守る、こういう形で福祉の向上を図るということを再度求めまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"この中にみどりと水辺の実態調査ということで、もうこれは終了しているとは思うんですが、この結果がどういう結果が出たのか、調査をしているわけですから、品川区にとってプラスの結果が出たのか、もっと頑張らなければいけない結果が出たか、あと、その調査に品川区の水とみどりの課の職員のだれかが一緒に同行して立ち会いながらやったかどうかというのをお聞かせください。","respondent":"藤田水とみどりの課長","answer":"緑化推進費８,４００万円の中に占める国費あるいは都費の割合ですが、この緑化推進費の中には、地域住宅交付金、国の交付金として１２６万円余の金額が入ってあります。それを率に直しますと、全体の１.５％ということになります。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問","question":"その実態調査、５年に一度ということなんですけれども、委託ということで、委託の事業者がどうこうではなく、やはり品川区に思い入れのある職員が、やっぱりそれは同行したほうが、逆に現場を実体験できるという部分も含めると、今後必要ではないかなと、手が回らないかもしれないんですが、やはり品川区の職員であれば品川区に思い入れもあると思いますので、その視点で地域とか。","respondent":"藤田水とみどりの課長","answer":"そういう面もありますが、委員ご指摘のとおり、実態調査に同行するというのも意味はあることだというふうに思いますので、次回やる際には、そういった面も検討の１つに加えていきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"稲川委員","kind":"意見","question":"次回は５年後だと思いますが、ぜひ忘れずにお願いいたします。」だれに聞いてもそう答えが返ってくると思うんですが、実際、品川区におけるみどりの必要性、目標値というのは、多分、先ほどご答弁にもございましたように、みどり率とか、緑被率、特に緑被率を上げるということが品川にみどりが増えたという事実的なものだと思うんですが、そのみどりの必要性というのはどうお考えであるか。","respondent":"藤田水とみどりの課長","answer":"品川区におけるみどりの必要性ですが、みどりを広くとらえると、地球規模等で考えると、ＣＯ２の吸収、あるいは温暖化の防止、また生態系の保全というような意味での非常に大きな意味があるというように考えてありますが、これを品川区に置きかえると。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問・要望","question":"今ご答弁にありましたように、私も１年前に環境対策特別委員会でそういうお話を聞きました。そのとき委員からも、地球規模の話を品川区に持ってきていいのかと、地球規模ではＣＯ２という話になるかもしれませんが、そこはしっかり明確にしていただいて、みどりを増やすためにご努力をいただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"そうしたところ、まだまだ緑化の必要なところがある、特に密集地域の中には接道部の緑化の割合が少ないということもはっきりわかってきましたので、そういったところに対して、また策を立てるというようなことも、今後、行動計画をつくる計画もありますので。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"みどりを増やすのに一番やりやすい、経費はかかるかもしれないですけれども、私は品川区の施設、ここに公共施設緑化事業とありますけれども、これは教育費になってしまうかもしれないですが、例えば学校とか、すべての品川区の公共施設において緑化、芝生化も含めて、壁面緑化、屋上緑化をやれば、何かすぐ達成できてしまうような気がするんですけれども、それはイエスかノーかでいいので、どうでしょうか。","respondent":"藤田水とみどりの課長","answer":"現在みどりが増えているのは、やはり民間の部分が品川区内では非常に多いのが実態です。そういった面では、官民あわせて協働で進めていかなければ実行できないというふうに考えてあります。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ民間のお手本になるように品川区も随時やっていただきたいと思います。１５８ページの産業経済費です。簡単にお答えいただければと思います。観光アクションプランの推進事業なんですが、平成２０年度の決算では８,５００万円余の額で、今回は大体半分ぐらいになっているんですが、この減ったことによって事業に対する影響というのがあるのかどうなのか、お願いします。","respondent":"諸岡商業・観光課長","answer":"この整備が終わったということで、平成２１年度にはこの経費を除いておりますので、それ以外の部分については、ほぼ前年と同額です。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"まだちょっと私、拝見していないんですが、こういった展を開けるということは、やっぱり荏原地域に非常に歴史がある、その歴史をもっとひもといていけば、更なる掘り起こし、文化とか歴史の掘り起こしができると思うんですけれども、これは観光全体について今お伺いしていますが、その辺、今後どのように取り組んでいくかお聞かせください。","respondent":"諸岡商業・観光課長","answer":"品川区の歴史に光を当ててというお話です。今回、歴史館のほうで中原街道展が実施されました。それに先立ちまして、秋の９月に、ＥＢＡＲＡオータムフェアということで、観光協会と区が連携いたしまして観光イベントを実施いたしました。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問・要望","question":"観光協会とか、地域の商店街もそうなんですが、点から線、線から面というとらえ方で地域のまち興しを行っていきたいという話もありますので、ぜひ取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"３点伺っていきます。１５９ページの経営相談のところは、まず、平成２０年にこの認定等の作業が入って劇的に相談件数が増えたのは、いま一度確認なんですが、平成１９年度と比べて何で増えたのか、ちょっと簡単に示していただきたいのと、創業支援、いわゆる開業から創業の部分の相談が増えてきています。今年で終わりですか。あの中で４０店選ばれて終わりですか、次、続けますか、お聞かせください。","respondent":"福島ものづくり・経営支援課長、諸岡商業・観光課長、山岡健康課長","answer":"私からは、経営相談につきまして回答します。本年度で２００店舗そろいますので、今後におきましては、この２００店を活かした取り組み、この２００店に核になっていただいて商店街の発展。肝炎ウイルス検査についてのお尋ねです。区で実施しているものは、検査のほうを実施しているものです。","id":"exchange-024"},{"speaker":"渡部委員","kind":"提案","question":"どんどんやはり活気づくのがいいのかなと。全部が全部行ったことがあるお店ではないのでわかりませんが、何かの機会のときに、やはりまた商業を盛り上げていける企画を、私たちもいろいろ考えていきたい、ご提案させていただきたいと思いますので、区のほうも積極的に進めていただきたいと思います。本当に５年生きられるか、いや、そのまま３０年生きるかわからないというような感じの病気とも聞きました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"私は、成果報告書１５９ページの中小企業対策費の中小企業支援費についてお伺いいたします。そういった中で、来年度には、東京都信用保証協会の１００％保証が１００％でなくなるというお話もありますが、そういったときに銀行もなかなか貸しづらくなるわけですけれども、今後も続くと思われる景気低迷の中で、品川区としては、この制度の運用についてどのようにお考えになっているのかお聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"区が行ってきました緊急融資あっせん制度のお尋ねですが、こちらの事業につきましては、平成２１年１月２０日から実施してまいりまして、３年間無利子ということで、かなり好評な事業です。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"その一方で、区内の中小企業の方からは、中小企業の融資あっせん制度よりも、そもそも仕事がないというお話も聞くわけですけれども、品川区では、住宅のリフォームなどで区内企業を利用した場合の優遇策等を行っていますけれども、大手の企業が品川に営業所をつくって仕事をとってしまうというようなお話も聞くわけです。そのほかの話もある中で、そういった中での区としての対策があれば教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"相談の中でも建設業にかかわる方からは本当に切実な厳しいという声を聞いてあります。そういった意味では、一番厳しいであろう建設業について支援していくことは重要なことだと考えていますので、区としては支援を続けていきたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"小規模事業者経営改善資金、いわゆるマル経融資利用者への利子補助制度についてお伺いさせていただきたいと思います。本人の負担利子の３０％を補助するというこの制度ですけれども、品川自民党の先輩方の政策要望により実現したと聞いていますけれども、現時点でのこの制度の利用企業者の数、また利用者の状況、声、来年度以降の制度の運用についてお聞かせいただければと思います。","respondent":"福島ものづくり・経営支援課長","answer":"実際は今年の４月から今までに７１件の融資が行われましたので、その融資が払われる来年になりましたら、その支払った額の３０％を区が補助していくという形になります。来年につきましても引き続き続けたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"先ほどほかの委員からもご質問がありましたけれども、経営相談事業費についてお伺いします。先ほど、現時点でどれだけの利用があるのかお答えしていただいたようなので、お教えいただければと思います。","respondent":"福島ものづくり・経営支援課長","answer":"残りが先ほど出ていました創業支援というような形です。２回、３回という形で相談された場合ですけれども、ファイルをつくりまして、確実に相談がつながるようにという形で行っているものです。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと前後してしまうんですけれども、中小企業融資あっせん制度の認定を受けても、先ほど、信用保証協会の保証を受けられず、銀行から借りられない場合もあると聞くんですけれども、そういった場合の対策、区としての何か対策があれば教えていただければと思います。","respondent":"福島ものづくり・経営支援課長","answer":"これ、金額ベースで見ますと、融資あっせんを申し込んだ金額の８０％が実行されているということがありますので、そういった意味では１割の方に対しては経営相談等を十分に行いまして、経営が続くように支援していくように努めているものです。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、先ほどもお話しありましたけれども、区内には３４カ所のおふろ屋さんがあるということで、４７件あったというのはどういうことなのかなというのを教えていただきたい。それからもう１つは、その下に健康増進型改築等支援補助ということでありますが、この健康増進型というのは、どういうものをおふろ屋さんで使っているというか、やっているのか、その辺も教えていただきたいと思います。","respondent":"山岡健康課長","answer":"これは衛生管理上必要な設備、釜とか、温水器、給排水器、その他公衆浴場の事業に必要なものの設備の改修をする際の経費について補助をしているものでございまして、これは件数をそれぞれの改修工事について１件と考えておりますので。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問","question":"それと今お話の健康増進型のお話で、場づくりというか、そういう施設をつくるお話を聞きましたが、今年は５００万円、また前回は１,０００万円ということでありますが、もうちょっとこれを具体的に、これだけお金がかかっていますので、どういうものを設置というか、使っているのか、教えていただけますか。","respondent":"山岡健康課長","answer":"施設自体をかなりの部分改修しまして、ホールといえるくらいのスペースをつくったり、これはもともと交付対象がそういうふうな健康づくり、健康増進事業ができるような広さ、３０平方メートル以上のそういうふうなスペースをつくる場合に対象になるものです。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"先ほどいろいろご質問の中に、おふろ屋さんに対していろいろな融資のあっせんですとか、また経営相談にも乗っているというお話がありました。それから、やはり区の施設がありますが、例えばシルバーセンターなんかはおふろにお昼から入れるんですが、それを例えば夕方から入れるとか、何かもう少し頭を柔軟にしてオープンにできる発想というか、何かございませんでしょうか。","respondent":"山岡健康課長","answer":"何らかいい知恵があれば、もちろん参考にしたいと思いますけれども、現状ではなかなか難しいかなというふうに思っております。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしてもぜひ考えていただきたいなと思います。時間がないので次の１４８ページの各種がん検診のところに行かせていただきたいと思います。改めまして、今回、最終的に受診率、大分上がったかなと思いますが、確認をさせていただきたいと同時に、内容といいますか、乳がん、また子宮頸がんの受診内容といいますか、そちらをちょっと教えていただきたいと思います。","respondent":"山岡健康課長","answer":"子宮がん、乳がん、国の無料クーポン事業も加えて、従来からやっている区の偶数年齢の方の受診、あわせて昨年度実施したところです。子宮がん検診につきましては、受診率が昨年度は２４％、平成２０年度が１７.９％でしたので、初めて２０％を超えて２４％まで行ったです。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問","question":"先ほど聞いたのは、受診内容をお聞きしたんですが、ちょっとその辺も教えていただけますか。","respondent":"山岡健康課長","answer":"失礼しました。子宮頸がん検診ということで実施しているものにつきましては、細胞診で実施しているものです。それから、乳がん検診につきましては、国の指針にあるマンモグラフィー検診、それに品川区では超音波検査を加えて実施しているものです。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"子宮頸がん検診なんですけれども、できれば検査項目にＨＰＶの検査をぜひ入れていただきたい、これは要望ですけれども、お願いしたいと思います。その詳細をあれなんですけれども、１つ質問は、中学校１年生からということなんですが、女性に対して、生活保護とか、母子家庭の家庭に対しての、任意ではありますが、その辺は区としてはどういうふうにお考えになっているか教えていただけますでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"任意予防接種につきましては、一応一律に補助というふうに現在考えております。基本的には一部補助の考え方で進めさせていただきたいというように考えています。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"１５１ページ、健康づくり支援事業費、１５３ページ、蝶の道プロジェクト、涼しさ回復プロジェクト、１６０ページ、しながわの一番店発見プロジェクト、ユビキタス商店街プロジェクト、ものづくり創造センター維持管理費についてお伺いしますが、まず、今、プロジェクト、プロジェクトとプロジェクトを４つ出したんですけれども、この４つのプロジェクトの内容はわかっておりますが、まずその前に。","respondent":"金子企画財政課長、山岡健康課長、諸岡商業・観光課長","answer":"私どもとしましては、特定のテーマで、特に新しく、また特徴的な事業を実施する際に、こういった取り組みを強調し。３２件、要は団体、その３２の中には団体も家族も入っておりますので、３２名の個々の方ということではなくて、もっと多くの方になると思いますけれども。その２００店舗が地域の核店舗として他の店舗をリードしていただくような存在ということで。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"名は体をあらわすという言葉があるように、これ、プロジェクトとつけるのは、何かもうこうやって事業をやっているんですからおかしいんじゃないかなという思いがあるので、その辺をもう一度答弁していただきたいのと、それと、この言葉ではなくて、そのプロジェクトという流れなんですけれども、ものづくり創造センターとかが。","respondent":"金子企画財政課長、福島ものづくり・経営支援課長、山岡健康課長","answer":"「プロジェクト」という呼称についての再度のお尋ねですけれども、先ほど私どもの基本的な考え方をご説明申し上げましたが。こちらの施設につきましては、大井４丁目にある施設でございまして、ものづくりにかかわる個人あるいは企業あるいはＮＰＯ等が、技術開発や産学連携。そういうことも含めて、今後この事業のあり方を考えてまいりたいと思います。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"私からは、１４７ページの予防接種および１４８ページのがん検診、それから１５９ページ、武蔵小山の創業支援施設について伺いたいと思います。それから、乳がん検診、先ほども出ました。それから、武蔵小山の創業支援施設なんですけれども、これはチャレンジショップを開業して数カ月たちましたけれども、経営状態といいますか、どのような状態かなということを伺いたいと思います。","respondent":"山岡健康課長、福島ものづくり・経営支援課長","answer":"原則はマンモグラフィーだというふうな、そういうふうな仕切りも含めて検討してまいりたいと思います。今、予備的な検討を始めたいというふうに考えているところです。何しろまだ始まったばかりでもありますので、これから経営の支援強化に努めていきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひそれはきちんと検討して今後に生かしていただきたいと考えています。しかし、今回のこのチャレンジショップについては、そういう初期の大変さだけなのだろうかという疑問が少々私にはあります。この募集に当たって、改めてどのような形で周知して、募集期間はどのようだったか、募集件数等、それから事業計画についてはどの程度検討を加えたかということをちょっとおさらいさせてください。","respondent":"福島ものづくり・経営支援課長","answer":"このチャレンジショップ自体には２７件の応募がございました。当然、事業計画書ですとか、さまざまな必要書類を出していただきまして、また面接等も行いながら、この事業がうまくいくかどうか、それを十分検討した上で３店舗を決めたものです。","id":"exchange-040"},{"speaker":"阿部委員","kind":"質問","question":"今のご答弁の中で、２７件のうち、そもそも支援が必要ないもの、それから絶対だめそうなもの、それは除いて検討された。そうすると、実質の競争率はどのくらいだったんですか。検討の俎上に上ったのは何件ぐらいだったのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"実質もやはり２７件、それは十分競争といいますか、検討しましたので、ただ、それをやりながらも、これは無理だろうという判断は、それは最終的にはしましたけれども、競争率としては２７件すべてです。","id":"exchange-041"},{"speaker":"阿部委員","kind":"質問","question":"区の審査に通った段階で開業予定の方々が全くノウハウがないからどうやって何をしていいか最初から教えてくれというようなことを結構いろいろな方に声をかけていたということで、大変皆さん心配されていて、あけてみたら、まさに心配どおりになってしまったというようなことも漏れ聞いております。その辺の状況というのをどのようにお考えなのか、私は大変心配です。お考えを教えてください。","respondent":"宮地地域振興事業部長","answer":"多少の危険はありますが、積極的にやっていってもらいたいというのがこの創業支援センターの取り組みですので、そのあたりはご理解いただきたいなというふうに思います。","id":"exchange-042"},{"speaker":"阿部委員","kind":"意見","question":"言いたいことは多々ありますが、今後の推移も見ていきたいと思います。その上で、また区のお考えを聞きたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民サービスコーナーのところが、以前はプレハブであってわかったんだけれども、新しくなったらどこにあるかわからないと言われて、私、質問を受けたりしたんですね。私はぜひ区民の皆さんへの啓発とか教育面で、ぜひ表示をつくっていただいて、どのくらいＣＯ２削減につながっているのかというアピールをぜひして、もっと活用していただきたいなという思いで質問をさせていただきました。","respondent":"福島ものづくり・経営支援課長","answer":"確かにあそこの施設自体の周知といいますか、知られていない部分があります。それにつきましては、今も検討してございまして、公共サインもそうですけれども、例えば駅前でチラシを配るですとか、そういったことはどうかというようなことを事業者と検討している段階です。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。ちょっと駅からも離れているし、周りが広場ということでは空間があるので、遠目から見てもわかるような、４階にあるということをきっちりと表示をしていただきたいのは、よろしくお願いいたします。ご答弁いただきたいのと、あと、駅からのサインも足りないですね。創業支援の新しい施設ができたんだというのをぜひアピールをしていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"太陽光パネルにつきましては、どういう形で表示するのか、ここが太陽光パネルですというのがいいかどうか検討したいと思います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"産業経済費全般にかかわって若者の就労支援政策について伺います。かつて品川区もこの産業経済部門でキャリア支援塾やヤングキャリアナビゲーションなどの若者就労支援を行っていました。これはなぜでしょうか。１つもないというのは、品川区のこの分野に関する位置づけがあまり高くないということのあらわれと見てよいのでしょうか。お伺いします。","respondent":"福島ものづくり・経営支援課長","answer":"若者の就労支援ですが、基本的には国の施策というふうに考えてありますので、ハローワーク等で行っているというふうに認識しています。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少しこの問題の重要性を区としてしっかり認識していただきたいと私は思います。今月１１月ですけれども、実は政府が定めております子ども・若者育成支援強調月間となっております。月間の実施主体の中には市区町村も入っておりますけれども、品川区では何か活動を行う予定はあるのでしょうか。この強調月間です。あわせまして、品川区は若者就労支援施策の必要性をどう考えていらっしゃるのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"こちら、先ほど出ました子ども・若者育成支援推進法の絡みにつきましては、今後の検討課題というふうに私どもは思ってあります。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"区内の実態をちょっと紹介したいんですが、私は共産党と民青同盟で街頭で雇用実態調査を行ったんですけれども、１０９人から声を伺いました。２９歳、女性、派遣の方。２年目で園の中では最長。２週間で仕事をやめた人もいる。過去にキャリア支援塾やヤングキャリアナビゲーションなどの事業、就労支援取り組みましたけれども、これらの事業はどう総括され、また今後にどう生かす考えがあるのか伺います。","respondent":"福島ものづくり・経営支援課長","answer":"そういった過去の経過も含めまして、また、こういったキャリア支援塾につきましては、ハローワークあるいは職業訓練校等で行っていますので、そういうところで実施していくということがございましたので、区としては現在、キャリア支援塾は行っていかないという状況です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"提案","question":"品川区としても、足立区で実績を上げているような若者の就労相談窓口を設置すべきだと私は思うんですけれども、その区内の、先ほどの答弁もなかったような気がするんですが、若者の雇用、就労困難な実態をどうつかんでいるのかということとあわせまして、この提案に対してのご意見も伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"区にはさまざまな事情がありますので、また企業の数ですとか、あるいは大企業の数ですとか、そういった人材がどこにあるのか、あるいは区全体としてどういう就労支援をしていくのか、そういったことを総合的に検討していきたいというふうには考えてあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"だからこそ私も民青同盟の方と行ったように、区として、一体区内で働いている若者がどういう状況に置かれているのかというのをやっぱりしっかりとまずつかむというか、そういうことがまず出発点になると思うんですけれども、その実態についてお伺いしますと、厳しい状況だということは伺うんですが、それ以上の答弁がないといいますか、では、品川区の若者が一体どういう困難に置かれているのかという。","respondent":"福島ものづくり・経営支援課長","answer":"若者の状況ですが、現に元気に働いている若者もいっぱいいますし、また、創業支援の中では若い人が創業して一生懸命働いていると、そういった企業も多くあります。そういった若者たちの支援も同時に行っていきたいというふうには考えてあります。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"環境情報活動センターですが、一応１１月１日から第３庁舎のほうに移転ということで、委員会でも報告があったというお話ですけれども、改めて移転になった理由というんですか、事情と、あと、平成１７年１０月に開設してちょうど５年を迎えたという中で、この間の環境情報活動センターの区の当初期待した役割と、またこの５年間の歩みの中での評価をお聞きしたいと思います。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"これも好評を得ているところです。環境学習講座に関しましても、かなり内容を充実しまして、講座数も増やしております。そういった意味では、少しずつですけれども、活用が高まっているというふうに認識しております。私から、創業支援のゼロから創業した方と、既に創業していた人との内訳ですけれども、ゼロから行った創業前の方が、全部で１３４人の方に平成２１年度は融資あっせんをしました。そのうち３９人の方が創業以前です。","id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"創業支援のほうにつきましては、３９人がゼロからということで今教えていただきましたけれども、これも非常に難しい課題だと思うんですけれども、私もたまたま１件、お知り合いの方からご相談があって調べて、今まであんまり知らなかったんですけれども、これから創業を始める方というのは、お金を借りるときに。","respondent":"阿部経理課長、工藤環境課長、福島ものづくり・経営支援課長","answer":"第２庁舎の環境情報センターの跡の件ですけれども、庁舎という限られたスペースのものですので。もう１つは、やはり今後、環境情報活動センターに求められているものは、やはり情報センターといわれているように。やはりある程度は自分で資金をためて、それを元手に行っていく、そういうことも大切だというふうに考えてあります。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"融資のほうは、信用保証協会のほうのそういうあれがということで理解はいたしますけれども、そうすると、相談に来た方でなかなか自己資金がなくてすぐ結びつかない方について、ぜひきめ細かく激励していただきながら、創業にいずれ結びつくような形でバックアップをしていただきたいというのが要望です。１点だけ教えてください。","respondent":"阿部経理課長","answer":"検討の状況はいつまでかですけれども、遅くとも来年の４月には、どういう利用になるかは検討中ですけれども、来年４月には新しいものができるような、そういうスケジュールで考えていきたいというように思っています。","id":"exchange-053"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、１４８ページの保健衛生費の環境衛生費の中の狂犬病予防および動物の愛護について、それから１４９ページの保健指導費の中の母子健康診査費と、母子保健指導事業費を中心にお伺いいたします。それから、産業経済費の中では、１５９ページの中小企業対策費の中の商店街活性化事業の助成、支援とか資金のあり方と、あと、小規模商店街活力づくり支援事業についてお伺いいたします。","respondent":"諸岡商業・観光課長","answer":"したがって事後ということになります。比率といたしましては、正確には出してございませんけれども、やはりイベントをかなり数が多いということがございまして、７割以上がイベント事業というふうに思っております。","id":"exchange-054"},{"speaker":"井桁委員","kind":"質問","question":"そのハード面のことは事前でしていただけるというのは非常にそのとおりだと思うんですけれども、やはりソフト面でのイベント事業というのは、後からお金をいただくというのは、やはり商店街の中でもかなり意欲があって、さあやろうと思ったときになかなか手が出ない商店街があったりとか、あと、資金繰りにもかなり困っているというようなことも聞きますので、ぜひ基金を創設していただいて。","respondent":"諸岡商業・観光課長","answer":"イベント事業に関する助成の件ですが、先ほど申し上げましたように、ハード整備と異なりまして、当初の予定額と最終的な金額との乖離が大きい。","id":"exchange-055"},{"speaker":"井桁委員","kind":"質問・要望","question":"イベントの件に関しましては、活性化をしていくんだという意気込みとともに、やはり区と一緒に頑張っていくんだというような考え方で、ぜひ基金を設立していただきたいなと、これは要望します。そんな中で、やはり私は自助、共助、公助の中で、これが順番だと思っておるんですが、品川区のほうでは、そのような取り組みであったりとか、積極的なお考えがあるかどうかまずお伺いいたします。","respondent":"山岡健康課長","answer":"母子保健事業について、厚めにいろいろできれば、それはそれに越したことはないと思いますけれども、これは出産費助成につきましては、国全体の制度がありますので、それに何か区のほうでできるかできないか、ちょっと研究課題とさせていただきたいと思います。","id":"exchange-056"},{"speaker":"井桁委員","kind":"質問・要望","question":"やはり子ども、特に１歳未満の子どもを抱えているお母さん方は、健診に行こうかというような、かなり意欲が高い方でないと忙しさにかまけてといいましょうか、なかなか自分の体まで気をつかってあげることができないのではないのかなと、それがその数字なのかなと思っているんですけれども、受診率のこのパーセンテージをどのようなとらえ方をされているのかというのをちょっとお伺いいたします。","respondent":"山岡健康課長","answer":"ただ、これはせっかくの健診の機会ですので、これからもう少し受診率が高くなるように何らかの工夫をしていきたいというふうには考えております。","id":"exchange-057"},{"speaker":"井桁委員","kind":"質問","question":"次の項目のすくすく赤ちゃん訪問事業のことについてお伺いいたします。これはかなりきめ細かく丁寧にやっていただいている事業だと考えています。その中で、現在、保健師と訪問指導員が連携、そしてまた児童センターと保健所が連携をしてこの事業を行っていると聞いておるんですが、この訪問指導員の研修でしょうか、指導の仕方というのはどのようにされているのでしょうか。お願いいたします。","respondent":"矢野品川区保健所品川保健センター所長","answer":"新生児の訪問指導員というのは、大部分の方が助産師の資格を持っている方です。その他、保健師の資格を持っている方もいらっしゃいますが、保健センターの保健師から毎年必要な情報等も伝えまして指導しております。","id":"exchange-058"},{"speaker":"井桁委員","kind":"質問・要望","question":"やはり助産師というのは、妊娠中からそして産後までかなり精神的な面でもケアをしていただいていると思っていますので、ぜひスキルアップであったりとか、保健師の全体的なレベルアップを図っていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"高橋委員","kind":"質問","question":"１４８ページ、こころの健康づくり事業の自殺予防講演会、自殺に関連してお尋ねします。区内の自殺者について一般質問のほうでもございましたが、品川区内の実態を数字的な面と要因の面でお教えください。全体的な傾向との比較と、そうすると、他区、２３区都市部での他区との比較、その比較をした分析をお教えください。よろしくお願いします。","respondent":"福島品川区保健所荏原保健センター所長","answer":"全国と比較しますと、平成９年から平成１０年に急に自殺の数が増え、３万人台、それまで２万４,０００人台が３万人台に増えたわけですけれども、品川区においては、その平成９年から平成１０年へというのは、ちなみに６６名から７２名ということで。","id":"exchange-060"},{"speaker":"高橋委員","kind":"質問","question":"要因について、品川での自殺の原因というのでしょうか、それを１位、２位を言っていただけるとありがたいんですが。","respondent":"福島品川区保健所荏原保健センター所長","answer":"一番多いのは、やっぱり健康問題ということですね。それからあとは、社会問題という具合にまとめてありますけれども、やっぱりこれは経済的な問題とか、そういうものが第２位に当たるかと思います。","id":"exchange-061"},{"speaker":"高橋委員","kind":"質問","question":"自殺の大きな要因の中で、先ほど健康問題とありましたが、精神疾患が多いということなんですが、全人口に占める推定の精神疾患の患者の割合は２.５％、生活保護を受けている方で精神疾患を持っている方は１６.４％ということで、生活保護の方がいろいろな要素を抱えているわけなんですが、この点において、ちょっと情報がないのかもしれませんが。","respondent":"福島品川区保健所荏原保健センター所長","answer":"監察医務院が自殺をなさった人の調査をしたデータからいいますと、総数が去年は８１名ということで、この中で家族の被扶養というのが１９名、それから給与所得者が２９名、年金預貯金の生活者が１６名、自営業が７名、それから生活保護を受けておられる方が４名。","id":"exchange-062"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうすると、やはり生活保護を受けている方と、あるいは精神疾患の予防ということで、こちらの今の衛生関係の課と、それから民生のほうとの連携が必要になると思うんですが、品川区では、区からの補助もあると思うんですが、この生活保護の方に関して、精神的なフォローも含めて、自殺も含めて、どのような施策を、平成２１年度からやられているのかなとは思うんですが。","respondent":"平澤生活福祉課長","answer":"平成２１年度というわけではないんですけれども、私どものほうで、専門の相談員を雇っております。非常勤で１名おるところですが、そういった者が心に病をお持ちの方を中心に生活指導ということで回っているということはやってあります。","id":"exchange-063"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、それは厚労省のセーフティーネット支援対策事業費の補助金ということで、款が飛んでしまうんですが、民生費の中の相談のところの予算になるのでしょうか。","respondent":"平澤生活福祉課長","answer":"資格につきましても、社会福祉の専門家ということで雇っております。連携ですが、この相談員に限らず、保健所、保健センターと連携をとりまして、そういった方に対するフォローをやっているです。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"そこで、生活者ネットワークが２３区の自治体で保健師の状況を調べましたところ、単純に人口割をしたところ、練馬区が一番多い人数で、その中では品川区は２番目で、保健師１人当たりに９,１００人という、そういった割合になるんですけれども、こういう考え方でいうと、品川区はワースト１０に入るのか、ベスト１０に入るのか、ちょっとその辺の位置をお伺いしたいと思います。","respondent":"矢野品川区保健所品川保健センター所長","answer":"保健師の数ですと、品川区の保健所だけではなくて、高齢者福祉課や国保医療年金課などにも配置されているですが、平成２０年度の東京都の特別区の保健師数というものがございまして、その中でいいますと。","id":"exchange-065"},{"speaker":"井上委員","kind":"確認","question":"そうすると、前回予算特別委員会で答弁いただいたように、品川区は２８人の保健師が健康センターにいるというふうに思われます。もう１点は、乳幼児相談とか、精神相談を同じ保健師が行うのかということの確認。それから、現在、品川区では、地域担当制を３つの保健センターでされていると思うんですけれども、１人の保健師が対応している人数がどのぐらいになるのか伺います。","respondent":"矢野品川区保健所品川保健センター所長","answer":"１人の対応人数は、それぞれバリエーションがあって、なかなか対象人口はこういうことですが、１人ずつの対応人数というのはちょっと出すのが難しいです。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、保健師のそういった専門職の確保と、事業部、教育委員会との連携が不可欠であるとふうに思いますけれども、職員の確保と連携の視点で見解を伺います。","respondent":"矢野品川区保健所品川保健センター所長","answer":"それは保健師の係内での研修や教育委員会等との連携等もそういう研修の中からきちんと連携ができるようにしていきたいと思っています。教育委員会との連携については、学校保健委員会というのがございまして、そこの中で検討しています。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望です。次、環境衛生費の猫の不妊・去勢手術なんですけれども、決算額で６０万円ほどの不用額が生じているんですが、この原因を伺います。","respondent":"荒井品川区保健所生活衛生課長","answer":"猫の不妊・去勢手術費についての不用額のお話です。実際には、予定していた主に飼い猫に対する不妊・去勢手術の助成額が残余したためです。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問","question":"予算の中で、飼い猫のほうが申請がなかったというところでは、飼い主のいない猫とか、そういったところの予算内での流用ができないのかということが１つと、あと飼い主のいないほうの猫の不妊・去勢手術の事業の目的を改めてお伺いいたします。","respondent":"荒井品川区保健所生活衛生課長","answer":"ただし、飼い猫の実施期間が３月末まででしたので、年度内にすべてのものを使い切るということができませんでした。それが１つの原因だったと思います。","id":"exchange-069"},{"speaker":"井上委員","kind":"質問","question":"行政が目的達成のためにいろいろな改善をしてくださっているということに大変評価の声が大きいということをまずはお伝えしたいと思います。その中で、飼い主のいない猫のそういった手術助成で、動物愛護の精神と環境問題に対してさまざまな解決が進んでいるというふうな認識を持っているんですけれども、実際に品川区はどのように、苦情についてもどういうふうな感想を持っていらっしゃるんでしょうか。","respondent":"荒井品川区保健所生活衛生課長","answer":"目的のご指摘をありがとうあります。確かに近隣への悪臭等の迷惑を防止するということが１つの目的となっています。","id":"exchange-070"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう苦情はまだまだ減っていないということで、品川区としては猫ボランティアの個人や団体と町会との取り組みということで２本立てで行っているということを、これはまた品川区の特徴としてぜひ推進していただきたいと思うんですけれども、１つ苦情対策というようなところで、他の自治体の２００９年度の飼い主のいない猫のそういった実施状況を比較する資料があるんですけれども、その中で。","respondent":"荒井品川区保健所生活衛生課長","answer":"予算配分のことについてですが、先ほど委員からも最初にご指摘があったように、現在の予算規模の中で、飼い猫の予算が余った場合には飼い主のいない猫へというような形で流用する形で、しばらくの間、見守っていきたいと考えております。","id":"exchange-071"},{"speaker":"井上委員","kind":"質問","question":"環境対策の環境指導相談についてお伺いいたします。低周波の健康被害についてなんですけれども、相談としてどういったものが品川区に寄せられているのかをお伺いいたします。","respondent":"工藤環境課長","answer":"低周波の音が原因でないかという相談の件ですけれども、数年に１度、そういったお問い合わせがあります。具体的な事例としましては、いわゆる工場等に設置している室外機に関して何か気になると、そういった苦情を受けているところです。","id":"exchange-072"},{"speaker":"井上委員","kind":"質問・要望","question":"今年、品川区では新規事業として省エネ機器の設置の助成を始めたんですけれども、ここで商品名でいうとエコキュートになるかと思うんですけれども、夜通し稼働するエコキュートの発する低周波音などで睡眠不足や食欲の不振などの体調不良を訴える、そういった全国での苦情が相次いだことで、事業者でもガイドラインを設置するというふうな動きがあるんですけれども。","respondent":"工藤環境課長","answer":"私どもの対策ですけれども、エコキュートに限らず、省エネルギー機器の導入助成の方には、すべて受け付けの際に室外機の取りつけ等のそのような説明はしております。","id":"exchange-073"},{"speaker":"井上委員","kind":"質問・要望","question":"来年もきっとこの助成事業は継続されるかと考えていますので、これは機器自体に問題があるわけではなくて、設置する場所、事業者が安全なところをきちんと設置をすれば何ら問題がないということが明らかですので、今後、区民の健康被害を引き起こすリスクを未然に防止するために、ぜひメーカーから安全な設置場所の確約をとるなどの対策をとっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"山路委員","kind":"質問","question":"２点ほどお伺いします。最初の水についてですが、水といいましても、私たちが給水を受けるのは水道、専用水道、簡易専用水道、あと小規模受水槽水道、あと井戸水がありますが、この決算書に計上してあります１３件、約６４万円と掲載してありますが、どういう検査、指導、あるいは相談、アドバイス、こういうものを展開されているのかをお伺いいたします。","respondent":"荒井品川区保健所生活衛生課長","answer":"貯水槽の水道の水質検査を希望された方についての検査です。実際に行いましたのは井戸水の検査、専用井戸というのが区内にも何件かありまして、その中でご希望された１３件について検査をしたところです。これは検査に必要な金額６４万円です。","id":"exchange-075"},{"speaker":"山路委員","kind":"質問・要望","question":"それで、ポンプが故障してとまってしまった、修理はだれがするかということで、みんなで使っているのに持ち主ができないという状況も相談を受けたことがあるんですが、何らかの形で、そんな高い値段ではないと思うんですが、修理するなり、整備するなり、そういう助成体制も今後考えていただけないかということなんですが、この２点についてお伺いいたします。","respondent":"荒井品川区保健所生活衛生課長","answer":"それで、どうしても水道工事ができないというご事情の方もいらっしゃるようなので、その場合につきましては必ず沸かしてから飲むようにといったご指導をさせていただいているところです。","id":"exchange-076"},{"speaker":"山路委員","kind":"質問・要望","question":"飲む対象ではないということはもうわかっているんですけれども、それに対して、今後、考えていただきたいことを要望しておきます。次に、ものづくり活性化事業費、新製品・新技術、あるいは海外進出、あるいは品川技術ブランド ＰＲ、環境ビジネス支援と拡充してこられましたけれども、水に関する新技術というものが何かございましたら、教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"水と直接関係ないかもしれませんけれども、水上飛行機の開発ですとか、そういうことを、これは国の補助金ですけれども、申請している企業がございました。","id":"exchange-077"},{"speaker":"山路委員","kind":"質問・要望","question":"なぜ水にこだわって、水のことばかり聞くかといいますと、水をよくしていく技術、水に関する新製品の開発、世界一の技術を誇っていると日本は言われているのですが、それで、日本での水はおいしいんですけれども、特に東南アジアの水というのは非常にまずいということで、今、言われているわけですが、品川区でも１１月２３日、バンコクのビジネスサポートセンターが開設され。","respondent":"福島ものづくり・経営支援課長","answer":"浄水器の会社等も出展してきますので、品川区内の企業が持つ技術力をしっかりとＰＲしていきたいと考えています。","id":"exchange-078"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひこのものづくりが水に関しまして、ますます東南アジアで発展することを祈るものですが、実は水の都の大阪では、ベトナムのホーチミンで水事業を民間と協働して着手したんです。そういうものと品川のものづくりとの関連について、新たなこれから研究をしていただきたいと思いますけれども、どのようにお考えでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"確かに都の水道事業は世界に誇れるものだと聞いてありますので、品川区として連携、あるいは品川区の企業が何かお手伝いできないか、それにつきましては今後研究してみたいと考えています。","id":"exchange-079"},{"speaker":"渡辺委員","kind":"質問・要望","question":"もっともだなという思いの中で、新住民の方、新しく引っ越されてきた方、あるいは昔からの常連という視点から、ともにお買い物をするとき、あるいはイベントの情報というのには大変こだわりを持って、きめ細かく、チラシなんかも比較をしたり、情報をすごく求めていらっしゃると思います。当初の事業目的に沿う結果のように聞いていますが、この確認をさせていただきたいと思います。","respondent":"諸岡商業・観光課長","answer":"それで、効果といたしましては、そこで個店の魅力を知っていただいて、また商品の魅力を知っていただいて、実際の商店に買いに来てくれたというようなこともありますし、また、その際、いろいろな研修会等も行っておりまして、イトーヨーカドーという大型店の持つ。","id":"exchange-080"},{"speaker":"渡辺委員","kind":"質問","question":"どうしても私どもも、私自身もそんなに得意な分野ではないんですが、アナログ的なところは大事だと思います。大手の流通なんかはそこにとても力を入れている。そういう意味で、１つの例示をすれば、例えばネットでチラシを見る、チラシの印刷費分はその分、コストダウンはできるけれども、デザイン料など、そういった補助も将来的に必要なのかと思うので、この辺の現時点での見解を伺えればと思います。","respondent":"諸岡商業・観光課長","answer":"１点目ですけれども、インターネットとか、そういった最新の伝達技術を利用したＰＲですが、これはあくまで個店ということになりますとかなり難しい面がありますが、商店街の行うそういったＰＲ事業、インターネットを通じての事業につきましては支援をしておるところですし。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区はこの要望をどういうふうに受けとめているのか、私どもは２倍化の継続を引き続いて求めていきたいと思うんですけれども、どういうふうに考えているのか、あと、ほかの区では全額助成という区もありますけれども、改めてそういう方向に増額、全額助成の方向を考えていく必要があると思うんですけれどもどうか、まずこの点を伺いたいと思います。","respondent":"諸岡商業・観光課長","answer":"装飾灯の維持経費等につきましては、平成２１年度から緊急経済対策として補助金の額を倍額にしています。今後のことですけれども、緊急経済対策ですので、その時点での社会経済状況等を勘案いたしまして判断していくというものです。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問・要望","question":"商店街が具体的にこれと言っているものですので、私はぜひ要望にこたえていただきたいと思います。例えば今のＴＰＰ参加ということになると、関税、例外なく撤廃だということになると、私はさらにこれが低コストを求めて海外にものづくりの拠点が移ってしまうのではないかなというような心配もあるんですけれども、そこら辺の区の見方を教えていただきたいと思います。","respondent":"諸岡商業・観光課長、福島ものづくり・経営支援課長","answer":"区に寄せられた声、また商店街連合会にも寄せられる場合がありますけれども、そういう場合につきましては、確実に区または商店街連合会を通して商店街に伝え、その連携については密に図っているというつもりです。このように、海外に進出することによりまして現地法人を管理するために必要な国内の従業員の増加が必要だとか、そういうデータがありますので。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"提案","question":"先ほどの融資の点でも、実際に仕事がないところが、一番底辺のところ、旋盤、フライス一つでやっている、そういうところが、仕事がなければお金も借りようがないということなんですけれども、そういうところに対する区の考え方はどうなのかということが伺いたいということと、共産党はこの間、そういうところのいわゆる固定費、家賃や機械のリース代などの固定費の支援を求めてきているんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"その販路拡大の支援のためには、専門のコーディネーターも雇っておりますので、そういった方によります売り込みですとか、また合同での、大田区ですとか横浜、川崎を中心としました京浜クラスターによる合同商談会、そういったことも年に数度実施していますので。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"意見","question":"今、課長がいろいろ施策を説明されたんですけれども、それは一定力のあるところの対策なんです。改めてそこを聞きたいと思うんです。逆に、これは区内で生産してもらう、仕事を持ってきてもらうということをどうするのかということが私は今、大事だと思うんですが、そこの対策といいますか、考え方を聞きたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"今年から始めました品川パビリオン事業といいますか、専門展示会に対する出展、共同出展ですが、これにつきましても、なかなか大きな専門展示会に出展できない小さな企業が、区と一緒に出ることで販路拡大につながると考えていますので。","id":"exchange-085"},{"speaker":"宮崎委員","kind":"意見","question":"もう１つ、海外進出、海外進出といいますけれども、大事なことは、国内で、区内でどう仕事を持ってくるかというところだと私は思うんです。だけれども、今、区の施策の方向性をしっかり区内に仕事を持ってくるという方向に頭を切りかえないと、結局、国内、区内で仕事がなくなってしまうということになってしまうので、頭の切りかえをよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"堺委員","kind":"確認","question":"特にこの動きにつきましては、ご存じのとおり、政府でも早急な対策が必要であるというところから、今年度につきましては臨時特例交付金を財源に公費負担で行うということを既に決定し、なおかつ１０月１９日におきましては、この特命チームにおいて母子感染の防止に有効な妊婦に対する同ウイルスの抗体検査、これも来年度も公費負担で継続するということを決めたということで。","respondent":"山岡健康課長","answer":"お尋ねのいわゆる５者協、東京都、特別区、市、町村、それから東京都医師会、この５者で協議をして決めるという場があります。妊婦検診につきましては、東京都全域で一体的にどこの医療機関で受診しても可能だというふうな形で実施しているものです。","id":"exchange-087"},{"speaker":"堺委員","kind":"質問・要望","question":"わかりました。非常に大事な母子感染の予防ですから、早期実施、早期に取り組むということが予防においては大事なことなんです。なおかつ今年度もしましたし、来年度ももうそうするということがはっきりしているわけですから、にもかかわらず動きがない。否定しませんが、先ほどから申し上げておりますように、大事な母親と子どもの命を守るということですから、いつまでも検討してではないんです。","respondent":"山岡健康課長","answer":"５者協で何回も協議をするということがないように、その前に、今、東京都が中心となってどういう形で協議会を通すかということで検討会を立ち上げているところです。","id":"exchange-088"},{"speaker":"堺委員","kind":"提案","question":"これについては要するに国で緊急経済対策、この事業が来年３月までの期限だということから、これについても第３回定例会の質問の中で、この件についても国の制度が存続するように関係機関に働きかけていただきたいし、仮に国が廃止になっても、区としても単独でこの事業が実施されるようにということで提案させていただきましたが、その際。","respondent":"福島ものづくり・経営支援課長","answer":"ですから、単純延長しないでどういった業況にある、どういった中小企業の分野でセーフティーネットができるか、その辺のところは国の動きをよく見ていかなければ、私どもが行っている事業は国の制度に乗っかった事業ですので、国の事業の動きをよく見ながら。","id":"exchange-089"},{"speaker":"堺委員","kind":"質問・要望","question":"３点目のプレミアム付区内共通商品券の件ですが、これも第３回定例会のときに、平成２３年度も継続して実施されるんでしょうかというお尋ねをした際に、これも経済動向を見ながら云々ということで、はっきりやりますという答弁ではなかったんですけれども、これについても、例えば平成２１年度、新規ということで２億円ですか、これについて区が２,０００万円。","respondent":"諸岡商業・観光課長","answer":"来年度につきまして、今年度を含めて、社会経済状況を勘案して判断させていただきたいと思っています。","id":"exchange-090"},{"speaker":"川西委員","kind":"質問","question":"１５３ページの環境相談の中での土壌汚染について伺います。最初に食育推進事業のことですけれども、その上の食からの子育て支援事業、この人数に比べますと、参加人数も少ないし、実施方法が違うから仕方がないかと思いますけれども、食育推進事業の募集方法、参加年齢層について、とりあえず伺います。","respondent":"山岡健康課長","answer":"もう１つは料理講習会ということで、対象別に子どものキッズ料理教室、あるいは子育て支援料理教室、働き盛りの方の料理教室、２０代の料理教室、高齢者のための料理教室、こういう形で実施しているものです。","id":"exchange-091"},{"speaker":"川西委員","kind":"質問","question":"私がこの中で参加年齢層ということを伺いましたのは、高齢者の食生活ということです。それからもう１つ、つくるのが面倒だという年齢にもなってくる場合もあります。そういうことからいいますと、バランスのいい食事をということを、特に高齢者に向けてどういうふうな形でこの食育推進事業の中でやられてきたのか、また今後やろうとされているのか、今後の方針も含めて伺います。","respondent":"山岡健康課長","answer":"先ほど申し上げたように、料理教室と、それから相談会ということで実施しておりまして、相談会のほうは特にどなたでも相談を受ける形です。この中で、もちろん高齢者の方からご相談いただければ、その方にふさわしいような食事の仕方等々をお答えするような形になります。","id":"exchange-092"},{"speaker":"川西委員","kind":"質問・要望","question":"できれば希望したいのは、つくるのが面倒だという人に、バランスのいい食事をどういうふうにしたらいいのか、例えばスーパーへ行って２００円ぐらいのパックがありますから、こういうものとこういうものとこういうものを毎日食べなくてはいけないというようなことを出前で指導する、例えばゲートボールの会場へ行って、入り口で１５分間足をとめてもらって話すとか。","respondent":"太田品川区清掃事務所長","answer":"初めにプラスチック製容器包装についての量の問題のご質問です。平成１９年度はモデル実施ということで１１０トンです。２０年度については１０月から６カ月実施いたしまして５９９トン、２１年度については１年間１２カ月実施いたしまして１,０７２トンになってあります。","id":"exchange-093"},{"speaker":"川西委員","kind":"質問","question":"粗大ごみの直接持ち込みという制度が始められまして、このことによって直接受け付けというのがどのぐらいの量であるのか、あるいは予算的にはそのことによって節約ができる方向性があるのかどうかを伺います。それから、土壌汚染については件数が大変多いということがわかりました。何点か、どういうところで土壌汚染の心配があるのか、どういう中身の相談か、これだけお答えいただいて終わります。","respondent":"太田品川区清掃事務所長、工藤環境課長","answer":"粗大ごみのお尋ねですけれども、これは平日回収を５台で回ってありますけれども、その分が２週間ぐらいかかってしまうということで、日曜日に区民の方が持ち込んでいただくということで開設したものです。この理由といたしましては、土地取引に関しまして、不動産の売買に関しまして、土壌汚染の情報が必須条件となっていることから、今までの工場、指定工場、作業所等の有無の問い合わせが多数あり、それに伴って相談が増加しています。","id":"exchange-094"},{"speaker":"山内委員","kind":"質問","question":"私から１５８ページの観光アクションプラン、それから１５３ページの環境費の中から、これはプラスチック容器の中間処理の経費について、時間があれば、涼しさ回復プロジェクトを伺いたいなと思います。最初に漠然と伺います。品川区に観光客、観光を目的として来ていただいている方が、平成２０年度から２１年度にかけて増えたかなと思うか、まずそこら辺の感想を伺いたいと思います。","respondent":"諸岡商業・観光課長","answer":"品川区への観光客です。私ども観光事業を地域に根ざした形で都市型観光ということで実施しております。","id":"exchange-095"},{"speaker":"山内委員","kind":"質問・要望","question":"先日の区民委員会で日刊工業新聞、これが配付されました。旧東海道、それからしながわ水族館、各地に点在する特色のある商店街、ほか大森貝塚などがありますけれども、このほかに、これからの観光資源といったことで何か思い当たるようなものがあればお聞かせいただきたいと思いますし、また、何かお考えがあればお聞かせください。","respondent":"諸岡商業・観光課長","answer":"そういう意味では、品川区はこれまでも着地型観光ということで着実に実施してきておりますし、また、今後、そういった地域の連携によってさまざまな団体、それから地域のそういったガイドボランティア等の人的資源もありますので。","id":"exchange-096"},{"speaker":"山内委員","kind":"質問","question":"着地型観光、発地型観光、今、着地型観光について大変詳しくご答弁いただきました。この発地型観光、これは私どもいろいろ考えたんですけれども、この発地型観光で１つ品川区に大きな財産といったものがあると私は思うんです。これは何かと思いますか。大井競馬場。そういった中で、この方々は大体みんな秋葉原とかへ行ってしまうんです。そういったものを観光資源として使えないのか、その辺を伺いたい。","respondent":"諸岡商業・観光課長","answer":"それで羽田空港の開港に伴いまして、競馬場も品川区と一緒に連携しながら何か事業を取り組みたいということの申し出がありました。これはまさに、委員は発地型と申されましたが、私は地域資源を大事に使っていくということでは着地型であると考えています。","id":"exchange-097"},{"speaker":"山内委員","kind":"質問・要望","question":"いつも議長から報告があるんです。これは以上で終わります。続きまして１５３ページなんですけれども、環境費、この中でプラスチックの容器の中間処理の経費、これが予算額が１億４００万円に対しまして決算額が６,９００万円と、３,０００万円以上の決算額減といったことなんですけれども、この要因は何なんでしょうか。教えてください。","respondent":"太田品川区清掃事務所長","answer":"当初、平成２０年１０月から分別変更を実施して、そのときから容器包装プラスチックについては回収をいたしました。その当時の見込みと、実際に平成２０年スタートいたしまして、実際に回収する量との乖離が出たです。","id":"exchange-098"},{"speaker":"山内委員","kind":"質問","question":"わかりました。そういった意味で、これを資源として今後考えていくのか、そのあたりをお伺いしたいと思います。なぜかと申しますと、この事務事業概要を見ますと、プラスチックは選別、それから梱包、保管といった位置づけがされておりますので、そのあたりで品川区の考え方といったものを伺いたいと思います。","respondent":"太田品川区清掃事務所長","answer":"一方、容器包装プラスチック以外のＣＤみたいな廃プラスチックについては、これは法のリサイクルシステムがまだ確立されてございませんので、分別変更に伴って燃やすごみとして清掃工場で焼却して、その余熱を使ってサーマルリサイクルを実施しているです。","id":"exchange-099"},{"speaker":"山内委員","kind":"質問","question":"プラスチックなんですけれども、燃えるごみとして出せるといった感覚が区民の皆様にあるといった中で、環境に対してすごく真剣に考えておられる方というのはきちんと分別をするといったことでありますけれども、それが安易に捨てることのできるごみといった感覚になってしまうと、どうしても資源といったことでの意識といったものが非常に低いというか、そういったところをもう少し何か高めていけるような。","respondent":"太田品川区清掃事務所長","answer":"そういう意味でいくと、こちら、事務所としては、ある程度、８割方そういう分別の変更を実施していただいていると思ってありますけれども、今後さらに５月のＥＣＯフェスティバルとか、あるいはその他イベント等の中で、十分、分別について。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"私からは１４７ページの予防接種費で、ここにはないですが、子宮頸がんワクチンについて、助成事業についてお聞きしたいと思います。初めに、子宮頸がんというものはそもそもどういう原因でがんを発症するのかということと、それから、対象者が平成２２年度は中学校１年生から３年生という対象だと、それはなぜかという理由です。これもどういう理由なのかをまず教えてください。","respondent":"吉田品川区保健所保健予防課長","answer":"実際に国の厚生科学研究で行われた調査などによりますと、中３では既に５.１％、あるいは高校２年生では１７.６％ということで、若年者の性行動という問題がありますので、なるべく早いうちに摂取を行う必要があるということで、対象者を若い年代。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"それから２０歳でそういう性交渉がないですよというのもどうやって調べるんですか。ちょっと私はここまで、がん検診と一緒にということはわかるんですが、ただ、効果という面からすると、摂取するときの年代というのが非常に厳しいのではないか、決めづらいのではないかなと思いますが、その辺と、ワクチンがどこのもので、どういう効果があるものなのかを教えてください。","respondent":"吉田品川区保健所保健予防課長","answer":"対象につきましては、国の厚生科学審議会感染症分科会等でも対象年齢についてはある程度示されているところでございまして、やはり若い年代で、１０歳から中学世代という話です。１０歳未満につきましては、摂取が基本的には認められていないです。","id":"exchange-102"},{"speaker":"西本委員","kind":"確認","question":"この仕様書の中を見ると、１０歳から１５歳の女児および２６歳以上の女性における予防効果に対するデータがないと言っているんです。抗体ができたけれども、それは確認できているということはわかっています。だけれども、抗体の量ががんの発症を予防するかどうかまでのデータはないということを言っているんです。それで、このワクチンを推奨するという理由がちょっと私は理解できないです。","respondent":"吉田品川区保健所保健予防課長","answer":"ただ、抗体価あるいは効果と、先ほど申し上げた前がん病変、あるいはがんの早期といったものの関係は明確にありますので、このワクチンについては効果がある程度期待できると考えております。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"これから調べていかなければならない、効果があるかもしれないねというところが今のワクチンの現状です。その状況の中で、いろいろ行政側の考え方はあるかと思いますが、課長はドクターでもありますので、ドクターの考え方も含めて、このワクチンの効果に対しての今後、検証しなければいけないとか、気をつけなければいけないとかという判断はいかがでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"それから海外、既にアメリカ、あるいはイギリスをはじめとして世界で多くの国で導入されておりますが、やはりある程度前がん病変としては少なくなる、あるいはなっていくだろうという話ですので、区としてもその方向で導入を進めていきたいと考えております。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"今、開発がどんどんされているということで、今のサーバリックスではないものも今、認可を申請している最中だと言われていますけれども、それが今、どういう状況なのか、そしてそれがこれと比べるとどういう効果があるのかということです。それで、サーバリックスを打ってしまったという場合に、次の出てくるものが効果があると言われた場合に、これを打てるのかどうかということに関してはいかがでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"２つ目の新しいワクチンを混合して打てるかということについては、現在、情報はございません。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"公費を使うわけですから、私はこれはちょっと早い判断ではなかったのかなと考えています。効果のあるもの、間近に認可がおりようとしているものがありますので、その効果を検証しながら決定すべきではなかったのかなと思って意見を申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問","question":"ですが実際は、向こうと競争して、海外へ出ていったら、雇用は国内からは少なくとも私はなくなるのではないかと、そういう事業に品川区が、一地方自治体が私は率先して予算を組むということはちょっとおかしいのではないか、逆にやるとして、タイに進出しました、次、インド、インドネシア、ほかにもやっていくんですか。１カ所だけというわけにいかなくなりますよね。","respondent":"福島ものづくり・経営支援課長","answer":"今ありました海外進出によりまして雇用がなくなるですけれども、先ほども説明させていただきましたが、今回、今年の２０１０年の「中小企業白書」を見ますと、逆に海外に出ていった企業のほうが発展している、そういうデータがあります。","id":"exchange-107"},{"speaker":"須貝委員","kind":"質問・要望","question":"でも、雇用は向こうに行ってしまうではないですか。これについて、毎年ちょっと言うのかもしれないですが、日本の経済状況もありますが、実際これで成果は上がっているんですか。そうすると、何か振興策、活性化事業というものが私は何か抜本的に直さなくてはいけない、見直さなくてはいけないのではないかと思いますけれども、どうでしょうか。その２点についてお聞かせください。","respondent":"諸岡商業・観光課長","answer":"商店街の皆様が積極的にそういった支援を活用して、商店街の中で商店街の今後等のことについてよく検討していただき、計画を立てて実施し、商店街の発展に向かっていっていただくということが一番必要なことであろうと考えております。","id":"exchange-108"},{"speaker":"須貝委員","kind":"質問","question":"活性化のために何がいいのか、今、さまざまな支援事業をすることがいいのか、でも、実際、その成果というのは我々が目で見てもあらわれていないのではないか、それで、では何が一番いいんでしょうか。でも、それは一過性ではないですか。一過性で本当にこの難局を乗り切れるんでしょうか。私はそこはしっかり考えてほしいと思います。国がやっている話ですが、その辺についてご見解をお聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"ただし、信用保証を使わずに何もしなかった場合、どうなっていたか、そういうことを考えますと、今回の国が行いました１００％保証制度というのは十分効果があったものだと考えていますし、私どもが行いました３年間無利子のものも十分効果があった。","id":"exchange-109"},{"speaker":"若林委員","kind":"意見","question":"冒頭に、先ほど子宮頸がんワクチンについての議論がございました。一方では、多くの区民、また国の承認があった中での、もう一歩これを、当然、がん検診にセットにしながら、より予防を高めていく、発症を抑えていくという、この効果については一定の品川区の行政判断といいますか、政治判断を私は高く評価したいと思うんですが、これについてのご見解をひとつお願いしたい。","respondent":"吉田品川区保健所保健予防課長","answer":"委員がご指摘のように、ワクチンの効果ならびに検診とのセットによる啓発ならびに検診の実施といったことについては、品川区としても大変効果の高い、期待できるものと考えております。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"これはたしか平成２０年度から、そして今回の２１年度決算ということで決算額が出ております。そこで、改めてこの事業の総括をぜひしていただきたい。できれば、できるだけ数量的に数値的に示していただきたいと思います。この事業の目的、またこの事業実績、いわゆる事業の内訳、またそれにそれぞれどれほどの金額を使ったのかというところの全体的な総括をよろしくお願いいたします。","respondent":"諸岡商業・観光課長","answer":"小規模商店街活力づくり支援事業の中の再生モデル事業についてのお尋ねです。平成２１年度におきましては、再生モデル支援事業ということで山王通り商店街、ここに支援事業を実施いたしました。それから、昭和通り商店街にビジョン策定の事業を行いました。","id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"事業の内訳をしっかりと聞きたいんです。それで、平成２１年度、コンサルタントが入ったのかどうか私は存じ上げませんが、そこも含めたパンフの発行部数、金額、いわゆる１枚ごとの単価、こういったところは最低限、決算ですので示していただきたい。","respondent":"諸岡商業・観光課長","answer":"申しわけありません。訂正させていただきたいと思います。交付額は６２４万円の誤りです。大変申しわけございません。経費の内訳ですけれども、「商店街ものがたり」というコミュニティ紙を作成いたしました。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問","question":"６４万５００円割る１万５,０００部という計算ですか。このぐらいは、すいません。単価は出しておいてください。出ますか。","respondent":"諸岡商業・観光課長","answer":"１部当たり４３円です。","id":"exchange-113"},{"speaker":"若林委員","kind":"確認","question":"それの確認と、そうすると、仕組みづくりが本当にできたのかどうかというところがこの事業を検証する最大のポイントだと思います。そこで、この事業を実施した前と後、平成２１年度決算を終えてどういうふうに、例えばお客様が１日当たり何人増えたとか、そういう定量的な観測というのはされたのかどうか、要するに、この事務事業の評価を総括的にどうされているのかということをお聞きしたい。","respondent":"諸岡商業・観光課長","answer":"その具体的な商店街の来客者数とか、そういった調査は行ってございませんが、１年だけの取り組みではなかなか効果が出ないということで、引き続き区の一般的な支援策を活用して、引き続き商店街では事業を継続していきたいというようなことを予定されております。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"すると、商店街の引き続きの努力でやるのであれば、そもそも２年間で１,０００万円以上かけたこの事業が、仕組みづくりが道半ばで終わって、これでこの商店街が終わって、また次の昭和通りとかという話になってきているわけですよね。こういう事業のあり方でよろしいんでしょうか。","respondent":"諸岡商業・観光課長","answer":"集中的に商店街をモデル地区に指定いたしまして実施した期間といたしましてはこの２年間ですが、その後も商店街支援は続いておりますし、商店街の事業計画に沿って区では支援をしていきたいと思っているところです。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問","question":"小規模商店街のモデル事業に対しての助成です。その今後のあり方とか、それから、４３円という単価が高いか安いかは私は存じ上げませんけれども、もう少しこのモデル事業、再生事業の第１号としての何かもっと成果を示していただけないものでしょうか。","respondent":"諸岡商業・観光課長","answer":"そういった２年間の取り組みを活かして、今後の商店街の事業に活かしていただくとともに、それに対しての支援を引き続き行っていきたいと思っているところです。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問","question":"次の街なみ緑化助成事業、時間がありませんので、この事業の目的と、それからこの補助金、執行率の低さ、４４.１％の執行だとありましたので、ここのご説明と、それから補助金が国と特定財源のみということで一般財源が入っていませんが、特に一般財源が入っていないということではなくて、この補助金によってこの事業の中身にどういう縛りが何かあるのかどうかということを１つ聞きたい。","respondent":"藤田水とみどりの課長","answer":"今回の事業の執行率の低さですけれども、私どもいろいろな形でＰＲはしているものの、低いというのが確かに実態です。今回の実態調査を踏まえて、今後どのように効果的にＰＲをしていくか、これについてはもう少し考えながら事業を進めたいと考えています。","id":"exchange-117"},{"speaker":"大沢委員","kind":"質問・要望","question":"しかしながら、三大疾病と言われますがん、そして脳卒中、心筋梗塞ということで、脳卒中、心筋梗塞に関して制度上、いろいろな経費上、その検診を行うに当たっていろいろなさまざま困難な部分はあると思うんですけれども、なぜ三大疾病のうち一番、双方とも、病気に軽重はつけられないとは思うんですが、心筋梗塞ならびに脳卒中、すぐに倒れて死に結びつくような病気でありまして、その部分に関して。","respondent":"山岡健康課長","answer":"特定健診にはそれぞれがん検診というものはございません。これはがん検診は健康増進法に残されたということで私どもが実施していると、基本的には４０歳以上は特定健診でまずは健診を受けていただく、こういうふうな形で平成２０年からなっているものです。","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"健康増進法ということで、今、課長のほうで伺いましたけれども、もう一回伺います。肺がん、大腸がん、胃がん、三大疾病、ＭＲＩをはじめ、それらの、確かに脳ドックは非常に高価なものがありますけれども、なぜこのがん検診の中に入れるのがこの２つについては困難なのか、その背景がありましたら教えていただきたいんですが。","respondent":"山岡健康課長","answer":"ただ、状況として、この２つについてはがんにかかる方も増えてきた、あるいは喉頭がん検診については喫煙の問題もありますので、そういうことも考えまして、この２つは独自に実施しているという状況です。","id":"exchange-119"},{"speaker":"大沢委員","kind":"質問","question":"今、独自に検診をしている疾病２種類があるということですけれども、独自にやって、今、国のがんの指針に基づいてということが胃がん等々でありましたけれども、独自にやっているのが２つあるのであれば、今の二大疾病の２つ、非常にこれは危険な命にかかわることなんですが、そこのところというのは。","respondent":"山岡健康課長","answer":"そういうものに基づいてやっておりますので、今、委員がお示しになりました検診につきましては、要はその検診以外のものにつきましては慎重に検討していかないと、どれほどの有効性があるのか、もちろん個人で受けるというもの、任意で受けるというものはあります。","id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"よろしくお願いします。続けて質問行きます。それで、こころの健康づくりということで各種相談、さまざまな５つ事業を行っておりますけれども、これも定期検診ということで、チェックシートか何かを用いて、これも定期に健康診断、早目の察知をするためには定期的に行うことも必要だと思うんですけれども、そこのところはどういうふうにお考えになりますでしょうか。","respondent":"福島品川区保健所荏原保健センター所長","answer":"ただ、ホームページの中に、自分でできるチェックシートというものが入っていますし、また、来年度ですけれども、来年度は自分たちでできるようなリストを入れていこうかと考えていますので、検診と、これだけでの検診というよりは。","id":"exchange-121"},{"speaker":"大沢委員","kind":"質問","question":"これは話のやりとりですから、ご納得いただけない部分もあろうかと思いますが、先ほど来、１つの自殺の予防という観点から伺ってみると、先ほど来からニュアンス的に、どうも受け身的な部分で積極性が私は感じられないような気がします。ご感想を伺いたいと思います。","respondent":"福島品川区保健所荏原保健センター所長","answer":"事業としてそういう検診という形でやるというよりも、我々はそういう自殺をなさる方のほぼ８割の方が周りの人に相談したり、眠れないとか、いろいろな症状等があるということから、自殺をする危険性のある人を気づこうということで、庁内連携、また庁外連携。","id":"exchange-122"},{"speaker":"大沢委員","kind":"質問・要望","question":"わかりました。１４９ページですが、先に１６１ページ、海外進出の事業について質問します。去年ですか、初めてＭＥＴＡＬＥＸということでタイ国のバンコクでビジネスマッチングを行いました。その中でＪＥＴＲＯとの協調関係ができて、その後、ＪＥＴＲＯとはどのような連携がとれるような形で区からアクセスし、またあちらからはどういうアクションがあったのかを教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"今年度につきましては、今度海外ビジネスサポートセンターをＪＥＴＲＯのあるビルの１０階に設置する予定です。そこにつきましてもＪＥＴＲＯとの連携を図っていくということで、ＪＥＴＲＯでの支援を全面的に受けるという形になっています。","id":"exchange-123"},{"speaker":"大沢委員","kind":"質問・要望","question":"次、また質問を移ります。１６０ページなんですが、空き店舗対策についてお伺いいたしたいと思います。空き店舗、この使い方についてお伺いしたいと思うんですが、喫煙場所と空き店舗対策についてという表題でお伺いしたいと思います。中には空調機などが置いてありました。持ち主とのいろいろな調整も必要かと思いますが、このアイデアについていかがお考えになりましょうか。","respondent":"諸岡商業・観光課長","answer":"そうなりますと、収益がないということで、どのような形で運営されていくのかというようなこともありますし、そういったことも含めて、空き店舗対策としてそれが適当かどうかということにつきましてはもう少しヒアリング等をさせていただいて。","id":"exchange-124"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、喫煙とたばこを吸う人、吸わない人、いろいろと多種多様な意見になっていますので、貸す方も、たばこのにおいがついてしまったりとか、造作を考えると、いろいろなところがあります。それから、そ族というか、蚊の駆除について伺いたいと思います。しかしながら、雨水升の中には多くの蚊の幼虫がいるわけでありまして、そこのところはどのように対処を今、されているのかを教えてください。","respondent":"荒井品川区保健所生活衛生課長","answer":"蚊の対策についてのご質問です。雨水升の対策ということでお答えいたします。現在、雨水升の対策につきましては、できるだけそこに泥であるとか、木の葉であるとか、ごみであるとかをためないように清掃していただくお願いを１つしています。","id":"exchange-125"},{"speaker":"大沢委員","kind":"質問","question":"例えば、飛散するのがだめであれば、聞いたところによりますと、食用の油を入れるだけでも違うという、要は空気、呼吸ができなくなるようにすれば蚊は死滅するというようなことも聞いていますのですけれども、そこらのところはどういうふうに考えたらいいでしょうか。お願いします。","respondent":"荒井品川区保健所生活衛生課長","answer":"雨水升について、メッシュの金網がうまく設置できないというご質問だと思うんですけれども、まず、指導の部分につきましては、保健所に相談していただければ、職員が参りまして、一緒にどういった形でやったら一番適当であるかということを探らせていただいているところです。","id":"exchange-126"},{"speaker":"大沢委員","kind":"質問・要望","question":"いろいろな部分で蚊については処方が難しい部分があります。しかしながら、感染症の原因にもなりますので、何か最善の策がありましたら、また保健所でお考えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"土井委員","kind":"質問・要望","question":"何かそういう分類があるんだろうなと思います。そこの出入りも含めて、どういうのがあるのか、へこんだほうはあまり大声で聞きたくないんですけれども、出ていったほうは大声で聞きたいものですから、立派に成業されて独立されたところは大声で聞きたいものですから、その辺について、この一、二年、あるいは３年ぐらいのところでありましたらお聞かせいただきたいということが最初の質問です。","respondent":"福島ものづくり・経営支援課長","answer":"創業支援センターですけれども、確かに武蔵小山と西大井、天王洲等にあります。武蔵小山につきましては、１階の貸し店舗が３店、６階に８事務室です。西大井につきましては、こちらはオフィス部分とブースがございまして、オフィスが５つ、ブースが１０です。","id":"exchange-128"},{"speaker":"土井委員","kind":"質問・要望","question":"今現在、そういうことでいきますと、今現在、例えば空いているんですか。みんな発展的にお出になって、今もうそういう時期だから皆出ていってしまっていましてということでしょうか。それには対策も必要になってくるかもしれないものですから伺っているので、募集も含めて、どうなっていくのかということを知りたいものですから、それを聞いているので、よろしくお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"空き状況ですけれども、現在、西大井で１室空いてあります。それは先日、出ていかれた企業がございましたので、空いていると。今、募集をしている段階です。天王洲につきましてはすべて埋まってあります。","id":"exchange-129"},{"speaker":"土井委員","kind":"質問・要望","question":"わかりました。それで、創業支援ですから、一定の時間的な制約があるんだと思うんですけれども、今もう出ていかれた方はいろいろな意味でお出になったので、今いらっしゃるので最長何年ぐらいいらっしゃって、もう時期が来るんだけれども、どうするのかななんていうような人たちもいらっしゃるんじゃないかと思うんですけれども、その辺はどのようになっているでしょうか。お聞かせいただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"出ていった企業につきましては、先ほど言いましたように、事業拡大する場合と両方あります。ただ、天王洲の場合ですと、ブースという小さい場所ですけれども、オフィスにステップアップするとか、そういう形でもレベルアップする企業というのはあります。","id":"exchange-130"},{"speaker":"土井委員","kind":"質問・要望","question":"できるだけ、本当に先ほどのようにステップアップしていっていただきたい。やってもらいたい。そしてそこに、それこそ先ほどのお話ではないけれども、海外にも進出するぐらいに発展的に進めていって、元気でアイデアのあるところを増やしていきたいなという思いで聞かせていただいておりますので、よろしくお願いしたいと思います。１５３ページにあります早川町の里山再生事業です。","respondent":"工藤環境課長","answer":"環境課の取り組みとしましては、一定程度の敷地の植林地に植林をしましたり、自然体験ということでネイチャーガイド的なことをやっておりまして、アプローチ的には環境面に重視した取り組みを行っているものです。","id":"exchange-131"},{"speaker":"土井委員","kind":"意見","question":"ただ、だから、こういうのが、こういう決算とかの仕事という面で、事務という面で１つまとめるとどうなるのかなと、要するに、これは先ほど言った植林の植木の代金ですよ、それを掘るためのくわの代金ですよというのだったら、そうかということにもなるんですけれども、全体的に幾らかかっているかなということはなかなかわかりにくくなるかもしれないということがあるので。","respondent":"太田品川区清掃事務所長","answer":"区民の皆様には、当時、「ごみ・資源の分け方・出し方」というものの中で具体的な品物も写真等を入れて掲載しておりますし、次にそれがどう再商品化していくかということについても資源の流れということでその中で掲載させていただいていますし、あるいはその他説明会。","id":"exchange-132"},{"speaker":"土井委員","kind":"質問","question":"説明会を開いたか開かないかを聞いているのではなしに、どういうふうに再処理をされているんですかと、ちょっと不勉強なもので聞かせていただいているので、聞かせてください。","respondent":"太田品川区清掃事務所長","answer":"コークスの場合については、鉄工所の製鉄所でコークスのかわりにプラスチック類をかわりに使うというような形で再商品化になっているです。","id":"exchange-133"},{"speaker":"土井委員","kind":"意見","question":"早い話はそうですよね。それからもう１つのほうも、一定程度分解はするけれども、炭素を回収しているという形になっているわけですよね。それをどう解消していくのかということをやらないと、大変な疑問が残ったままだと。これを実は国が間違っているなら国が間違っているといって変えなくてはいけませんし、区独自で、あるいは都全体で近隣も誘い合ってやるということもできるのではないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"１５９ページの商店街の活性化について伺います。とりわけ、私は八潮に住んでおりますので、八潮の商業施設の問題で伺いたいと思います。ところが、八潮に対する助成、商業施設への助成が今、どういうふうに行われているのかというところを知りたいと思うんですけれども、規模と、そして助成の額、どんな内容で行われているのかをまず教えていただきたいと思います。","respondent":"諸岡商業・観光課長","answer":"パトリア店舗会に対します支援ですが、商店街のにぎわい事業の中でイベント事業への支援ということで、ここでは夏のイベント、それから冬の年末、クリスマスにかけてのイベントを行っておりまして、夏のパトリア店舗会のイベントにつきまして１７３万円。","id":"exchange-135"},{"speaker":"南委員","kind":"提案","question":"予特のときに伺ったときには、八潮南小学校跡地の交流施設ができたそのときに人を呼び込むようなことも考えていきたいという答弁なんですが、まだまだそれは先だし、本当に今から本腰で考えていただかなくてはいけないと思っているんです。それで、私としては、１つの提案なんですけれども、空きスペースが今、たくさんあるわけです。ふんだんにと言っていいくらいにたくさんあるわけです。","respondent":"諸岡商業・観光課長","answer":"そのほかの支援メニューもありますけれども、そのようなことについてはあまり活用されておりませんので、まずは品川区の商店街支援メニューがたくさんありますので、そういったことを説明会等でご説明はしているんですけれども、改めて理解していただきながら。","id":"exchange-136"},{"speaker":"南委員","kind":"提案","question":"ですから、そういう担い手がいない、そういうところを手だてを、しっかり声を聞いて、そしてどういう対策があそこの地域には合うのかということを具体的に見つけていく、検討して知恵をお互いに出し合う、そういう作業が必要ではないかなと１つ思います。それが１つ、２つ目の提案です。そういう幾つかの提案をしたんですけれども、ぜひとも検討していただきたいと思っていますが、いかがでしょうか。","respondent":"諸岡商業・観光課長","answer":"店舗会ということで、私どもといたしましては商店街と同様な対応を図らせていただいているところですが、いろいろご相談には応じておりまして、店舗会として何か取り組むということであれば支援はする体制もありますし。","id":"exchange-137"},{"speaker":"南委員","kind":"提案","question":"幾つかの提案をさせていただきましたけれども、これはパトリア店舗会の声ではありませんので、私がいろいろな方々の声を聞きながら、住民の方々の声を聞きながら、今、提案したんですけれども、１つ１つについて３点提案しましたけれども、ちょっと見解を伺いたいということでさっき質問したんですけれども、全くなくて、一くくりにして、声は聞いていくというだけだったので。","respondent":"日下部企画部長","answer":"ですから、今後、自治会からまたいろいろお話があれば、それについては区としても対応させていただきたいと考えているところです。","id":"exchange-138"},{"speaker":"南委員","kind":"質問・要望","question":"自治会のほうからというただし書きがあるんですけれども、自治会は、まちづくりという点ではもちろん声は聞いていただきたいと思うし、すべての住民を対象にしたまちづくり委員会という、商業施設に限ってつくっていくということは私は大事なことだと思いますので、私も自治会長の方には働きかけたいと思うし、区もぜひそういうキャパで接していただきたいと思うのが１つと、それから自治会だけではなくて。","respondent":"諸岡商業・観光課長","answer":"先ほど申し上げましたように、店舗会からのお話はよく聞いて対応していきたいと考えています。","id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"よろしくお願いいたします。くれぐれもよろしくお願いします。それから、もう１つ商業施設なんですけれども、北側エリアにある生協が入っている小規模の施設があります。あそこが来年の３月には撤退するということになっているんですが、その件についてどの程度品川区としては受けとめて、その後のフォロー等々についてどういうふうに考えておられるのか、この際、伺いたいと思います。","respondent":"諸岡商業・観光課長","answer":"今の撤退されるというお話は、私どもとしては把握はしてございません。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひ早速、八潮の住民の商業の問題、暮らしの問題ですから、調査をしていただいて、それなりの対応をしていただきたいと思いますので、時間との関係があるので、これは要望でいいですけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"三上委員","kind":"質問","question":"私は１５１ページ、健康づくり支援事業、それから１５５ページ、リサイクル推進事業、それから、それに関係する環境対策費ということになるでしょうか、環境対策費として温暖化対策に関係して２つの視点からお伺いします。そのほか時間がありましたら、またそのときにお願いしたいと思います。ありますよね。水洗トイレの少水化、少ない水といった点でもいろいろ叫ばれていて、随分意識が高くなってきた。","respondent":"山岡健康課長、太田品川区清掃事務所長、工藤環境課長、藤田水とみどりの課長","answer":"私からは、温泉と健康づくりということでお答えしたいと思います。１００円ライターの回収についてのお尋ねです。いろいろと住まいの省エネ化はありますけれども、１つは建築物の省エネ化ということで、いろいろと断熱、気密性能が高く。そういった観点から考えますと、常設の緑というよりか、施設を管理運営する中で取り組んでいく施策と考えています。","id":"exchange-142"},{"speaker":"三上委員","kind":"質問","question":"温泉のことでありますけれども、この健康づくりという中にあって、品川区としてはその成分的な部分はどういうふうに掌握しているんですか。通常、どこかの温泉なんかに行ったりすると、効能書きみたいなものがあったりしますよね。入ったままのものをどう回収するのかということについての、それはもう品川区としては、来年の９月を考えたら、対応せざるを得ないのではないでしょうか。","respondent":"荒井品川区保健所生活衛生課長、太田品川区清掃事務所長、宍戸施設整備課長","answer":"健康づくり事業への利用といいますか、活用ということにつきましては、先ほど来、お話の出てありました、例えば出会いの湯におけるものであるとか。来年の１月から２月にかけて、陶器・ガラス・金属ごみの収集回数の変更に伴いまして、その部分の特集号をつくりますので、その中でページを割いて。学校その他施設建設に当たりまして、熱線吸収ガラス、緑のカーテン等々、他区でもさまざまに事例が出てまいっておりますので。","id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"その反面、１,０００円、２,０００円取るところもある。ただ、それだけにどういう価格のものを使ったらいいのかという検討をせざるを得ないかわかりませんけれども、しっかりとそういった対策をどういうふうにするかということについては、緑を増やすという意味もあってのそういう取り組みと一緒に考えていっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問","question":"１４７ページ、エイズ予防啓発費、１４８ページ、がん検診、１５１ページ、保健衛生施設費について、また、あと時間がありましたら質問を続けます。エイズ予防啓発費、毎年やっていただいているんですけれども、この傾向はどうなのかなと、いわゆるエイズの抗体検査をして、陽性というような回答が出てくる状況がどうなっているかを簡単にお聞かせください。","respondent":"吉田品川区保健所保健予防課長、山岡健康課長、荒井品川区保健所生活衛生課長","answer":"昨年のエイズのまず抗体検査の結果ですが、３１３件やりまして、１件の陽性が出ております。そういうことで我々はがん対策については考えているところです。保健所が庁舎内に入りましたメリットといたしましては、１つは危機管理体制がスムーズにとれるようになったこと、それから２つ目には。","id":"exchange-145"},{"speaker":"須藤委員","kind":"質問","question":"がん検診についてはいろいろなストレスということなので、検診をしなくては、しなくてはというのもまたストレスになってきてしまうので、あまり今お話しのように、検診が、検診がということも１つあるのではないかなというような思いがあるので、それから、エイズは１件ということなんですが、兆候がどうなのかなと、今までずっともう二十何年こういう形でやっているんですけれども。","respondent":"吉田品川区保健所保健予防課長","answer":"失礼いたしました。エイズの検査につきましては、抗体検査につきましては年間大体３００から４００件で推移しています。ただ、年によって陽性者が出たり出なかったりですが、増加している傾向には少なくともないと考えています。","id":"exchange-146"},{"speaker":"須藤委員","kind":"質問","question":"１５８ページの観光アクションプランと１５６ページの清掃総務費と船舶中継所維持についてお尋ねします。東京二十三区清掃一部事務組合の流れ方が、いわゆる２３区、このままでいくのではなくて、各地のというような話があって、その後の経過を見てというような結果になったと思うんだけれども、そのあたりの状況がどうなっているかを教えてください。","respondent":"太田品川区清掃事務所長","answer":"ところが平成１５年７月に、区長会においては、２３区は工場のある区もない区も相互に協調・連携し、全体の責任として特別区の区域から排出される一般廃棄物の安定的な中間処理体制を確保するという仕切りができまして、その後、中間処理は平成１８年４月以降も当分の間。","id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"清掃一部事務組合は当面の間というので、当時もいろいろ議論があったと思うんだけれども、そのまま推移してしまって、何のアクションもないよというのはどんなものかなと思っているんだけれども、品川区としてはいかがなものでしょうか。","respondent":"太田品川区清掃事務所長","answer":"当時は品川区も少なくとも地域ブロック体制というようなことで主張してございましたので、今後も機会あるごとに、少なくともそういう地域ブロック、あるいは各区への移管ということを意見表明をしていきたいと考えているところです。","id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"あそこに像ができて、ある団体から今度はブロンズ像が寄贈されて、１３日に披露なさるというようなお話も伺っていますけれども、坂本龍馬が今までのでは靴を履いていたけれども、今度は１９歳の若いときの像で、草履の像にしてあるというような話も聞いていますけれども、あそこの名所になる大砲の跡というのにただ石が載っているだけといようなことで、その辺の大砲をものづくりの中で一緒に研究して。","respondent":"諸岡商業・観光課長","answer":"それからプレミアム付区内共通商品券ですけれども、いろいろ多方面、商店街のご意見、また区議会の皆様方のご意見も含めて、総合的に来年度につきましては検討させていただきたいと考えています。","id":"exchange-149"},{"speaker":"須藤委員","kind":"意見","question":"龍馬の大砲はどうなるのか、大砲をつくってくれるかどうか、それから、共通商品券は今後の動向というか、議会の云々というような話もあるんだけれども、これだけ区民の方々が期待したり、商店街もそれだけの活動ができるという形なので、非常にいいアイデア、ただ、費用的にも全部今年みたいな数字ではなくても、しっかりしたそういう支援ができる仕組みはつくっておいてやるべきだと思うんですけれども。","respondent":"諸岡商業・観光課長、福島ものづくり・経営支援課長","answer":"今、砲台の件につきまして、まずは今申し上げましたのは龍馬像の周辺の整備から始めさせていただいて、その上でその次のことについては考えていきたいと考えています。龍馬のところの大砲ですけれども、どのようなことができるのか、今の時点ではわかりませんけれども、異業種交流会等もありますので、そういうところでどんなことができるのかについて、できるかできないかも含めて、どんなことなのか。","id":"exchange-150"},{"speaker":"須藤委員","kind":"質問・要望","question":"１６０ページから１６１ページに、ものづくりで大崎駅周辺ものづくりの準備会をしてきたんだけれども、この後の検討結果、それから１６１ページ、城南地域の合同の商談会をやって、この結果、それからそのあたりをちょっと聞かせてください。","respondent":"福島ものづくり・経営支援課長","answer":"城南の商談会につきましては、９月に実施しまして、品川区内からは２０社ほど参加して、それぞれ成果を上げていると聞いてあります。","id":"exchange-151"},{"speaker":"須藤委員","kind":"意見","question":"大崎ビジネスクラブが立ち上がって、幾つかアイデアが出てきているということなので、ぜひ今後ともしっかり支援をして、やはり技術の品川だと言われるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/696113?Template=document&Id=1330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":115796,"voices":355}},{"id":"h22-20101108-4","meetingId":"h22-c-settlement","date":"2010年11月8日","dateIso":"2010-11-08","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件抜き出しています。","topics":[{"id":"topic-01","title":"◯鈴木委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"◯鈴木委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"私は、成果報告書、１６４ページ、道路新設改良費の補助１６３号線整備、商店街電線類地中化事業、１６８ページの公園新設改良費、時間があれば１６２ページの土木総務費の駅周辺等放置自転車対策費についてお伺いいたします。電線類地中化事業についてお伺いいたします。商店街の皆様からもきれいになってよかったというお話をお伺いいたしております。","respondent":"藤橋都市整備下水道課長","answer":"最後にお話のありました商店街の今後の電線類地中化に当たりましては、２カ所の選定に当たりまして、平成１５年度当時に１０４の商店街にいろいろヒアリングして、意向調査を行い、物理的に施設の埋設が可能なのかどうか等を調査して、最終的に２４の商店街を絞り込み、その後。","id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"そういった中で、大井の滝王子通りですけれども、ここは計画道路ということで拡張が予定されているようですけれども、ほとんどそういった様子はなくて、とても難しいのではないかと思います。滝王子通りの現状のご認識とか今後の安全対策がありましたらお教えください。","respondent":"品川防災整備担当課長","answer":"現在、土地の購入が１件ございまして、大体２件から３件ほど交渉している段階です。拡幅につきましては、現在地区計画というものをかけておりまして、その中で、建て替えをするときには、必ず１０ｍになるように家を下げてもらうという形で縛りをかけております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"補助１６３号線についてです。その先の光学通りから池上通りに抜ける三ツ又交差点は、ご承知のとおり、右折が大変危なくて、あそこは危な過ぎて皆さん気をつけるので、逆に事故が少ないというお話ですけれども、右折レーンをつくることや右折信号をつけるなどの対策をとったほうがいいのではないかなと思っているんですが、ご認識をお伺いさせていただきたいと思います。","respondent":"藤橋都市整備下水道課長、藤木交通安全担当課長","answer":"先週の１１月５日から区が電線類地中化工事に着手したところでございまして、今後地面を掘って埋める工事が続きますので、これまで以上に安全対策の徹底を図るとともに、地域の声も聞きながら、きめ細やかな対応をしてまいります。それで、警視庁の本部にさらにいろいろ上申等を大井警察署でもしておりまして、現在のところは歩行者の保護の観点から、池上通りを進行する横断歩行者の信号機の青信号を延ばせないかなど。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に大井中央公園についてお伺いさせていただきたいと思います。確かに私も子どもが遊んでいるというところをあまり見たことがないですし、浮浪者やタクシーの方のトイレとして使われているときのほうがよく見かけるわけですけれども、あの辺にあれだけの広さの公園はないので、芝生化とか、公園の管理を含めてのお考え等がありましたらお聞かせいただければと思います。","respondent":"齋藤道路公園課長","answer":"委員のご指摘ですけれども、都心の中の森ということでもって、高齢者の方に大変評判のいい公園です。もう少し公園の全体の維持管理については、防犯面での見通しをよくするように努めたいと思います。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"すみません。ちょっとよく聞こえなかったんですけれども、高齢者の方に評判はいいということで、子育てしているお子さんたちがちょっと遊びにくい公園なのかなというお話をお伺いしたので、ぜひともそういうことを対応していただけたらなと思いましてご質問させていただきました。それから、子どものための遊具の面とか、そういう面では改良とかあるのかもう少し教えてください。","respondent":"齋藤道路公園課長","answer":"遊具が少し古くなっているのは事実ですので、遊具を取りかえるなど、少し子ども向けの新しい試みをしてみたいと思います。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間がなくなってしまったのですけれども、最後に、大井町の駐輪場の不足についてお伺いさせていただきたいと思います。来年度に阪急ができるということですけれども、条例では店舗面積２０m2当たり１台ということですが、駐輪場の今後はどういう形になるかをお聞かせいただければと思います。","respondent":"藤木交通安全担当課長","answer":"阪急周辺の駐輪対策ですけれども、現在のところ、具体的な駐輪場の新設等の計画はございませんけれども、このような附置義務のある業者などには、事前に協議を行いまして、必要な分の駐輪場を整備していただきたいというような依頼をしています。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"私からは、成果報告書の１６２ページ、土木管理費の中から、道路台帳補正事務、地籍調査事業、指定道路等台帳整備事業について、１６５ページ、道路橋梁費の中から、今質問のありました商店街電線類地中化事業について、１６９ページ、都市計画費の中から、時間があればですが、東急目黒線緑道等整備事業について、順番にお伺いしたいと思います。","respondent":"井浦土木管理課長","answer":"平成２１年度におきましては、二葉三丁目および西品川二丁目の一部を実施いたしまして、０.１９Km2を完了しています。国庫補助の負担割合がございまして、国が２分の１、東京都が４分の１補助ということになってあります。","id":"exchange-007"},{"speaker":"浅野委員","kind":"意見","question":"この事業というものは、区民の財産を管理する本当に重要な事務であるということで、年数もかかるわけですけれども、これらに対する問い合わせ、区民の方からもあると思いますし、また建設関係の業者からも随分あるかと思いますけれども、年間でどのくらいあるものなのかということと、提供方法ですけれども、例えば口頭だけで終わるものなのか、それとも例えば図面を出して、提示をして、回答するものなのか。","respondent":"井浦土木管理課長","answer":"現在土木の道路台帳平面図というものにつきましては、これまで窓口等々で、業者あるいは個人の方に閲覧ということで行っておりますが、昨年の１０月からインターネットでも見られるようになりまして、この窓口相談件数についても、若干の推移があります。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"こんなに多いとは私も想像していませんでしたけれども、その中で、昨年からインターネット上で見ることができるということで、件数も減ということで、合理化も図られていくのかなと思いますが、先ほどの土木管理新システム、こういう形で構築をされておるわけですけれども、結局基本となる地図というのはこの３種類だけなのかなと思えるわけですが、このような形で提供しつつ。","respondent":"井浦土木管理課長","answer":"地図の種類につきましては、今後もさらにデータベースをアップさせる中で、工事の内容、あるいは公図データシステム、認定、改廃、告示、情報システム等々、充実させてまいりたいと考えております。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"２つの商店街ということで、北品川と戸越銀座が選ばれたですが、今後北品川が、来年度ぐらいですかね、完了するような計画だったと思いますけれども、その後の商店街の電線類の地中化について、対象としている、また考えている商店街が今あるのかどうか。ないのであれば、今後どのような形で決めていくのかお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"今後につきましては、２４の商店街に改めてヒアリングをした上で、物理的に入るのかどうか、また地域の一定の負担が得られるのかどうか、また長期間にわたるため、ご理解、ご協力が得られるのかどうか、それから財源の確保の課題も含めて。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"調査をしたのが今から７年前ということもありまして、それぞれの商店街も、いろいろ経営的なところ、景気のところも含めて、かなり変動しているのかなと思われます。それはただ単に順番なのか、それとも、設置できるところから順番なのか、それとももっと商店街と地域の発展ということを考えた上での順番なのか、このような考え方というのは今あるのかどうかということをお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"商店街につきましては、先ほどもちょっとお話ししたとおり、平成１５年当時にご要望されている商店街がありますので、まずはその商店街にヒアリングをした上でということになるかと考えています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうことで、新たに手を挙げてくる商店街も多分あるかと思いますので、そこら辺につきましては、ある程度の検討というんでしょうか、それも進めていただければなと思うところです。現在におきます区民の方からのご意見、またご要望等ございましたらお伺いします。","respondent":"齋藤道路公園課長","answer":"委員ご指摘のとおり、ほこりということでのご指摘もちょうだいいたしましたので、土の舗装、もう一度敷き直しをしました。水まきも週３回、夏場はやっておりますので、少しずつそういうお声も低減されております。引き続き良好な維持管理に努めてまいりたいと思います。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"なかなか区民の方もこの件については喜んでおられると思います。ただ、区民の方からもさまざまな要望という形で寄せられておりまして、例えば目黒区側から西小山駅に入るところ、これが今、階段で手すりが一応つけられているんですけれども、これはやはり、お子様をお持ちのお母様方ですとか、高齢の方から何とかバリアフリーにしてもらえないか。一言お願いします。","respondent":"齋藤道路公園課長","answer":"植え込みが見えないところにつきましては、おそらく近隣の方がプライバシーの関係で塀のようなものをつけてくださいというようなご要望があっての対応だと思いますが、今後その点につきましても、地域の皆さんのお声を聞きながら、よりよい方向に改善してまいりたいと思います。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"これまで区営住宅の増設の要望に対して、品川区は２万戸を超えるストックがあるということを理由に拒否をしてきましたけれども、平成２１年度から住情報センターを創設するための調査委託費が拠出されています。それからもう１点、区営住宅に入居申し込みができる収入基準、この辺、変更になって、平成２１年度から２０万円から１５万８,０００円ですか、引き下げられた。","respondent":"柏原住宅担当課長","answer":"今ありましたように、平成１９年に公営住宅法施行令が改正になりまして、平成２１年度より収入基準が変わったというところでございまして、それに関する影響といいますか、入居者の状況ですけれども、平成２０年度から平成２１年度にかけまして。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"これは全般的に提供するということですから、当然そうした調査というのは、本来平成２１年度で行われていなければならなかったものというふうに私は考えるんです。先ほども言ったように、基本機能として全般的な住情報を提供するということで出されているわけですから、この辺の点についてもう一度答弁願いたいと思います。","respondent":"柏原住宅担当課長","answer":"同じく密集地域につきましても、なかなか建てかえ、住みかえ等が進まないというところがありますので、こちらも区の施策の中心ということで考えながら、まずその住みかえの意向等を調べていこうという中身でやったものでございまして、そういったものを受けまして。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"私も家賃の調査、いろいろ調べてみました。全国平均が今６万４６７円なんだそうです。この年度でね。これは民間の借家の１カ月の家賃、間代の比較になっていましたけれども、東京都が８万５,１１２円。区部になるともっと高くて、９万１４５円なんです。それからもう１点、先ほどの申込者の話は、当然月収、引き下げられましたから、応募できる人たちというのは人数的に少なくなっている。","respondent":"柏原住宅担当課長","answer":"そういったところを総合的に考えてやっていくというのが住宅施策だと思いますので、引き続き住情報の検討なども含めながら、そういったところは考えていきたいと思ってあります。それから区営住宅の保証人の関係です。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"前段ですけれども、聞いていることにあまり答えていない。民間の動きが大きいとか何とか。こういう現状ですから、先ほどの答弁では全然わからないですよ。現状に対する認識、もう少し伺いたいと思います。それから、連帯保証人についてですけれども、都営住宅の場合には、どうしても立てられないという場合には、連絡員を設定する、こういうことで済むそうですけれども、この辺の違いを説明していただきたい。","respondent":"柏原住宅担当課長","answer":"区営住宅の保証人の方の所得の制限ですが、連帯保証人の資格としましては、国内に居住している方で、年間所得、所得金額ですけれども、１２４万８,０００円以上ということになってあります。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"最後のところなんですけれども、私、都との違いというのがどうしてそういうふうにあるのかというのをお聞きしたので、その辺答えていただきたいんです。保証会社を使ってください。本当に冷たい答弁だと思うんですね。都との違いのところの説明をお願いします。","respondent":"柏原住宅担当課長","answer":"東京都との違いですけれども、ご案内のように、区営住宅はほとんどが東京都から移管をされて、区で、今、運営をしているというものです。区の判断としまして、債務をなくしていくとか、そういった観点もありますので、都と違った形でやらせていただいているです。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"ここは関連してエスコートゾーンについてお伺いさせていただきたいと思います。１６９ページに載っています五反田にぎわいゾーン整備方針について、まずこれ、どのような結果が出たのか教えていただきたいのと、五反田駅にぎわいゾーン整備方針の中に五反田駅周辺の放置自転車対策、自転車の駐輪場の整備が盛り込まれているのかどうか、まず教えてください。よろしくお願いします。","respondent":"藤木交通安全担当課長、三宅都市開発課長","answer":"地下の駐輪場の整備は果たして可能かですけれども、地中の埋設物など、少し確認いたしましたところ、確かに電気等、水道等の埋設物はありますけれども、物理的につくれないかどうかということでしたら、つくれないことはない。１点目ですけれども、こちらは市街地整備基本方針におきまして、北側は山手線、西側は首都高速の目黒線、東は中原街道ですとかゆうぽうとを含めたあたり、この辺はにぎわいゾーンと位置づけられておりまして。","id":"exchange-019"},{"speaker":"石田委員","kind":"質問・要望","question":"そんな中で、空き店舗の活用のご検討はいかがかということをまず聞かせていただきたいのと、撤去数３,７９８台、減少しているということなんですが、成果報告書の４３ページに具体的な全体の撤去数が出ています。そんな中で、返還を引いた約１万台の中で９,３７３台処分されている。１,０１９台が再生利用されている。これは要望で終わります。では、まずそこをちょっと教えてください。","respondent":"藤木交通安全担当課長","answer":"しかしながら、そう申しましても、それがまだ、いつのことになるやら、明確なところがございませんので、とりあえずその間、暫定的に道路空間などを利用した自転車の駐輪場の増設ができないかなど、その辺を検討してまいりたいと考えております。続きまして、空き店舗の関係です。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。次に、１６３ページ、視覚障害者誘導ブロックについて、その関連で、エスコートゾーンについてお伺いします。エスコートゾーン、現在品川区内において何カ所設置をされているのか。このエスコートゾーンが音響つきの信号機とセットになって設置をされているのかどうか、そこをまずお聞かせください。","respondent":"藤木交通安全担当課長","answer":"エスコートゾーンの関係です。現在区内に設置されてありますのは、区役所の本庁舎の前、第２庁舎の前の２カ所だけです。","id":"exchange-021"},{"speaker":"石田委員","kind":"質問・要望","question":"ほかの地域で実際にエスコートゾーン、音響つきの信号機がついてないところにあるところ、皆様も目をつぶって歩いてみたらどれだけ怖いかというのがわかると思うんですが、せっかくいいことをしているのに逆に危険を招いてしまうという可能性がありますので、ぜひここは、このエスコートゾーン。","respondent":"藤木交通安全担当課長","answer":"それからもう１点、エスコートゾーンの設置の計画ですけれども、現在のところ特に具体的な箇所はございませんけれども、いろいろと視覚障害者の方ですとか、一方でまた突起があると歩きづらいというような声も一部来ているようですので、その辺を総合的に勘案しまして。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問・要望","question":"黄色の点字ブロックが町中にありますが、道路を挟んでつくられているというのは一つもないわけで、なぜかと言えば、道路を横断するときに音がないとやっぱり危ないということで、結局それは道路を横断されていないという中で、ぜひ音響つきの信号機との連携をしていただきたいと要望します。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"それから１６８ページ、公園管理費、同じく公園新設改良費。ちょっと順序が逆ですが、１６８ページの公園新設改良費で、工事説明会のことをちょっとお尋ねします。ただ、予備知識はありませんし、また昨今の世の中の情勢で、あらかじめ行政への不信感を持って登場することもありますので、説明会での対応といいますか、研修といいますか、どのような対応をとられていらっしゃるのでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"このようなことから、説明会の資料のつくり方ですとか、説明の仕方などの向上を図るために、説明会の前に、管理職、また職務と直接かかわらない職員も入りまして、事前にリハーサルを行うほか、説明会の当日には、出席者のご了解を得て説明会の状況をビデオ撮影し。","id":"exchange-024"},{"speaker":"高橋委員","kind":"質問","question":"今後もよろしくお願いします。次に、駅周辺等放置自転車ですが、大井水神公園駐輪場なんですが、すぐに７時半ごろ満車になってしまう。点字ブロックのところに放置自転車があるなどありまして、稼働率というか、利用状況と今後の予定をお伺いします。それから、立会川の浄化については、平成２１年、平成２２年の施策の成果を踏まえて、今後どのような形で進められていくのでしょうか。坂道になっております。","respondent":"藤木交通安全担当課長、藤田水とみどりの課長、山崎マスタープラン担当課長、齋藤道路公園課長","answer":"こちらにつきましても、今後引き続き民間事業者への働きかけとあわせまして、いろいろな道路空間等を利用した駐輪場の設置が可能かどうか、現在調査。立会川の浄化の関係ですが、立会川の浄化については、平成１９年度にまず実験を行いまして、平成２０年から効果があったということで。区では平成１９年度に改定の品川区すべての人にやさしいまちづくり推進計画に基づく公共施設等におけるユニバーサルデザインの推進を検討する中で。公園の状況を見ながら、自転車走行については強く指導してまいります。","id":"exchange-025"},{"speaker":"高橋委員","kind":"質問・要望","question":"立会川については、今のお話、全体的な大きな流れの中で今後、時間かかりますけれども、きれいになっていくと思うのですが、平成２３年度もこの浄化については引き続き実施されていくのでしょうかということをお尋ねします。エレベーターについては、ぜひ前向きに検討していただきたいと思います。それから、自転車の件については、いろいろありがとうあります。よろしくお願いします。","respondent":"藤木交通安全担当課長、藤田水とみどりの課長","answer":"こちらにつきましては、今後利用状況と、大体駅から遠くなるに従って設置はしたけど、利用いただけないような傾向にありますので、その辺を踏まえまして、いろいろ関係先と検討はしていきたいと考えています。立会川の浄化の関係ですが、平成２０年から５カ年のリース契約で行っておりますので、平成２４年までは高濃度酸素溶解水で行っていきたいと考えています。","id":"exchange-026"},{"speaker":"高橋委員","kind":"質問・要望","question":"これは要望なんですが、鮫洲運動公園、運動場と隣の遊具があるところの工事が、遊具についてはもう始まっています。運動公園については１１月から始まるんですが、３月までということなので、地域の方々は、公園も運動場も非常に楽しみにしておりますので、その工期どおりにぜひすばらしい公園にしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は１６４ページの２項道路橋梁費の中の道路維持費の街路樹等維持管理費について、あと１６６ページの３項河川費の中、こちらは目黒川と運河の水辺の活用、水質改善についてお伺いをしたいと思います。１６７ページ、水辺景観助成事業についてお伺いをいたします。の１件は看板の撤去がされるかどうかのまず確認をさせていただきたいと思います。","respondent":"井浦土木管理課長、藤田水とみどりの課長","answer":"景観についての助成のお尋ねにお答えいたします。この助成につきましては、屋外広告物法、あるいは東京都景観計画に基づきまして、東京都が水辺景観地区に指定した段階で既存不適格になっている屋外広告物について撤去する。その中でさまざまな観光等に使える資源があるのではないかということで、実態等を把握してきたわけですが、今後、既にあります観光アクションプラン、こういったものとの連携を図りながら、みどりと水辺の行動計画をつくる中で。","id":"exchange-028"},{"speaker":"井桁委員","kind":"質問・要望","question":"観光アクションプランで、各課と商業・観光課と連携ということなんですけれども、水辺というと、運河のあたりであったりとか、利用については、よく利用したいができないというのは、都との関係が、港湾局との関係があると思うんですけれども、そこのあたり、強い働きかけを私たちもやっていきたいと思いますし、ぜひ区からも、水辺がもっと、今まで活用がなかなかされないというのは。","respondent":"藤田水とみどりの課長","answer":"運河ルネサンスの地域等に指定をされれば、そういった面でもかなり規制が緩和されることになりますので、そういったことも活用していきたいと考えています。それから、運河等のにおいの関係ですが、今年度港湾局が勝島運河で水質浄化の実験を開始しています。","id":"exchange-029"},{"speaker":"井桁委員","kind":"質問・要望","question":"そのあたり、ぜひ強化に努めていただきたいと考えています。そこでもう１件、浄化についてなんですけれども、先ほど勝島のポンプの工事がされて、全体的になされていくとあったんですけれども、川と違って運河というのは流れが少ない。そして、連携をしてやっていくということなんですが、そのあたりでの都からの助成があるのかどうか。その２点をお伺いしたいと思います。","respondent":"藤田水とみどりの課長","answer":"これについては、このときにあわせて、区も水質の状態がどうであるかということを立会川ともあわせて調査をしていきたいということで連携を図っていく、こういう考えです。","id":"exchange-030"},{"speaker":"井桁委員","kind":"質問","question":"次の項目の１６４ページの道路橋梁費の中の街路樹等維持管理費についてお伺いいたします。木の本数なんですけれども、２,９１９本とあるんですが、これというのは、ちょっと素朴な疑問で申しわけないんですが、区道の木のみの本数なんでしょうか。それとも、区にある木という意味で見ているのか。","respondent":"齋藤道路公園課長","answer":"街路樹は区道の約２割ぐらいにありまして、総本数は３,９５０本ぐらいあります。ここに載っておりますのは、そのうち剪定をした木の数です。２年に１回、３年に１回剪定すればいい木もありますので、この決算書に載っておりますのは、剪定した木の数です。","id":"exchange-031"},{"speaker":"井桁委員","kind":"質問","question":"区道にあるのは３,９００本ちょっとということですね。そのことについてお伺いをしたかったんですけれども、では、区にある、個人が所有をしていて、仮に区道の近くに家があり、そこに落ち葉とかが落ちた際は、区が処分するのではなく、個人が落ち葉をはいたりしているということになりますよね。その２点、お伺いしたいと思います。","respondent":"齋藤道路公園課長","answer":"その他のところは、地域の皆さんが清掃していただいて、地域の皆さんに片づけていただいているです。民間と区の街路樹の処理ですけれども、枯れ木は一般ごみになりますので、廃棄された方がご自分で処理される。これが原則だと考えています。","id":"exchange-032"},{"speaker":"井桁委員","kind":"質問","question":"落ち葉というのは１年中出てくるものだとは思うんですけれども、特にピークというものがあると思うんですね。そういったときに、これはお聞きしたいんですけれども、剪定の維持管理費の中に落ち葉のごみというのも出てくると思うんですが、それは区の事業系のごみになるんでしょうか。それとも、どう言ったらいいんでしょうか、ただで処分をしているのか、そのあたりをお伺いしたいと思います。","respondent":"齋藤道路公園課長","answer":"落ちたものは、もうごみですので、清掃工場のところに分別する場所があります。瓶、缶は資源化センターへ、落ち葉は清掃工場にお金を払って持ち込んでおります。民間の木は民間でお願いしたいというのが私の立場です。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"１６２ページの運転免許返納によるエコライフ支援について、またその下の駅周辺等放置自転車対策費について、そして１６３ページの自転車走行レーンカラー舗装についてと、時間があれば１６８ページの仮称鮫洲入江埋立公園整備基本設計についてお話を伺いたいと思います。返納された年代別というんでしょうか、何歳ぐらいの方たちに多いのか、その辺も教えていただきたい。","respondent":"藤木交通安全担当課長","answer":"エコライフの件数です。こちらは、平成２１年度中、５５２人の方に支援させていただきました。当初予算を組んだときは３００人ぐらいと私ども考えておりましたので、それを大幅に上回る方から申請をいただいたです。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"駅周辺等の放置自転車対策についてお伺いさせていただきたいと思います。実際問題、放置自転車については、置くところも少ないということもあって、仕方なく放置してしまうのかなという考えがあるんですが、実際、駅周辺等の自転車対策というんでしょうか、その辺をどのように考えていらっしゃるのか教えていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"今後につきましても、引き続き、そのような形で考えてありますので、指導啓発活動、撤去活動、それから駐輪場の整備、３本柱で検討してまいりたいと考えております。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"次の１６３ページの自転車走行レーンカラー舗装についてお伺いいたします。実際、スタートいたしまして、利用状況を教えていただきたいということと、あっては困るんですが、これまで、そういう走行レーンで事故などはなかったでしょうか。その辺も教えていただきたいというのと、また今後は、こちらの走行レーンですが、ほかにも予定をしているところがあれば教えていただきたいと思います。","respondent":"齋藤道路公園課長","answer":"段差の歩道があるとか、自転車の走行が１日当たり７００台を超えるだとか、そういうことでございまして、現時点で設置可能、整備可能な場所はございませんので、補助２０５号線を整備した後、補助２０５号線で整備すれば、並走して走っていますので。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても、自転車は意外と大変危険な武器にもなりますので、その辺もぜひいろいろ考えていただきたいと思います。では、最後に１６８ページの仮称鮫洲入江埋立公園整備基本設計についてお伺いさせていただきたいと思います。何度か地元の方たちに対して説明会を開催していただいたと思いますが、今までの状況、また、これからどのような展望があるのか、教えていただきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"公園内での犬の散歩の利用についても課題はあります。これらの課題を整理いたしまして、平成２４年、年明けになりますけれども、また新たに第４回目の説明会を行い、今後、整備のあり方、あるいは管理のあり方についても意見交換したいと考えているところであります。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"１７０ページの密集住宅市街地整備促進事業、都市防災不燃化促進事業、１７１ページの耐震シェルター等設置助成についてお伺いしますが、まず、密集地区防災不燃化促進地区で、整備した防災広場の名称と数と用地取得費について、できれば５年間ぐらい、わからなければ３年分ぐらいでいいんですけれども教えてください。","respondent":"品川防災整備担当課長","answer":"この部分と、それから、中延三丁目に防災広場用地、これも今開発中です。それから、シェルターですが、シェルターの開発費は約７００万円ぐらいかかっています。実績ですが、平成２１年度に１件、設置をしています。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"しているのであるならば、どういう結果を持っているのか教えていただきたいのと、用地取得費についてお伺いをして、さっき答弁漏れがあるのでしていただきたいんですけれども、これ、投資対効果といいますか、こうやって税金を投入しているわけですから、はっきりこの辺は説明をしなければいけないと思うんですけれども、防災活動広場を何メートルメッシュで、何カ所整備するのか。","respondent":"品川防災整備担当課長","answer":"非常に好評ではあるのですが、具体的にどのようにシェルターをやっていくかという点、まだ件数が１件ということで、もう少し件数が増えれば、区内の中小企業者ですとか、そういう方に設計方法を提供してやっていくということは考えてあります。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこを明確に説明してくださいと言ったのですから、具体的に何カ所、どこに防災広場をつくる計画があるのか。幾ら用地取得費をかけるのか。それで、どのぐらいの数で目標を達成したと区としては考えるのかということを教えていただきたいのと、シェルターなんですけれども、この件は結構アピールしていますよね。していると思いますよ。何か統一性がないように思えるんですけれどもその辺はいかがでしょうか。","respondent":"品川防災整備担当課長","answer":"例えば旗の台・中延地区ですが、こちらは、全体事業費として３７億円を考えてあります。その中で、現在執行しておりますのが約１１億円程度というような形で、公園についても、例えば公園の用地取得として全体の計画としては２,３７８m2ということで考えてあります。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"ただ、アンケートをとると、やっぱり耐震の助成という形で必ず出てくるわけなんですから、その辺を今度施策を考えるときに頭にちゃんと入れといてください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"稲川委員","kind":"質問","question":"成果報告書１６３ページ、交通安全施設費の安全施設維持管理と安全施設整備について、これはカーブミラーについてと、先ほども山元委員からありました立会通りの道路の自転車の走行レーンについて、１６５ページは、踏切改良事業に関連して、これは簡単で構わないので、荏原町踏切についてどのような取り組みをこれからしていくか、１７１ページが環境共生住宅助成について。","respondent":"齋藤道路公園課長","answer":"カーブミラーの数ですが、現在２,００８カ所あります。管理の方法ですが、毎日２人ずつ、４班体制で３４８kmの区内を回っていますので、１カ月に１回は必ずカーブミラーの点検をしております。カーブミラーの補修ですが、平成２１年度は６２カ所直しております。","id":"exchange-042"},{"speaker":"稲川委員","kind":"質問","question":"何千カ所という数を回っているのはわかるんですけれども、最初の１カ所を回ったときに、次にまたそこに戻ってくるまでに結構時間かかるんじゃないかなと思います。６２カ所、調整というか、補修をしたということなんですが、これは実際、区の回っている方が見つけて補修をされたのか、それとも区民の皆様が、ここ曲がっていますよという、通報で連絡が来たのか、その辺、教えてください。","respondent":"齋藤道路公園課長","answer":"６２カ所と申しましたのは、工事がかかわるものでございまして、ただ動かしていいというものについても、ほかにも幾つかあって、その数はちょっとわかりません。","id":"exchange-043"},{"speaker":"稲川委員","kind":"質問・要望","question":"それがだんだん時がたつにつれて、ブルーの色が色あせていっているというか、汚くなっているというか、そういうのがまず１点あります。それを今後どういう形で補修をしていくのか、引き直すのか、わかりませんが、その辺を１点お伺いしたいことと、今年の夏大変暑くて、西大井公園広場ですかね、あの横、路上駐車、日陰になっていて涼しいから、やっぱり路上駐車をしていたんですよね。お願いします。","respondent":"齋藤道路公園課長","answer":"路上駐車につきましては、大井署、荏原署の方が特に気を使っていただいて、特に西大井公園のところは路上駐車が多いので、かなり回っていただいております。自転車走行レーンの問題というのは路上駐車対策ですので、引き続き区でも取り組んでまいります。","id":"exchange-044"},{"speaker":"稲川委員","kind":"質問","question":"運転をしている方のモラルもあると思いますので、そういうところも含めてよろしくお願いします。ちょっと踏切改良は飛ばします。１７１ページの環境共生住宅助成について。これは２４件と書いてあるんですが、２４件の詳細を教えてください。省エネルギー型設備設置工事、遮熱性塗装工事、シックハウス対策工事と３点あると思うんですが、その内訳をお願いします。","respondent":"柏原住宅担当課長","answer":"環境共生住宅事業の詳細です。省エネルギー型設備設置工事が２２件、それから遮熱性塗装工事が２件、以上２４件です。","id":"exchange-045"},{"speaker":"稲川委員","kind":"質問","question":"それで、遮熱性が２件で、シックハウスにおいてはゼロ件ということなので、全体を見たときに、助成制度があまりバランスよくないのではないかなと感じます。この間、私も一般質問でお伺いをしたんですが、ぜひ省エネルギー型の設備ですか、それと遮熱性などを切り離して助成制度を創設したほうがいいのではないかなと思うんですが、その辺、お伺いします。","respondent":"柏原住宅担当課長","answer":"平成２２年度、委員からのご指摘もあったところでございまして、分けるか、どうするかというところは、内部でも検討したんですけれども、予算の枠が結構大きくとれたというところもございましたので、分けてとってしまいますと。","id":"exchange-046"},{"speaker":"稲川委員","kind":"質問・要望","question":"助成率というか、バランスいい助成率になるように努力をしていただきたいと思います。次に、密集市街地整備についての手法です。今年度の予算特別委員会の総括質問で質問させていただきました。今回リバースモーゲージについて品川区としてはどうお考えなのか。これをもし品川区に当てはめたとき、どんなメリットがあって、どんなリスクがあるのかを教えてください。","respondent":"品川防災整備担当課長","answer":"この中で、密集事業として部屋を一応約１０戸、枠としていただいてあります。ここに住ませる１つの方法としまして、現在密集地域に住んでいる高齢者の方の土地とか建物とか、そういったものを売却しまして、その中からここの家賃に充ててもらうというようなことを今検討中です。","id":"exchange-047"},{"speaker":"稲川委員","kind":"質問・要望","question":"これは、武蔵野市などは今もやっているんでしょうか。バブルのときにちょっとおかしくなってしまって、不良債権を抱えてしまったなんていう話も聞いているんですが、それはいいとして、もちろんさっきおっしゃっていました住みかえ用の高齢者優良賃貸住宅をハード面としてつくっていくことも、住みかえ用ですから、本当に大切だと思います。これは品川区、積極的に今行っております。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"宮崎委員","kind":"質問","question":"そこを調べているかどうか伺いたい。例えば木造住宅ですと、当時の３年前の説明では、耐震性がないと診断を受けて、言われているところが木造住宅の場合１万７,８２８、非木造で２,９５７、またマンションでは７２２棟あると言われていますけれども、この３年間での動きはどうだったのかということを伺いたい。２０１５年までの関係で、今のペースはどうなのかということを伺いたいと思います。","respondent":"品川防災整備担当課長","answer":"平成２０年は１０棟、平成２１年が１５棟、平成２２年が１０棟となっています。９０％目標に関しましては、現在こういう状況ですので、今後またいろいろ検討して、制度改正等も考えながら見直していきたいと考えています。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、建て替えのところも何件かありました。そこのところ、どういうふうに見ているのかということと、９０％目標を達成していくには、建て替えはやっぱりやってもらうんだけど、残りの支援が必要なところはどのくらい、これを毎年どのくらいでやっていかなきゃいけないのか。そういうペースがわかっているのか。わかっていたら教えていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"今後の支援ですが、現行、耐震診断、それから耐震改修等、今あるメニューをいろいろ啓発活動を含めながら進めていきたいと考えています。それから９０％までに達成する計画ですが、今のところは、大きく数字を考えてございません。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"やっぱり自力では建て替えできない、自力で耐震化できないというところ、これがどういうふうになっているのかということなんですね。やっぱりそのところが問題だと思うんですよ。そこのところ、改めて伺いたいということと、あと、今回の調査のところでは、耐震診断をして、設計したんですよね。そこの関係が、先日の発表のところではよく見えないんですけれども、どうなんでしょうか。","respondent":"品川防災整備担当課長","answer":"耐震シェルター、１件当たりについて３０万円の助成。品川シェルターにつきましては５０万円の助成を考えてあります。自力でできない方については、シェルター等も検討材料としてはあると考えています。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、平均が３４５万円ということですと、いろいろ価格帯というのはあると思うんですね。ここのところは要望して、何か見解があればいただきたいと思います。そうすると、耐震改修、こっちのほうも、区内業者利用の場合には、上乗せするだとか、せっかくですから、仕事づくりという観点からも必要だと思うんですけれども、そこら辺のお考えというのはどうなんでしょうか。","respondent":"品川防災整備担当課長、柏原住宅担当課長","answer":"それから耐震診断すらされない方についての対策ですが、我々も民生委員協議会等に参加しまして、その中で今後耐震の制度の宣伝ですとか、またはまちづくり協議会等を利用しまして、耐震化の説明を考えてあります。住宅リフォーム助成のお話もございましたが、住宅リフォーム助成、平成２２年度行わせていただいておりますけれども、耐震改修の場合は、通常の一般助成の場合は５％を限度としておりますけれども。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それは知っているんですけどね。やっぱり評点１.０だけじゃなくて、例えば自分の持ち金だと０.８まで行くよとか、０.９まで行くよとか、そういうことがあれば、本人の資金力といいますか、力に合わせた支援。例えばそれだと避難路を確保するにはこのぐらいまでできるだとか、あるいは、そのお金だったら命までやれるよ、そういう細かい支援の内容も求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"武内委員","kind":"質問・要望","question":"私は３点、１６２ページの地籍調査事業、１６５ページの立会川緑道整備調査設計委託、１７０ページの密集住宅市街地整備促進事業、この３点、お伺いします。本格整備がまだされてないですね。やっぱり地域の方からは、まだ都の土地だからだれも入れない、広い土地があるのにどうなっているんだろうという声が聞こえているんですけれども、都との交渉の状況ですか、その辺についてお伺いします。","respondent":"井浦土木管理課長、藤橋都市整備下水道課長、品川防災整備担当課長","answer":"残りは１９０万m2ということで、毎年これまでのペースで進めていきますと、今後１０年間、計画終了年次には目標値達成の見込みであると考えています。今年度、１２月１日から現場の工事を行う予定で準備を進めておりまして、既存の二葉公園と新たに取得した用地を一体的に整備する予定で。密集事業で行っている３つの公園用地ですが、１つ目は、ＪＴ跡地の北側ということで、先ほど都市整備下水道課長から説明があったとおりです。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。これは要望します。それから、もしその場合には、地域の方は広場としてできてよかったなと思っている中で、場合によってはそうなったときに、ちょっと残念なのかなという方もいるかもしれないので、その辺をうまくしっかり丁寧にやっていただきたいんですけれども、そこについてお伺いします。","respondent":"藤橋都市整備下水道課長、品川防災整備担当課長","answer":"立会道路の歩道部の横断勾配につきましては、現状１１％ほどありますが、これについては地先の高さとも調整し、勾配を改善する計画で進めているところです。南側の跡地につきましては、今後も用地取得等、ほかの三丁目の地区で公園の用地がないかということも検討しながら、代替地の可能性があるかどうかも検討してまいりたいと思います。","id":"exchange-055"},{"speaker":"原委員","kind":"質問・要望","question":"私は成果報告書で１６２ページ、撤去返還委託等ですね、これが約８,４００万円、これの委託等の「等」の部分についてお答えいただきたいです。それから、１６７ページ、品川区景観計画策定業務委託、７２０万円の委託、これを一言いただきたいのと、それから１６９ページ、五反田にぎわいゾーン整備方針策定業務委託、これが２,０００万円、これについても一言いただければと思います。","respondent":"藤木交通安全担当課長、藤田水とみどりの課長、三宅都市開発課長、柏原住宅担当課長","answer":"こちらにつきましては、放置自転車の管理システムのサポート費用ですとか、保管所につきまして、公租公課分の負担。私からは７２０万円、品川区景観計画策定業務委託についてお答えいたします。こちらの地域につきまして、平成２０年度から、地元の五反田地域まちづくり協議会の皆様とともに内容を検討してきておりまして。こちらは指定管理者に管理委託ということで委託しているものがほとんどでございまして、それ以外につきましては。","id":"exchange-056"},{"speaker":"原委員","kind":"質問","question":"自転車の件はわかりました。それから、景観についても、今一生懸命やっていただいている。それもよくわかりました。しっかりとしたものをつくっていってください。ですから、ここに関しまして、もう少し詳しくお聞きをさせていただければと思います。今後の推移、３年から５年、１０年、その辺をざっくりとお教えいただければと思います。よろしくお願いします。","respondent":"柏原住宅担当課長","answer":"区営住宅の耐震の部分です。耐震の部分につきましても、８団地、耐震改修が必要だというものがございましたので、平成２１年度、１件出ていますが、南大井六丁目区営住宅の実施設計ということで、ここを皮切りに８団地、平成２６年度までに何とか耐震工事を進めていきたいです。","id":"exchange-057"},{"speaker":"原委員","kind":"質問","question":"基本的には、これはお約束ですから、守らなければいけないんですけれども、この契約に関して、まず質問の１点目は、全部の契約が終了するのはいつなのかということと、それから、この契約に関して、解除、解約等、その辺のところはどうなんですか。ペナルティーがあるのか、ないのか。その辺まで教えていただければと思います。","respondent":"柏原住宅担当課長","answer":"２０年間契約ということですので、平成３２年まで、最後の物件は続きます。それから、途中で解約等の場合は、基本的にはできないということになっておりますが、ペナルティー等々については契約書には明記はされておりません。","id":"exchange-058"},{"speaker":"原委員","kind":"質問","question":"そうしますと、どう説明しますかね。ですから、そこの部分と、それからもう１つ、ペナルティーがないということであれば、そこの部分でもう少し、以前から再度個別的にオーナーからは話は聞いて、お願いをしたりしているんだということも聞いております。ただ、聞いているんですけれども、その２点、国、東京都、それから今度は個人オーナー、そこについてのお考えをもう１回お願いいたします。","respondent":"柏原住宅担当課長","answer":"オーナーにつきましては、引き続き、できれば設定家賃を下げていただくのが一番よろしいんですけれども、そういったところもオーナーの資金計画等もございまして、なかなか難しいところがありますので、今回出させていただいた空き家対策というところで進めていきたいです。","id":"exchange-059"},{"speaker":"原委員","kind":"質問","question":"そうしましたら、ちょっと角度を変えて、実際には家賃関係、今度は滞納ですね。ですから今後においては、逆に民間などは、企業内弁護士などというものを入れたりしておりますので、今すぐとは申しませんけれども、区でもその辺の考え方を、３年、５年、１０年先、どうなんだろうというような考えが出てくると思います。それから、先ほど午前中にもありましたけれども、これは今度は入居のほうです。","respondent":"柏原住宅担当課長","answer":"ただ、指定管理者が債権等々回収もしておるんですが、特に公営住宅の関係でいいますと、指定管理者がそういったところまで、要するに債権を買い取るとか、そういったところまではできないという通達も出ておりまして、なかなかちょっと難しい面もあります。","id":"exchange-060"},{"speaker":"原委員","kind":"質問・要望","question":"これは今すぐということではないんですけれども、弁護士の活用方法をもう少しお考えいただければなと思うんです。その次のステップは何かと言えば、今度は、個々の能力を上げていただきたい。先ほど申し上げましたように、区にしても、都にしても、めちゃくちゃなことがいろいろ出てきておりますので、品川区としてのお考えをできましたらば、すみません、上級の理事者の方にご返答いただければと思います。","respondent":"片田防災まちづくり事業部長","answer":"確かに弁護士法等のいろんな法的な制約がありますので、そういう専門家の能力を生かしながら、なおかつ私どもがこれまで培ってきた指定管理者や、そういう関係機関との連携をとって、最大限私どもとしても努力していきたい、このように考えてあります。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"私は１６８ページ、しながわ水族館運営費と、１７１ページ、建築物耐震化支援費についてお聞きしたいと思います。はしながわ水族館運営費ですが、現在日本には約１００カ所の水族館があると言われております。この大規模改修の際には、工事期間中、水族館にいる生き物に対して、移送先や飼育の管理費用も大変であると聞いているんですが、しながわ水族館の状況はどうなんでしょうか。お聞かせください。","respondent":"藤田水とみどりの課長","answer":"しながわ水族館についても、そういったことで３０年近い年数が２０２０年に来るわけなので、現在、来年が２０周年を迎える年ですが、２５周年までにしながわ水族館のあり方を、今後どうあるべきか、これは聖域を設けるのではなく、あり方を一から検討する。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問・要望","question":"どこかに行くときに、すぐ乗れるという形ならば、比較的行かれる方も多いのかな。わかっておりますが、宣伝もそうですが、逆に、交通の便がよければもっと行くのかなという感覚も持っておりますので、その辺を考えていただきたい、どうでしょうかということと、大規模改修の際には、地球環境基金、この３０億円というのは使えるんですか。それとも、これは使えない財源、基金なのでしょうか。","respondent":"藤田水とみどりの課長","answer":"実際に平日、それから休日で、混み具合が違いますので、それに応じた、入館者の数に応じた本数になりますが、そういった中では、交通の便、これは大事だと思っていますので、こういった無料バス等も活用しながら進めていきたいと考えています。","id":"exchange-063"},{"speaker":"須貝委員","kind":"質問・要望","question":"かなりの大規模改修となると、何億円という話じゃなくて、３０億円か４０億円かわからないですが、相当の金額がかってくるかと思うんですね。ぜひその辺はしっかり計画を立てていただいて、本当にいい水族館、よりいい水族館をまた目指して頑張っていただきたいと思います。それに対して、品川区は今後老朽化マンションに対して耐震化支援など、どのようにお考えになっているのか、お聞かせください。","respondent":"品川防災整備担当課長","answer":"しかし、今後の状況とか、それから２３区の動向なんかも踏まえまして、マンションについても少し今回の制度改正では検討していかなければいけないという認識はあります。","id":"exchange-064"},{"speaker":"須貝委員","kind":"意見","question":"民間の場合には、高齢者の住みかえ住宅を区で積極的に支援していますが、私は逆に区も、そういう大型プロジェクトになってしまうのかもしれないですが、そういうマンションを借りるなり、つくるなりして、１回移り住んでいただいて、建て替えるという支援も必要じゃないかなと思いますので、ご検討ください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"市川委員","kind":"確認","question":"駅周辺放置自転車対策なんですけれども、これは先ほどから随分質問がいろいろ出ておりまして、２０１０年の事務事業概要で確認しますと、２００５年から２００９年に、区営、民営合わせて駐輪場の収容台数を１,０４４台増やしたということです。まちの景観上というところでも悪影響を及ぼしているというものです。今後の見通しというところでは、どんなふうに思っていったらいいのか、その辺をお聞きします。","respondent":"藤木交通安全担当課長","answer":"今後につきましても、旗の台地区あたりにも駐輪場を整備するよう、こちらから働きかけておりますので、引き続き協力体制をとっていきたいと考えています。","id":"exchange-066"},{"speaker":"市川委員","kind":"質問・要望","question":"本当にこれだけの税金が毎年出ていくということでは、ぜひ鉄道事業者に対しては申し入れを今後も行っていただきたいと思います。対策ではなくて、政策を品川区としても打ち出して、その中で個々の課題を解決していただきたいなと思うんですけれども、この点について、品川区としてのご見解をお聞きいたします。","respondent":"藤木交通安全担当課長","answer":"総合的な政策ですけれども、現況では、品川区内、非常に狭隘な道路が多いということで、自転車、自動車、歩行者の共存ができないという状況にあるところです。","id":"exchange-067"},{"speaker":"市川委員","kind":"質問・要望","question":"それで、２００８年の第２回定例会で生活者ネットワークが、どうも視覚障害者当事者の設置してほしいという希望と違うところに設置がされているんじゃないですかというようなことを一般質問でさせていただいたんですけれども、そのときに、今回の設置を契機に障害者団体の方や一般の方々から感想を聞いて、今後の拡大に向けて生かしていくという答弁がされたと認識しているんですけれども。","respondent":"齋藤道路公園課長","answer":"例えばガード下で音声誘導装置が聞きづらいところに設置するですとか、こういった基準を示していただいて、今後、地方自治体、交通管理者ではなく道路管理者である私どもで設置の可能性、必要性について検討してまいります。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"設置するのは警察なんですけれども、こういう道路に設置してほしいというのは自治体のほうの考え方が優先されるべきではないかなと思うんですけれども、ちょっとそこのところがよくわからないので、再度答弁をお願いします。","respondent":"山崎マスタープラン担当課長、岩田都市環境事業部長","answer":"そういうことで、区として、道路管理者として、それから警察等への要望、連携を図りながら、この件については慎重に対応してまいりたいと考えています。これは品川区がゼロcm段差をやった当時、障害者団体との意見調整に約５年かかりました。そこら辺は十分意見調整を進めてまいります。","id":"exchange-069"},{"speaker":"市川委員","kind":"質問・要望","question":"視覚障害者の方たちは交通量の多い、道幅の広い場所にある横断歩道に自分たちは危険を感じる。そのためのエスコートゾーンだということも言っておりますので、ぜひこの辺は他の障害者団体と視覚障害者団体との調整の中で、エスコートゾーンの拡大については検討していっていただきたいという要望をお願いいたします。それから、１６７ページのしながわお休み石設置事業について伺います。","respondent":"山崎マスタープラン担当課長","answer":"例えば周辺の通っていらっしゃる病院の近くに設置をしてほしいとか、あるいは散歩道、健康づくりの散歩道のコース沿いに設置をしていただきたい等々の要望を受けているものです。","id":"exchange-070"},{"speaker":"市川委員","kind":"質問・要望","question":"５万円で名前を入れてくれるというようなことが規定になっておりますけれども、もっと寄附金額を下げて、名前を入れなくても、休める場所が増えればいいというような、そういう個人もいらっしゃるのではないかなと思いますので、この辺の考え方について区のお考えを伺います。","respondent":"山崎マスタープラン担当課長","answer":"それで、寄附につきましては、現在１口５万円ということで、お休み石１台の設置が約３５万円ということを勘案しますと、７分の１を区民の皆様のご寄附で賄っていただいているということです。７分の１の負担割合が適正かどうか、妥当かどうかということだと思います。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"ぜひ寄附のバリエーションも広げて、お休み石事業が広がるということをよろしくお願いします。では最後に、公園新設改良費から児童遊園の禁煙化と分煙化ということで伺いをいたします。健康増進法では学校や公官庁など、多くの人が集まる施設の管理者に他人がたばこを吸うことによる受動喫煙の防止策を求めています。そもそも児童遊園の目的、位置づけというのは何なのかをお聞きします。","respondent":"齋藤道路公園課長","answer":"公園は今分煙を徹底する方向で事業を進めております。具体的に申し上げますと、２４６の公園のうち３８ぐらいの公園でしか喫煙ができないように灰皿を撤去しております。理由は何かと申しますと、やはりまだ喫煙人口、男性で３８％、女性で１４％いらっしゃいます。","id":"exchange-072"},{"speaker":"山路委員","kind":"提案","question":"２点ほどお伺いします。すずらん通りに向かう富士ガーデンの横、昨日も行ってまいりましたら、２列になってとまっているんですね。この例を引いて、できないでしょうかという提案をさせてもらったら、当時、阪急が改造するので、改造したら阪急にも附置義務が生じるので、その辺を話し合いたいというご答弁をいただいた記憶があるんですけれども、その辺どうなっているかお伺いいたします。","respondent":"藤木交通安全担当課長","answer":"現在のところはそのような計画で進められているものと認識しております。","id":"exchange-073"},{"speaker":"山路委員","kind":"提案","question":"表示の指導啓発はどうぞよろしくお願いいたします。これは要望しておきます。もう水道は直結の時代に入っているのではないかと私は思っておりました。小学校に関しましても、この間、我が党で提案したら、計画的に直結にしていく。こういう区の施設、特に高齢者の方の施設には、水道直結をしていただきたいと思いますが、なぜ受水槽が設けてあるのかお伺いいたします。","respondent":"宍戸施設整備課長","answer":"今委員ご指摘のとおり、直結にしたほうがいろいろ衛生上好ましいということもございまして、直結にできる部分につきましては直結にしているんですが、ここの大井林町住宅につきましては、径が細いということもございまして、やむなく受水槽を設けたというものです。","id":"exchange-074"},{"speaker":"山路委員","kind":"提案","question":"一応説明いただきましたが、径が細いのは幾らでも太くできるんじゃないですか。このように直結していくことが高齢者にやさしい水の配給、また多くの地域の方の小規模多機能とか、看護ステーションとか、今回いろんなものが設置されるわけですから、特に配管については幾らでも大きいものもあると思うんです、改造できると思うんですが、どのようにお考えでしょうか。","respondent":"宍戸施設整備課長","answer":"加圧ポンプ等を使いまして、確かにかなり引き込みの径が細いものも含めて、直結にするというような場合もありますが、引き込み自体がかなり細いということと、それに加えまして、学校などでも受水槽。","id":"exchange-075"},{"speaker":"山路委員","kind":"質問・要望","question":"緊急対策では、水をためていたほうがよろしいかと思うんですけれども、大体全体的には、引っ張ってくる配管を大きくするのも、それと増圧の部品も、いろいろ新製品が開発をされておりますので、その辺を研究して、全体的には直結方式で、そして、防災用には受水槽も設置する。こういうものも含めて検討をしていただきたいと思いますが、もう一度ご答弁をお願いします。","respondent":"宍戸施設整備課長","answer":"もともと、例えば厨房等の水道については直結にしたり、組み合わせとなっています。委員ご指摘の点も踏まえまして、ほかの施設も含めまして、これからいろいろ研究しなから建設を進めたいと考えています。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問・要望","question":"放置自転車はもう随分議論が出ましたので、根本的な解決をずっと考えていくと、例えば鉄道事業者等に駐輪場設置義務の法制度化を国に求めていくとか、身近な自治体、品川区の税金を使って駐輪場を整備していくことももちろんいいんだけれども、際限なく広がっていくわけでありますから、やっぱりそれはどこかで鉄道事業者等の設置義務を法的に求めていったらどうでしょうかという質問が１つ。","respondent":"藤木交通安全担当課長","answer":"ただいま委員ご指摘のとおり、鉄道事業者に自転車駐輪場の附置義務というのがありましたら、非常に駐輪対策も大幅に進むのではないかという認識を持っております。","id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問","question":"これは２３区もそうだけど、どこの自治体でも問題になっているわけじゃないですか。やっぱりさらにもう一歩踏み込んで、例えば２３区と東京都と共同して、国に対して法改正を要求していくとか、さらにこの問題について、いつまでも品川区などに責任を押しつけるのではなく、鉄道事業者等も含めて解決していきたい大都市の問題なんだということの姿勢を考えてはいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"ただいまのご質問に対する回答です。区といたしましても、また自治体でつくっております自転車問題の協議会みたいのもありますので、そちらの場などを活用いたしまして、今後検討してまいりたいと考えています。","id":"exchange-078"},{"speaker":"伊藤委員","kind":"提案","question":"あのね、すいません、検討はいいんですよ。ぜひやってください。そうであるんだから、そこについての費用負担を求めていく姿勢を品川区なり行政なり、大きく言えば東京都は持っていると思いますから、もう一声このことについて、協議する場で例えば提案していくとか、品川区として方向性を出していくとか、具体的な行動を期待しますが、答弁をお願いします。","respondent":"岩田都市環境事業部長","answer":"ＪＲとも今後さまざまな形で協議の場があります。特に直近では、五反田駅の駅ビル計画というのを持っておられますので、今までもやっておりますけれども、こういう中で自主的にＪＲがお客さん用の駐輪場を設置するように、強く要請はしてまいります。","id":"exchange-079"},{"speaker":"伊藤委員","kind":"質問","question":"あれが途中でさびていたり、それから壊れそうになっているのをご存じでしょうか。意外な盲点かもしれませんけれども、万が一そんなことはないと思うのですが、水が途中でとまったり、それから、あふれ出たりしたら大変なことになると思いますから、これはセクションがどこかわかりませんけれども、ＪＲに伝えていったほうがいいのではないでしょうかという指摘ですがいかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"そのことによって何かあっても対応できるようにするというような話はいただいております。そのほかにも、委員ご指摘のように、悪いところがあれば、私どもからＪＲに申し入れ、修理をお願いしていきたいと考えています。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、やっぱり品川区の責任としてやる以上は、そういうプロに学ぶと言ったらいいんでしょうかね、説明の仕方であるとか、それから表現の仕方であるとか、配る資料の内容についての点検であるとか、いろんなところで、特にこういう説明をする場所についてはですよ、一般区民に直接品川区が説明する場所においては、新しい仕組みと。","respondent":"藤橋都市整備下水道課長","answer":"したがいまして、説明会の事前のリハーサル、これは区民の立場になって質問する人、答える人、いろいろ役割を変えて、本年度から実施しているところですけれども、この取り組みを続けるとともに、プレゼンテーションや交渉力強化等の研修も。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、内部の研修はもちろんやっていただきたいんだけれども、外の方々、つまり直接区民の皆様方に向かって説明するときに当たっては、何というかな、外部の講師をお願いするとか、新たな視点でやっていかないと、特にこういうことについては、直接区民に説明する場所においては、知識と経験とノウハウがこれからさらに必要になってくると思いますが、さらにご答弁をお願いいたします。","respondent":"岩田都市環境事業部長","answer":"これは公園だけに限らないんですけれども、品川区は住民参加を昔から非常に大事にしておりまして、約３０年ぐらい前からこういう説明会を品川区ではやっております。現在ではすべての公園の説明会を全部やっております。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問","question":"歳入の款別審査の中で、再開発の補助金投入について、大崎駅西口南地区のように補助金額を増額するというところはほかにあるんですかという質問で、着工済みの計画についてはほかにはないというご答弁だったと思うんですが、例えばここにもありますけれども、一本橋などの大井町西地区再開発など、現在着工中などの計画、これからの計画については、そうした変更。","respondent":"三宅都市開発課長","answer":"目黒駅前地区再開発についてですけれども、今のところ、総事業費は１,０００億円を予定していると聞いております。補助金額の全体につきましては、これは今後の設計などを進める中で出てくるものでして、まだ全体像としては未定です。","id":"exchange-083"},{"speaker":"安藤委員","kind":"質問・要望","question":"西地区のほうは、補助金、当初に比べて増額ということなんですが、これは理由、後で伺いたいと思いますが、ご答弁お願いします。この目黒駅のほうですけれども、税金投入で推進する１４５ｍ級の高層ビル、３本建てる計画でして、近隣住民と幼稚園からは、現行の計画では風害や日照など周辺環境に看過できない悪影響を及ぼすということで、見直しを求める運動が起こっております。","respondent":"三宅都市開発課長","answer":"都の役割ですけれども、これは都の地権者としての役割ということになろうかと思いますけれども、東京都は平成１５年度から都営住宅の建て替えなどによって新たな利用が可能となる都有地を活用して。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところ、すいません、１,０５０％、最大のところあると思っていたんですけれども、それはなぜ１,０５０％じゃないのかというのを後でお伺いします。この権利をどう行使する予定なのかというのを伺いたいと思います。私よく伺いますのは、マンションばっかりつくっても、住民に何の利益もないんじゃないかというよく聞かれる声なんですね。その結果を受けてどうしたのかということですね。","respondent":"三宅都市開発課長","answer":"最後に、請願ですけれども、介護施設につきましては、こちらでは設ける予定はございません。幼稚園、保育園に関しましては、こちらは子育て支援施設を、詳細の計画内容につきましては今後検討していくわけですが、そちらを予定しています。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的に要望されて、区立保育園もわからない。介護施設は１個もない。だったら、何なんですか、これは、となると思うんですね。白紙のままに、まず絵はできちゃうというか、１４５メートル級３本、超高層ビルまず先につくることありきそのものじゃないですか、これは。もうけが１６０億円になるんですね。これ、こんなにもうけるんですけれども、区はこの辺どういうふうに考えておりますか、お伺いします。","respondent":"三宅都市開発課長","answer":"したがいまして、保留床を適切な価格で参加組合員に処分したということが再開発事業にとっての最大の重要なポイントでございまして、区はそれを大切なことだと考えております。","id":"exchange-086"},{"speaker":"堺委員","kind":"確認","question":"私から３点。このような指摘もされているところでございまして、そんな視点からも、戸越幹線の貯留管の工事についても、一日も早い完成を期待をしていたところですが、残念ながら、補正予算の中にも書いてございましたように、途中で出水があって、現在立坑の現状回復工事が行われているですが、この辺の現況はどうなんでしょうか。その辺の見通しも含めて、確認をしておきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"戸越幹線貯留管の整備におきましては、３月１６日に出水事故が発生して以来、原因分析と対策の検討を進めてまいりました。","id":"exchange-087"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１点、この辺については、先般も完成するであろうことを想定して、あの上で、当初あった公園をこういう形で復旧していきますよというような説明会が既に行われているのですが、今回この件について、来年の３月、完成時期にあわせまして、もう１回改めてこの公園についての説明会等が行われるのかどうか、その辺のスケジュール等について、また考え方について確認をしておきたいのですがいかがでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"地域の方々とは公園のいわゆる復旧の絵を描く説明会をやっていたさなかに出水事故が発生しましたので、最終的に公園の絵がどうなるのかということについては、改めて地域の方を踏まえて、説明会を行った上で、整備に入っていきたいと考えております。","id":"exchange-088"},{"speaker":"堺委員","kind":"質問・要望","question":"１６７ページのまちづくり推進事業、これに関連して教えていただきたいんですが、この平成２１年度の予算書の中には、これに関連して３点、まちづくりの動向調査、区民の自主的なまちづくりへの支援、それから地域における総合的なまちづくり推進事業ということで、３項目計上されていたのですが、今回の成果報告書の中では、まちづくりの動向調査。","respondent":"久保田行財政改革担当課長","answer":"実際にはこうした中で、跡地活用等の話につきましては、職員が直接出向いていって、お話をして、町会、地域の方々等、そういった説明等をやった経費の中で、対応してまいりました。","id":"exchange-089"},{"speaker":"堺委員","kind":"質問","question":"そうすると、予算書、それから成果報告書のまちづくり推進事業というと、これは今のお話、荏原平塚中学校跡地の利用に関連してということのみですか。ほかのことは入ってないのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"重点的に跡地利用ということで、当初はいろいろと説明用のチラシとか、そういったものの経費ということで計上させていただいたところですけれども、話を進めていく中で、職員が手づくりの形で対応してきたということで、執行がなかったということです。","id":"exchange-090"},{"speaker":"堺委員","kind":"質問・要望","question":"そうしますと、まちづくりについて、この時点でのとらえ方については教えていただきましたから理解はできたんですが、最近、このまちづくり推進事業に関連をして、平成２２年度の当初予算の中では、具体的に東急大井町線沿線まちづくり調査費７００万円ということで計上されてはおりますが、この時点からいろんな動きがあったんだろうなと思いますけれども、これに関連して。","respondent":"山崎マスタープラン担当課長","answer":"区はこうした活動に対しまして、オブザーバーとして参加をしているほか、活動費の一部を補助する等々の支援をさせていただいているものです。","id":"exchange-091"},{"speaker":"堺委員","kind":"質問","question":"要するに私たちが心配することは、ご存じのとおり、品川区議会としても補助２９号線については廃止ということで、３回でしたかね、やってきた経緯がありまして、一度は関係者が東京都まで行って、補助２９号線を廃止しなければならないんだというぐらいに、地域運動の一環としてやってきた、取り組んできた経緯もありますが、この文書を見ると、その補助２９号線はどうも認めますよ、やってください。","respondent":"山崎マスタープラン担当課長","answer":"区としましては、過去、本区議会におきまして、３度にわたって不採択ということを重く受けとめてはおりますけれども、ここの道路は区としまして、都市交通網としての機能を持つ、そういったこと以外にも、大規模な市街地火災の延焼を防止する延焼遮断帯等々の役割もございまして。","id":"exchange-092"},{"speaker":"川西委員","kind":"質問・要望","question":"カーブミラーについては、私もいろいろ関係者から陳情を受けていまして、その方のご意見によると、１日とか１０日とか、交通安全で道路に立ったりしている方ですから、非常に警察との関係がある方なんですけれども、警察にいろいろ陳情したら、道路管理は区役所だから区のほうにというので、何かよくわかりませんが、電話をしたそうですが、なかなか解決をされなかった。これはお返事は要りません。要望です。","respondent":"藤田水とみどりの課長","answer":"公園は、今ご指摘がありましたとおり、広場型については２０％、遊具中心の公園であれば３０％ということで、基本的にはすべてその基準の中でおさまる形で緑化が進められてあります。","id":"exchange-093"},{"speaker":"川西委員","kind":"質問・要望","question":"第２の質問も含めて行います。これは今年はご覧になったでしょうか。ご答弁の中にありましたように、ハナミズキは輸入もの、これから日本産のものを街路樹に植えていきたいというお話があったかと思いますが、そういう点では、管理点検台帳を区でつくって、毎年点検をしていただきたいと思うのですがいかがでしょうか。そういう点で、バーベキュー施設の今後の区内の公園に広げていくお考えについて伺います。","respondent":"藤田水とみどりの課長、齋藤道路公園課長","answer":"そういった中では、今あるものを適切に管理していくことになろうかなと思います。今後、そういったような道路が出てくる場合については、緑化指導の対象として行っていきたいと考えています。そういうことですので、ある程度の必要数は足りているかなと考えています。ただし、釜をつくりますと、火事の問題や煙の問題もいろいろありますので、どういった場所に設置することが可能かを含めて、検討してまいります。","id":"exchange-094"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひ点検台帳をつくっていただいて、点検していただきたい。南馬場通りについては、ハナミズキを植栽したときから３年ぐらい後、年々元気がなくなっております。こういうのをどう見ていらっしゃるのかと思っています。それから、バーベキューについては、あそこの区民公園の施設が、公園の広さが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"１６３ページの道路維持費の交通安全についてお尋ねをいたしますので、よろしくお願いします。スクールゾーンについてです。道路管理というところから聞かせていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"その後警察や道路公園担当に連絡しまして、交通規制面ですとか、路面表示などをやっているところです。したがいまして、原則として、特に校区の変更等がない場合は、それぞれ要望とか通学実態などを勘案していきますので、時期的なものというのは特に定まりはないところです。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問・要望","question":"今ご答弁の中で、もちろん学校というのは昔からあるものですけれども、学校が既に交通戦争というものが始まる以前からこのスクールゾーンというのはできていたのかどうか、ちょっと確認をさせていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"スクールゾーンというのは、昭和４０年代から始められたものです。交通戦争というのは昭和３０年代ぐらいには子どもの事故、非常に全国的に多発しておりますので、当時はございませんで、その後１０年ぐらい経過してからです。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問・要望","question":"モータリゼーションの幕開けと重複するような形と思いますけれども、そこで昭和４０年代ということで、もう何年でしょうか、かなりの年数がたっていると思います。何か大昔ということでお話出ました。先ほど地域の方、そして学校の関係者の方の要望を受け入れて、警察、教育委員会と調整をするという話を伺いましたけれども、そういう中に、学校周辺を取り巻く環境が変わってきていると思います。","respondent":"藤木交通安全担当課長","answer":"学校現場で対応されているかもしれませんけれども、通学路と申しますと、どうしても交通規制ですとか、そういうものをかけることになりますので、その場合につきましては、正式なそのような手続は踏んでないというのが実情です。","id":"exchange-098"},{"speaker":"大沢委員","kind":"意見","question":"今、課長から歩車道の区別がついている云々という話がありました。４ｍ道路で歩車道の区別がついていない道路近辺の通学路、スクールゾーン、ここで頻繁に道路の車の往来が激しい場合、子どもの安全というのが確保できるのかどうか、率直にお答えください。","respondent":"藤木交通安全担当課長","answer":"現場を確認してみないとわかりませんが、原則として歩車道区別があるのが望ましいというところですけれども、歩車道がないところにつきましては、それなりの事故の危険はないかといったら皆無ではないと考えます。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこで、今対処されているというところ、それと、先ほどもお話をしましたように、あくまでもこの時間帯、いわゆる子どもたちの登下校の時間帯というのは、遠路から車が来るのではなくて、先ほどの工事車両もそうですけれども、あくまでも近辺に生活をされている方がそこを往来する部分があると思うんですが、ここのあたりで道路管理する上で建築課とどのように連携をとられて、そこら辺の整理。","respondent":"岩田都市環境事業部長","answer":"スクールゾーン、あるいは通学路の時間規制につきましては、これは東京都公安委員会の法律による規制になりますので、何人たりともその時間帯は車両は通行できないことになっております。","id":"exchange-100"},{"speaker":"大沢委員","kind":"意見","question":"子どもの安全を確保するべくぜひとも取り組みをお願いします。予測不可能な場合もあると思いますが、そこら辺のところ、よく周辺の方、学校の方と、また近隣の生活者の方とよく意思の疎通をしていただいて、子どもの安全が図られるようにぜひともよろしくお願いいたします。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"西本委員","kind":"確認","question":"２つほどお聞きしたいと思います。１７０ページになるんでしょうか、避難道路機能強化事業で、滝王子通りの件について、それから、１６８ページの公園管理費、公園新設改良費についてお聞きします。特に滝王子通りというのは、商店街通りになっておりますので、それがどういう形とどういう方向性で今なっているのかをまず確認したいと思います。","respondent":"品川防災整備担当課長、藤田水とみどりの課長","answer":"今後、地区計画、現在１０ｍ離れて、家を建ててくださいという地区計画はあるんですが、もう少し地区計画を拡大しまして、滝王子通り、どういう方向で活性化をしていくのか。公園設置のトータル的な考え方ということなので、私からお答えいたします。都市公園ですけれども、基本的には都市公園法の中で、半径２５０ｍの中に１カ所、２,５００m2程度の公園を設けるというまず大きな基準があります。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"実際に該当する町会の方たちと話をすると、まちづくり協議会ですかね、その中にもあまり参加されていないような雰囲気を聞いておりますし、強制力はそんなにないわけですよね。そうすると、建て替えのときによろしくねという程度ですから、いずれは自分たち、いるかどうかわからないしね、なんていう状況で、実際に強化するという中でも、一体何年かかるのかという状況にあろうかと思います。","respondent":"品川防災整備担当課長、岩田都市環境事業部長","answer":"地域の皆さんに、この地域は避難道路となって危険だよという認識を我々が伝えながら、その認識を理解したもとに道路を拡幅していかなければいけないと考えております。品川区では２例目です。中延地区の密集事業で道路拡幅の地区計画をかけております。したがって、そこの沿道の方は、将来建て直しのときには、下がらないと建築確認がおりないという法規制がかかります。","id":"exchange-103"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６３ページの道路維持費で、先ほどもありましたスクールゾーンについて伺います。１６２ページ、規制・許可事務費の屋外広告物取締事務の中で伺っていきますが、スクールゾーン、１つまずお伺いしたい件がありますので、先にお答えいただきたいと思います。そのときに、当然スクールゾーンですから、道は通れないわけです。区民の方に広くそれを伝えてほしいと思うんですがいかがですか。","respondent":"藤木交通安全担当課長","answer":"今後ホームページなり何なりで活用できるか、もしくは警察で何らかの広報をするか、いずれにしろ、警察と連携とりまして、何らかの広報をさせていただきたいと思います。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問・要望","question":"スクールゾーンの質問、続けます。やはり１つのまちでスクールゾーンの時間帯が２つあるというのもおかしな話だと思うんですけれど、まず実際にその時間がずれているようなケースがあるのかどうなのかというのを教えてほしいのと、例えばずれているところをこれから何とか７時半から８時半という時間帯にすべて合わせていこうという努力をされているのかどうかというところを教えてください。","respondent":"藤木交通安全担当課長","answer":"ほかの地域につきましては、お買物の対象としまして、商店街なんかは午後の夕方の時間帯とかを通行止めにしているようなところはありますけれども、朝方というのは大体通学路とこちらの中延の８時から９時だけだと聞いております。","id":"exchange-105"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。確かに駅の乗りかえ口の部分で、どういう事情があってなのかなというのもあったんですが、８時、９時は、これはしようがないのかな。子どもの安全に対してスクールゾーンという決まりがある中で、実際のところ、車が走っていますよということを言い続けていらっしゃるのかどうなのか。それを何とかしてほしいという認識があるのかどうか、お答えを欲しいんですがよろしいでしょうか。","respondent":"市川教育次長","answer":"教育委員会といたしまして、今お尋ねのような情報なり要請が学校からまいりましたらば、区役所の担当部署と連携して、子どもの安全確保に向けての取り組みをすること、これは当然のことと考えております。","id":"exchange-106"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。本当にゾーンになっています。地域を挙げて頑張っている中で、やはり心ない運転手といいますか、その時間に、やむを得ずなのかもしれないんですが、そのように車の通行があるわけですから、何とかさまざまな尽くせる手は尽くして、何とかその時間帯、車はなるべく入らないようにしようという努力をしていっていただきたいと思います。","respondent":"井浦土木管理課長","answer":"これについて、不適看板についての指導、それから、適合するけれども許可が出てないものについての許可申請の催促といいますか、連絡ということについて、現在、今年の８月以降、事務的に進めているところです。","id":"exchange-107"},{"speaker":"渡部委員","kind":"質問","question":"緊急総合経済対策の一環ということですので、相当な人手がかかったのかなと思います。額がでかいのであれなんですが、延べ何人ぐらいの方がそれに当たったかだけ最後教えていただけますか。","respondent":"井浦土木管理課長","answer":"お答えいたします。この件につきましては、データといいますか、電子データで専用システム……。","id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"１６７ページの雨水浸透施設設置促進事業についてお伺いいたします。この事業の目的をお聞かせいただきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"地下水の涵養という観点からも、雨水浸透を促進しているものです。さらに、下水道への負荷を低減することで、下水道から河川に越流する水を減らす効果もありますので、いわゆる水質の改善に寄与するという３つの効果があるという形で事業を促進しているものです。","id":"exchange-109"},{"speaker":"若林委員","kind":"確認","question":"これは確認ですが、促進事業の中に、いわゆる雨水流出抑制の指導、それから雨水浸透施設設置助成事業、それから平成２１年の予算で、区有施設の整備の検討、こういう３つが含まれていると思うんですが、間違いなければ、その確認と、それぞれどのような事業であるのか。できれば事業費についても説明いただきながら、解説をお願いしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"区有施設の整備につきましては、これは目黒川流域の豪雨対策計画が東京都で発表されたことを受け、区内において雨水の貯留浸透施設を今後どうするべきかという観点で、平成２１年度検討いたしたものでございまして、決算上の３４５万１,４０５円の中には助成はゼロ件、あとは。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、要綱に基づいた指導件数、これが平成２１年度からさかのぼって、４６件、６６件、８０件と平成１９年度まで直近の指導が行われております。この指導によって、実際に設置に至った施設、大規模、中規模施設というのはどのぐらいあったのかをお聞かせいただきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"実績については、平成２１年度４６件、平成２０年度６６件、指導した実績というのは、これに基づいて実際指導してついた件数を計上しています。","id":"exchange-111"},{"speaker":"若林委員","kind":"質問","question":"要綱にのっとって、適正に民間の方もやられていると理解をいたしました。一方、助成制度について、平成１９年度から２件、平成２０年、平成２１年とゼロ件です。実際に要綱外のいわゆる小規模施設、それから民間の個人住宅、これは実際にどのような工事内容になるのでしょうか。ちょっと教えてください。","respondent":"藤橋都市整備下水道課長","answer":"そこで、宅地内の降った雨を、下水道に入る前に、宅地内に雨水の浸透ますをつくっていただいて、そこで１回浸透させた上で、下水道管に流してほしいという指導でございまして、そうすることによって下水道への負荷が減るので。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"これは今後、これからゲリラ豪雨ということも、これは大きくまた東京都等の対応があると思うんですが、ここら辺の今後のそういう豪雨、また現状、品川区、東京都でもいろいろ委託を受けながら、さっきの戸越幹線とかという、そういう対策も進めている中で、民間への助成のあり方というのは、今どのように考えられているのか、お聞かせいただきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"なかなか宅地内に、いわゆる密集した家屋の中で、１m2ぐらいの土地の中にますをつくらなければいけないものですから、そういったことがなかなか難しいというのが区内の実情だと私どもも分析しておりまして、今後抜本的な見直しを行っていきたいと考えています。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問","question":"そうすると、今の都の検討があって、その検討を待って区も検討するという理解でよろしいでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"東京都と連携した施策ができないかということを現在検討しています。","id":"exchange-114"},{"speaker":"須藤委員","kind":"質問","question":"１６２ページの駅周辺等放置自転車対策費について。駅周辺という表現は駅から何ｍぐらいまでを駅周辺と称するのか教えてください。それから、駅周辺の中で、私道の中にとめられていると、なかなか行政としては撤去できないという話をよく聞くんだけれども、その場合にはどういう対応をしたらいいのか教えてください。何らかの費用が返還するなりかかるのかどうか、そのあたりを教えてください。","respondent":"藤木交通安全担当課長","answer":"おおむね２００ｍぐらいということで考えておりますけれども、駅といいましても、ターミナル駅、あとは東急の駅、いろいろありますので、その実態に応じた範囲で放置禁止区域を指定いたしまして、撤去活動等をやっているところです。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"それから１６４ページの道路新設改良費に関連して、補助２６号線は都道ですから、今直接ここにはないんだけれども、新しい道路ができますといったときに、よく理事者の皆さんは、品川区は交通網が非常に発展しているという話をするんだけれども、小山のほうから例えば役所へ行きましょうといったときには、電車に乗ってきても、大岡山に出て回ってこなければならないというような形になるので。","respondent":"松代都市計画課長","answer":"今委員から出ましたように、道路ネットワーク、我々は非常に重要なものだと考えています。その根幹的なものとしての都市計画道路、これがまず整備を進めなければいけないと考えています。これは区だけでなくて、東京都も同じように進めております。","id":"exchange-116"},{"speaker":"須藤委員","kind":"確認","question":"補助２６号線も最初の予定より随分遅れるというような話ですが、もう１回確認で、遅れてきているのは、政権が変わって、国がいろいろ道路の費用を削減している。そんなことでいろんな地方行政も、そのあたりが大変だという話もちらほら聞いているんだけど、今言ったように、３０年というのがどうかなと思うので、そのあたりいかがですか。","respondent":"松代都市計画課長","answer":"その整備状況とあわせて、その後のことを想定しますと、平成２７年の少し後に完成するのではないかというのが我々が今思っているところでございまして、それまでの間には完成するということを前提に、いろいろさまざまな計画を私どもも持っていかなければいけない。","id":"exchange-117"},{"speaker":"須藤委員","kind":"質問・要望","question":"いずれにしても、交通網を新しくつくるということには、ある程度、我々が先を読んで、こういう道路ができればここに交通網ができるというようなことを考えながら、関係機関に働きかけていかなければいけないと思うので、そのあたりも頭に入れといていただきたいと思います。東京電力と連携をして電柱も危険な度合いというか、何年かたったら交換しているという仕組みがあるのかどうか教えてください。","respondent":"井浦土木管理課長","answer":"私ども、年に４回、東京電力あるいは東京ガスという公共事業者と連絡会を行っておりますので、その中で、老朽化した、いわゆる経年対策と申しますが、法定耐用期間が過ぎているもののつけかえについての計画というものについては、東京電力、東京ガスに密接に連絡をしながら。","id":"exchange-118"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、何かちょっと違うんじゃないかな。理解は、いいですよという、工事が入るけどということならいいけど、財政的な理解まで求める必要というのは必要なんだろうか。むしろ、私は、行政自体がそういうものの責任でやっていくということが必要だろうと思うんですがいかがでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"その場合については、グレードアップ分については、地域の方に一定のご負担をいただいた上での整備という形を考えておりますので、電線類を地中化する施設、あるいは電柱を取り除く費用等につきましては、全額行政側で負担することとしております。","id":"exchange-119"},{"speaker":"須藤委員","kind":"質問・要望","question":"ただ、プラスアルファの道路の形状はこうしたいとかという要望がそのときに一緒にあれば、そういう負担は商店街にお願いしますという話になろうかと思うんですけれども、そういう意識でいいのかどうかをもう一度確認しておきますけれども、それでよろしゅうありますか。","respondent":"藤橋都市整備下水道課長","answer":"委員のご指摘のとおりですので、私どもとしては、今後商店街等については、丁寧に説明してまいりたいと考えております。","id":"exchange-120"},{"speaker":"須藤委員","kind":"質問・要望","question":"同じ１６５ページの道路新設改良費と１６８ページの公園新設改良費で、荏原町公園前緑道復旧工事設計委託、それから、同じように荏原町公園復旧工事実施設計ということがあるんだけれども、これは、荏原町公園のところなので、一緒に設計委託とか、そういうのをやっているのかどうかということと、それから、いつごろまでに実際に公園化、あるいは道路化ができるのか、教えてください。","respondent":"藤橋都市整備下水道課長","answer":"その後、そこの公園の復旧と緑道の復旧を区が行うという形になりましたので、その設計を公園と緑道部分、分けて行ってまいりました。今後につきましては、下水道工事はもう終わっていますので、私どもで復旧工事にこれから入って、年度末までに完成させる予定で進めてまいります。","id":"exchange-121"},{"speaker":"須藤委員","kind":"質問・要望","question":"一緒に説明が来ていたのも、私、知っているんですけれども、緑道については復旧工事設計委託という表現で、それから、公園については、復旧工事実施設計という表現になっているんだけれども、この辺は今、東京都から委託されたという説明で、公園についてはうちが自主的にやるから実施設計という表現の出し方でいいのかどうかということと、それから、この間、相当な期間。","respondent":"藤橋都市整備下水道課長","answer":"事業が終わった後の対応ですけれども、今、東京都下水道局と話をしているのは、第二立会川幹線の貯留自体が今年度から行っているところでございまして、９月の雨のときにも貯留を初めてしたという状況で、ただ。","id":"exchange-122"},{"speaker":"須藤委員","kind":"質問・要望","question":"まちの人たちもそのあたり、特に商店街なんかも、何らかのイベントを一緒にやりたいというようなことがあるので、日程的なものがはっきりしましたら、ぜひ早めに商店街とか地元の方にご連絡をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"土井委員","kind":"質問・要望","question":"それともう一つは、１６７ページの河川費、河川総務費の中にあります同事務用経費についてお伺いをいたします。先日道路大会が開かれました。そこに入っているのがなぜかという質問はしません。問題は、この大会等をどう考えるかということをお聞かせをいただきたいと思います。この辺をどうお考えになっているのか。だから、そういう形の中でのこの大会のとらえ方も含めてどうお考えかをお聞かせください。","respondent":"松代都市計画課長","answer":"今、委員からも話がありましたように、東京都内の６２市区町村すべてが参加した、主催者としてやってあります。ここでは、今、目的に言いましたように、我々品川区においても、一番区民の生活に重要な道路というところで、道路の整備促進を図る。","id":"exchange-124"},{"speaker":"土井委員","kind":"質問","question":"だから、そうすると、この大会に出席するのは、区市町村がやるんですから、二元代表制ですから、それはそれでいいでしょうということになるのかもしれませんけれども、でも、それをチェックするのは我々の役目でもあるので、それはちょっと今チェックするかどうかは別にいたしまして、そういう形で決まってきたものじゃありませんかということなんです。そうすると、これをこれからも続けるんですか。","respondent":"松代都市計画課長","answer":"これは主催をする６２市区町村から、大会規約の中で定められています実行委員会をもってこの大会を運営するべく進めております。そこから正式に各市区町村の区長、または議長あてにこの大会の参加ということで、正式にその都度出しております。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問","question":"河川費はできないので、ここだけにしますけれども、要するに、今のお話でいくと、一応区の議会には議長あてにお願いをしているんだ。出てくる、出てこないは、議会のせいだと、こうおっしゃるんでしょう。そういうことでしょう。それでよろしいんですね。来年もお頼みされるおつもりですか。それで、議会がどうするか決めればいいですね。そういうことでよろしいんですか。","respondent":"本間副区長","answer":"ただいまご答弁させていただいたとおり、すべての都内の構成する市区町村の実行委員会からの要請に基づいているですので、次年度も実行委員会からの要請があれば、それに基づいてのご判断ということになろうかと思います。","id":"exchange-126"},{"speaker":"土井委員","kind":"質問・要望","question":"どう参加をしていいのか。だから、そこら辺をこれからもしっかり実行委員会でこう決めて、こう論議して、部課長の方がやってやることになっているんですから、それをしっかりと発表できるようにしといていただかなければどうにもならないじゃないですか。そのことだけはやっぱりこれから来年はしっかり改善をしていただきたい、このように思います。いかがでしょうか。","respondent":"本間副区長","answer":"快適な都市環境をつくるのは区民すべての願いです。それを……。","id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"１６２ページ、土木管理費、とりわけ駅周辺等放置自転車対策費、そして道路行政全般にわたって質問いたします。多分ご承知のことと思います。運輸部門で発生しているＣＯ２の９割は道路を通行する自動車から出ている。したがって、道路行政の責任は大きいとそこでも指摘をしています。こういう状況をこのまま続けていっていいのかどうか、まずそこの認識を伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"引き続き自転車の駐輪場の整備、指導啓発、あと撤去活動、これが区のやっている放置自転車対策の３本柱ですので、現在の考えとしましては、これにのっとって、引き続きやっていくと考えております。","id":"exchange-128"},{"speaker":"南委員","kind":"質問","question":"決して少なくない税金をかけて、なかなか改善が見込めない、こういう状況では私は本当に問題ではないかと思うんですね。自転車はエコな乗り物と言われておりますけれども、そういう認識があるかどうか、そこもまず伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"製造から廃棄まで一連の作業を含めますと、エコではないと言う学者も最近はいらっしゃいますが、自動車のように排気ガスを出さないということで、その面ではエコな乗り物だと考えておりますけれども、歩くほうがよりエコではないかです。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"確かに歩くほうがＣＯ２は排出しません。ただ、相互乗りかえですから、どこかに、乗り捨てという言葉がいいのかどうかあれですけれども、どこかに行って、そこでおりる。そういう時代ですので、本格的にこのシェアリングというのも、区が検討するべき、そういう時期に来ているんじゃないかなと思うので、まずその見解をひとつ伺いたいと思います。そこで、改めてこの問題についても見解を伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"１点目の自転車のシェアリングにつきましてです。当区では現在のところは、道路環境などから、自転車については自粛ということでお願いしておりまして、具体的な検討は行ってはおりませんが、いろいろ他区の情勢など、調査、研究等はしています。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひシェアリングのほうは検討していただきたいと思います。違うんでしょうか。その辺の位置づけについて改めて伺いたいと思います。そういう点で、私は、区民のこの時代の高齢化社会の社会的弱者をどうやって救おうかという、そういうことが行政に求められている時代に、しっかりと検討していくべき課題ではないかなと思いますので、改めてその点についても見解を伺いたいと思います。","respondent":"松代都市計画課長","answer":"バス路線に当たっては、４９系統、１１４のバス停が区内にあります。これが他区とは大きく違うというところをまずご認識いただきたいというところと、１９区が今は実施しているようですけれども、私どもの調べる範囲では、各区、採算性で非常に苦労していると聞いております。","id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"区内には４０の駅があると、そして１５分程度で歩いていけるという、こういうお話なんですね。それは現実ですから、そうです。しかし、区のレベルで生半可な気持ちで交通に取り組むべきじゃない、こういうふうにおっしゃっているんです。しかし、採算性、経済性というのを調べているということなので、どの程度調べられて、どういうふうな結果が導き出されたのか、ぜひそこは受けたいと思います。","respondent":"松代都市計画課長","answer":"そういうケースは、いろいろと今実施している１９区、いろいろとほかの区で発表しているものをとってみたり、一番身近なところでは、目黒区がコミュニティバスの検討報告書というのを平成１９年に出しています。","id":"exchange-132"},{"speaker":"南委員","kind":"意見","question":"私は具体的に、今ご答弁されたこと、２回おっしゃったけれども、具体的にどういうことかわかりません。目黒区を引っ張ってきて、目黒区は唯一で２３区の中で実施しないということを決めた区だと聞いておりますけれども、そこを持ってきて同じだと言うのは、私はこれは正確な答弁じゃないと思うんですね。品川区で検討して、どういうふうに採算が合わなかったのか。そこをもう１回言ってください。","respondent":"松代都市計画課長","answer":"自分のできれば生活する身近に来てほしい。そういったものを一応要望されていますし、それがまた満足されることだと思います。それを実際走らせますと、非常に難しいですし、それが費用的にも、１億円とか、そういった形で負担としてなっているです。","id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"私はそれは目黒の検討であって、やっぱりそれを引いてきたものであって、やっぱり品川区民の皆さんの声を聞くべきですよ。強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"三上委員","kind":"質問","question":"１６４ページの道路改良費、１７０ページの武蔵小山駅周辺地域整備事業についてお伺いしたいと思います。最初に道路改良費の件ですが、これ、２点お伺いしたいと思います。１つは、小山台二丁目で、林試の森公園の南口があります。ですから、そこのところは、通称月光プロムナードという目黒区がつけた通りになっている。商店街の一等地の入り口のところに。簡単でいいですからお願いしたいと思います。","respondent":"松代都市計画課長、藤木交通安全担当課長、矢部生活安全担当課長、三宅都市開発課長","answer":"その予定がありますので、そのことを盛り込んだ上で、都市計画等の変更をし、かつ、今暫定的に道路を整備したところ、そこをしっかりと位置づけて。時間帯につきましては、今回９時半ということでやっていただきましたけれども、今後は、より効果的な時間帯となるように。これにつきましては、議員ご指摘のとおり、最初のときには、確かに商店街の出入り口の真ん前に置いてあったんですけれども。","id":"exchange-135"},{"speaker":"三上委員","kind":"質問・要望","question":"そうなると、交通事故のもとになるという現状を考えたら、安全を考えるという、その視点から、しっかりそれは取り組んでいっていただきたいと思います。それから、武蔵小山の放置自転車のキャンペーンについては、地元としては協力すると言っているわけですから、ぜひ一番効果的な時間帯をご検討していただいて、お願いしたいと思います。それから、灰皿の件はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"２点お聞きします。成果報告書の１６４ページ、補助１６３号線整備についてと、同じく１６４ページの細街路拡幅整備事業、隣のページの１６５ページ、道路バリアフリー事業。大きな事業費、この年度使っていますけれども、それの内容と細街路整備拡幅事業と道路バリアフリー事業、その理念というんでしょうか、その精神というのはどういうものかということについてお聞きしたいと思います。","respondent":"中村建築課長、齋藤道路公園課長","answer":"奨励金、これはセットバックした部分、区道などに面したところに伴いました１m2当たり１０万円の奨励金、お礼金を出しております。これは５件ということになっております。続きまして、道路バリアフリー事業についてご説明を申し上げます。これは、側道の段差解消、歩道の平坦化、視覚障害者用の誘導ブロックの設置をすることが中身です。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"細街路拡幅整備事業については、本会議の質問でも、この委員会の中でもたくさん出ています。虚空蔵様ということで皆さん知っていると思うんですけれども、そこが敷地を囲い込んでしまっているんですね。近隣の方からも、大変にお年寄りから危ないという苦情が来ているし、町会長からもお話がいったと思うんですが、その現状についてちょっとお伺いしたいと思います。","respondent":"中村建築課長","answer":"完全に段差がない部分といたしましては、この境内のわきを通る、通過する公道部分、区道部分があります。こちらも段差なく通行ができるということで、現在問題ないと考えております。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"これが昭和４４年ですか、官民査定ということは、あそこに区境というような形でびょうを打ってありますよね。ところが、今、囲い込みをして、６cmの段差ができて、歩道化されている。１.８ｍですよ。今話になっている細街路整備の基本からすれば、中心線から２ｍ下がらなければいけない。これが違法性がないからといって、何もできないんですか。そのことについてお答えいただきたい。","respondent":"中村建築課長","answer":"これも建築確認の記録が現在までないために、２項道路としての判断は未判定です。縁石につきましても、これは建築物ではありませんので、現在のところは、道路のふち石といったものについては、セットバックについて対応することはできません。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんなことで通るんですか。そうであれば、先ほども言いましたけれども、細街路拡幅整備事業の精神、何ですか。それを何にもできない。いいですか。１.８ｍの区道は下がらないまま。中心線から２ｍ下がってくださいというお話をして道路上に直さなかったら、一生、１００年、２００年、１.８ｍの区道は広がらないんですよ。４ｍなければいけない道路が、ここは私有地ですからって段差をつけられている。","respondent":"片田防災まちづくり事業部長","answer":"ただ、先ほど申し上げましたように、私有地の権限について相手方はそういうお話をしていますので、一応私どもも、法的な規制がかけられるかどうか、まず２項道路の調べをさせていただかなければいけませんし、なおかつ、そういう段差の問題についても。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"検討していきたいと思うというのは、できるということでいいですね。あそこは２項道路に決まっているんですから。官民査定でびょうを打って、１.８ｍ。道路でも区道と書いてありますよ。区道ではないのですか。","respondent":"片田防災まちづくり事業部長","answer":"今、検討というのは、２項道路かどうかの一応ヒアリングをかけたりして、まず調査をさせていただきたいです。逆にもしできるとすれば、法的なそういう扱いがあれば、当然そういう指導を行っていきます。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"期待していますよ。やった得にならないように。本当にね。１.８ｍしかない現状、しっかり見てくださいね。やらなかったら、私が議員でいる限り、何回でも本会議でも質問しますので、よろしくお願いします。課長、予算特別委員会のときに、何としても２３年度までには完成させますと見えを切ったんですけれども、今現在の進捗状況と、２３年、必ず完成するのかどうか、その辺をお聞きしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"１０月に地域の方々への説明会を行った際も、平成２３年度末の完成を目指して取り組みますという話をさせていただきました。電線類地中化工事に引き続き、平成２３年度には上空から各建物へつながっている電線類の地中の配線への切りかえを行います。","id":"exchange-142"},{"speaker":"松澤委員","kind":"質問","question":"午前中も質問がありましたけれども、大変に道路をほっくり返されたり、曲がったりして、危険なところですので、いよいよ２３年には完成するのかなと思っていますけれども、あれをもって補助１６３号線の完成ではないですよね。あれができたからといったって、本来はガードの拡幅がなくてはならない。区庁舎の側の補助１６３号線の整備、それの計画はどのようになっているのでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"補助１６３号線におきましては、未整備区間１,５６９ｍあります。そのうちの現在５４９ｍを対象に事業を実施しているところでございまして、残りの部分がかなりまだあります。","id":"exchange-143"},{"speaker":"松澤委員","kind":"意見","question":"わかりました。当然のことながら、そのように計画をしている、申請をしているということですと、ガードの形状もある程度決まっていると思うんですけれども、どのような形、例えば何車線になるのか、ガードの形状はどうなのか。あのままでいいのかどうか、その辺のガードの未来図といいますか、その辺を話していただければと思います。","respondent":"藤橋都市整備下水道課長","answer":"その前段階の都市計画法の認可をもらうための作業を行っているという状況ですので、昨年度の段階で東急大井町線との交差する部分について、どのような事業の仕方があるかということで、幾つか比較検討は行いましたけれども、まだ結論には至っておりません。","id":"exchange-144"},{"speaker":"松澤委員","kind":"質問","question":"そうでないと、五反田駅ではないですが、車がクレーン車とぶつかったりしてはいけないというので、道路をガードを上げるというんですか、薄くするというんですかね、それでは間に合わないから、おそらく傾斜をして、少し山盛りにするのかななんていうように思っているんですけれども、そういう話も漏れ承っているんですけれども、そういう話は決まってないからできないということなんですか。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる東急大井町線を少し上げる形での検討を比較検討の中では行いましたが、それに必要な財源が数十億円かかるということから、財源の確保も含めて東京都と調整しているという状況です。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/696113?Template=document&Id=1332#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":114940,"voices":348}}]);
